    pub fn clear_runtime(&mut self, cx: &mut Context<Self>) {
        self.clear_agent_auth_terminal(cx);
        self.runtime = None;
        self.backend = None;
        self.generation = self.generation.saturating_add(1);
        self.loading = false;
        self.details_ready = false;
        self.refresh_pending = false;
        self.agent_install_refresh_task = None;
        self.agent_auth_generation = self.agent_auth_generation.saturating_add(1);
        self.agent_auth_loading = false;
        self.agent_auth_scope = None;
        self.agent_auth_catalog = None;
        self.agent_auth_context = None;
        self.agent_auth_model_catalog = None;
        self.agent_auth_logout_preview = None;
        self.agent_auth_reauthentication = false;
        self.agent_auth_error = None;
        self.agent_auth_inputs.clear();
        self.agent_auth_clear_values.clear();
        self.discover_agents_after_refresh = false;
        self.mcp_import_open = false;
        self.skill_import_open = false;
        self.mcp_discovery = None;
        self.skill_discovery = None;
        self.native_export_preview = None;
        self.native_import_preview = None;
        self.notice = Some(
            management_locale_text(
                "Management runtime is not connected",
                "配置中心运行时未连接",
                "配置中心執行階段未連線",
            )
            .to_string(),
        );
        cx.notify();
    }

    pub fn request_local_agent_discovery(&mut self, cx: &mut Context<Self>) {
        self.navigation.active = ManagementSection::Agents;
        self.discover_agents_after_refresh = true;
        if !self.loading {
            self.discover_agents_after_refresh = false;
            self.discover_local_agents(cx);
        } else {
            cx.notify();
        }
    }

    pub fn show_agent_authentication(&mut self, agent_id: AgentId, cx: &mut Context<Self>) {
        self.navigation.active = ManagementSection::Agents;
        let agent_id = agent_id.as_str().to_string();
        if self.selected_agent_id.as_deref() == Some(agent_id.as_str()) {
            self.selected_provider_profile_id = None;
            self.load_agent_auth(true, cx);
        } else {
            self.select_management_agent(agent_id, cx);
        }
        cx.notify();
    }

    pub fn set_pairing_context(
        &mut self,
        workspace: Option<String>,
        workspace_id: Option<vibex_core::WorkspaceId>,
        session_id: Option<String>,
        mode: impl Into<String>,
        cx: &mut Context<Self>,
    ) {
        let default_scope_changed = self.pairing_workspace_id != workspace_id;
        self.pairing = PairingContextProjection::new(workspace, session_id, mode);
        self.pairing_workspace_id = workspace_id;
        if default_scope_changed && self.runtime.is_some() {
            self.refresh(cx);
        } else {
            cx.notify();
        }
    }

    fn current_workspace_context(&self) -> Option<(String, WorkspaceMode)> {
        if let Some(workspace) = self
            .pairing
            .workspace
            .as_ref()
            .filter(|workspace| !workspace.trim().is_empty())
        {
            let mode = if self.pairing.mode == "vibex_worktree" {
                WorkspaceMode::VibexWorktree
            } else {
                WorkspaceMode::CurrentCheckout
            };
            return Some((workspace.clone(), mode));
        }
        self.snapshot
            .graphs
            .first()
            .map(|graph| (graph.workspace_root.clone(), graph.workspace_mode))
            .or_else(|| {
                self.snapshot
                    .scheduled
                    .first()
                    .map(|task| (task.workspace_root.clone(), task.workspace_mode))
            })
            .filter(|(workspace, _)| !workspace.trim().is_empty())
    }

    fn select_management_agent(&mut self, agent_id: String, cx: &mut Context<Self>) {
        if self.selected_agent_id.as_deref() == Some(agent_id.as_str()) {
            return;
        }
        self.custom_agent_editor_open = false;
        self.selected_agent_id = Some(agent_id);
        self.selected_provider_profile_id = None;
        self.selected_acp_profile_id = None;
        self.acp_config_draft = None;
        self.native_export_preview = None;
        self.sync_projection_editor();
        self.load_agent_auth(false, cx);
        self.schedule_agent_install_refresh(cx);
        cx.notify();
    }

    fn select_provider_profile(&mut self, profile_id: String, cx: &mut Context<Self>) {
        if self.selected_provider_profile_id.as_deref() == Some(profile_id.as_str()) {
            return;
        }
        self.selected_provider_profile_id = Some(profile_id);
        self.selected_acp_profile_id = None;
        self.acp_config_draft = None;
        self.native_export_preview = None;
        self.sync_projection_editor();
        cx.notify();
    }

    fn current_agent_auth_scope(&self) -> Option<(String, Option<String>)> {
        let agent_id = self.selected_agent_id.as_ref()?;
        self.snapshot.agents.iter().find(|agent| {
            agent.id.as_str() == agent_id
                && agent.added
                && agent.enabled
                && !management_agent_installation_pending(agent.added, &agent.managed_install)
        })?;
        Some((agent_id.clone(), None))
    }

    fn load_agent_auth(&mut self, force: bool, cx: &mut Context<Self>) {
        let Some(scope) = self.current_agent_auth_scope() else {
            self.agent_auth_generation = self.agent_auth_generation.saturating_add(1);
            self.agent_auth_scope = None;
            self.agent_auth_catalog = None;
            self.agent_auth_context = None;
            self.agent_auth_model_catalog = None;
            self.agent_auth_logout_preview = None;
            self.agent_auth_reauthentication = false;
            self.agent_auth_loading = false;
            self.agent_auth_error = None;
            self.agent_auth_inputs.clear();
            self.agent_auth_clear_values.clear();
            self.clear_agent_auth_terminal(cx);
            cx.notify();
            return;
        };
        if self.agent_auth_scope.as_ref() == Some(&scope)
            && self.agent_auth_terminal_state == Some(AgentAuthTerminalState::Running)
        {
            return;
        }
        if !force
            && self.agent_auth_scope.as_ref() == Some(&scope)
            && (self.agent_auth_loading || self.agent_auth_catalog.is_some())
        {
            return;
        }
        let Some(backend) = self.backend.clone() else {
            return;
        };
        let Ok(agent_id) = AgentId::parse(scope.0.clone()) else {
            return;
        };
        let scope_changed = self.agent_auth_scope.as_ref() != Some(&scope);
        self.agent_auth_generation = self.agent_auth_generation.saturating_add(1);
        let generation = self.agent_auth_generation;
        self.agent_auth_scope = Some(scope.clone());
        self.agent_auth_loading = true;
        self.agent_auth_error = None;
        if scope_changed {
            self.agent_auth_catalog = None;
            self.agent_auth_context = None;
            self.agent_auth_model_catalog = None;
            self.agent_auth_logout_preview = None;
            self.agent_auth_reauthentication = false;
            self.agent_auth_inputs.clear();
            self.agent_auth_clear_values.clear();
            self.clear_agent_auth_terminal(cx);
        }
        let entity = cx.weak_entity();
        let runner = gpui_tokio::Tokio::spawn(cx, async move {
            let context = backend
                .agent()
                .ensure_default_agent_auth_context(MutationRequest::new(agent_id.clone()))
                .await
                .map_err(crate::app::remote_error_into_vibex)?;
            let catalog = if force {
                backend
                    .agent()
                    .refresh_agent_auth_methods(MutationRequest::new(agent_id))
                    .await
                    .map_err(crate::app::remote_error_into_vibex)?
            } else {
                backend
                    .agent()
                    .list_agent_auth_methods(agent_id)
                    .await
                    .map_err(crate::app::remote_error_into_vibex)?
            };
            Ok::<_, VibexError>((catalog, Some(context)))
        });
        self.agent_auth_task = Some(cx.spawn(async move |_, cx| {
            let outcome = runner.await;
            let _ = entity.update(cx, |this, cx| {
                if this.agent_auth_generation != generation
                    || this.agent_auth_scope.as_ref() != Some(&scope)
                {
                    return;
                }
                this.agent_auth_loading = false;
                match outcome {
                    Ok(Ok((catalog, context))) => {
                        let reauthentication_still_available =
                            context.as_ref().is_some_and(|context| {
                                context.status == AgentAuthContextStatus::Authenticated
                            }) && agent_auth_catalog_supports_reauthentication(&catalog);
                        this.agent_auth_catalog = Some(catalog);
                        this.agent_auth_context = context;
                        this.agent_auth_logout_preview = None;
                        if !reauthentication_still_available {
                            this.agent_auth_reauthentication = false;
                        }
                        this.agent_auth_error = None;
                        this.agent_auth_inputs.clear();
                        this.agent_auth_clear_values.clear();
                    }
                    Ok(Err(error)) => {
                        this.agent_auth_catalog = None;
                        this.agent_auth_context = None;
                        this.agent_auth_reauthentication = false;
                        this.agent_auth_error = Some(format!("{}: {}", error.code, error.message));
                    }
                    Err(error) => {
                        this.agent_auth_catalog = None;
                        this.agent_auth_context = None;
                        this.agent_auth_reauthentication = false;
                        this.agent_auth_error = Some(format!(
                            "{}: {error}",
                            management_error_text(
                                "Authentication discovery failed",
                                "认证方式发现失败",
                                "驗證方式探索失敗",
                            )
                        ));
                    }
                }
                cx.notify();
            });
        }));
        cx.notify();
    }

    fn ensure_agent_auth_inputs(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        if self.selected_provider_profile_id.is_none() {
            self.agent_auth_inputs.clear();
            self.agent_auth_clear_values.clear();
            return;
        }
        let specs = self
            .agent_auth_catalog
            .as_ref()
            .into_iter()
            .flat_map(|catalog| catalog.methods.iter())
            .filter(|method| method.kind == AgentAuthMethodKind::Environment)
            .flat_map(|method| {
                method.environment.iter().map(move |variable| {
                    (
                        agent_auth_input_key(&method.id, &variable.name),
                        variable.secret,
                        variable.configured,
                    )
                })
            })
            .collect::<Vec<_>>();
        let active_keys = specs
            .iter()
            .map(|(key, _, _)| key.clone())
            .collect::<BTreeSet<_>>();
        self.agent_auth_inputs
            .retain(|key, _| active_keys.contains(key));
        self.agent_auth_clear_values
            .retain(|key| active_keys.contains(key));
        for (key, secret, configured) in specs {
            if self.agent_auth_inputs.contains_key(&key) {
                continue;
            }
            let placeholder = if configured {
                management_locale_text(
                    "Configured - leave blank to keep",
                    "已配置，留空则保持不变",
                    "已設定，留空則保持不變",
                )
            } else {
                management_locale_text("Enter value", "输入凭据", "輸入憑證")
            };
            let input = cx.new(|cx| {
                InputState::new(window, cx)
                    .placeholder(placeholder)
                    .masked(secret)
            });
            let input_for_subscription = input.clone();
            let key_for_subscription = key.clone();
            self._subscriptions
                .push(cx.subscribe(&input, move |this, _, _: &InputEvent, cx| {
                    if !input_for_subscription.read(cx).value().trim().is_empty() {
                        this.agent_auth_clear_values.remove(&key_for_subscription);
                    }
                    cx.notify();
                }));
            self.agent_auth_inputs.insert(key, input);
        }
    }

    fn toggle_agent_auth_clear(&mut self, key: String, cx: &mut Context<Self>) {
        if !self.agent_auth_clear_values.remove(&key) {
            self.agent_auth_clear_values.insert(key);
        }
        cx.notify();
    }

    fn begin_agent_reauthentication(&mut self, cx: &mut Context<Self>) {
        let can_reauthenticate = self
            .agent_auth_context
            .as_ref()
            .is_some_and(|context| context.status == AgentAuthContextStatus::Authenticated)
            && self
                .agent_auth_catalog
                .as_ref()
                .is_some_and(agent_auth_catalog_supports_reauthentication);
        if !can_reauthenticate {
            return;
        }
        self.agent_auth_logout_preview = None;
        self.agent_auth_reauthentication = true;
        self.agent_auth_error = None;
        self.clear_agent_auth_terminal(cx);
        cx.notify();
    }

    fn cancel_agent_reauthentication(&mut self, cx: &mut Context<Self>) {
        self.agent_auth_reauthentication = false;
        cx.notify();
    }

    fn authenticate_agent_context(
        &mut self,
        method_id: String,
        scope: (String, Option<String>),
        cx: &mut Context<Self>,
    ) {
        let (Some(backend), Some(context), Some(method)) = (
            self.backend.clone(),
            self.agent_auth_context.clone(),
            self.agent_auth_catalog.as_ref().and_then(|catalog| {
                catalog
                    .methods
                    .iter()
                    .find(|method| method.id == method_id)
                    .cloned()
            }),
        ) else {
            return;
        };
        if method.effect == AgentAuthMethodEffect::RequiresProviderProfile {
            self.agent_auth_error = Some(
                management_error_text(
                    "This sign-in method requires a model provider configuration",
                    "此登录方式需要模型供应商配置",
                    "此登入方式需要模型供應商設定",
                )
                .to_string(),
            );
            cx.notify();
            return;
        }
        let agent_id_key = context.agent_id.as_str().to_string();
        if self.mutation.is_some() || self.agent_mutations.contains_key(&agent_id_key) {
            return;
        }
        let generation = self.agent_auth_generation;
        let operation_id = AgentAuthenticationOperationId::new();
        let mutation = ManagementMutation::AgentAuth {
            agent_id: agent_id_key.clone(),
            action: method.id.clone(),
        };
        self.agent_mutations
            .insert(agent_id_key.clone(), mutation.clone());
        self.agent_auth_operations.insert(
            agent_id_key.clone(),
            AgentAuthPendingOperation {
                operation_id: operation_id.clone(),
                scope: scope.clone(),
                method_id: method.id.clone(),
                phase: AgentAuthOperationPhase::Running,
                auth_context: Some((context.id.clone(), context.revision)),
            },
        );
        self.agent_auth_logout_preview = None;
        self.agent_auth_error = None;
        let active_locale = locale::current_locale();
        let entity = cx.weak_entity();
        let backend_for_callback = backend.clone();
        let Some(transport_for_callback) = self.terminal_transport.clone() else {
            return;
        };
        let scope_for_callback = scope.clone();
        let operation_id_for_request = operation_id.clone();
        let operation_id_for_callback = operation_id.clone();
        let runner = gpui_tokio::Tokio::spawn(cx, async move {
            backend
                .agent()
                .authenticate_agent_context(MutationRequest::new(
                    AgentAuthContextAuthenticateRequest {
                        operation_id: operation_id_for_request,
                        auth_context_id: context.id,
                        expected_context_revision: context.revision,
                        method_id: method.id,
                    },
                ))
                .await
                .map_err(crate::app::remote_error_into_vibex)
        });
        let completed_mutation = mutation;
        let agent_id_for_callback = agent_id_key.clone();
        let task = cx.spawn(async move |_, cx| {
            let outcome = runner.await;
            let _ = entity.update(cx, |this, cx| {
                let operation_is_registered = this
                    .agent_auth_operations
                    .get(&agent_id_for_callback)
                    .is_some_and(|operation| operation.operation_id == operation_id_for_callback);
                let scope_is_current = agent_auth_scope_matches(
                    this.agent_auth_generation,
                    this.agent_auth_scope.as_ref(),
                    generation,
                    &scope_for_callback,
                );
                let interactive = matches!(
                    &outcome,
                    Ok(Ok(result)) if result.terminal.is_some()
                );
                if operation_is_registered && !(interactive && scope_is_current) {
                    this.agent_auth_operations.remove(&agent_id_for_callback);
                }
                if this.agent_mutations.get(&agent_id_for_callback) == Some(&completed_mutation) {
                    this.agent_mutations.remove(&agent_id_for_callback);
                }
                if !operation_is_registered || !scope_is_current {
                    if let Ok(Ok(result)) = &outcome
                        && let Some(terminal_id) = result
                            .terminal
                            .as_ref()
                            .and_then(|terminal| terminal.terminal_id.clone())
                    {
                        let transport = transport_for_callback.clone();
                        std::mem::drop(gpui_tokio::Tokio::spawn(cx, async move {
                            let _ = transport.close_terminal(&terminal_id).await;
                        }));
                    }
                    cx.notify();
                    return;
                }
                match outcome {
                    Ok(Ok(result)) => {
                        this.agent_auth_context = Some(result.context);
                        this.agent_auth_model_catalog = result.model_catalog;
                        this.agent_auth_error = None;
                        let terminal_id = result
                            .terminal
                            .as_ref()
                            .and_then(|terminal| terminal.terminal_id.clone());
                        if let Some(terminal) = result.terminal {
                            this.clear_agent_auth_terminal(cx);
                            this.agent_auth_terminal = Some(terminal);
                            if let Some(terminal_id) = terminal_id {
                                this.start_agent_auth_context_terminal_monitor(
                                    backend_for_callback.clone(),
                                    transport_for_callback.clone(),
                                    scope_for_callback.clone(),
                                    generation,
                                    operation_id_for_callback.clone(),
                                    terminal_id,
                                    active_locale,
                                    cx,
                                );
                                this.notice = Some(
                                    management_locale_text_for(
                                        active_locale,
                                        "Interactive sign-in terminal opened",
                                        "交互式登录终端已打开",
                                        "互動式登入終端已開啟",
                                    )
                                    .to_string(),
                                );
                            } else {
                                this.agent_auth_terminal_state =
                                    Some(AgentAuthTerminalState::Failed);
                                this.agent_auth_error = Some(
                                    "agent_terminal_auth_terminal_missing: Interactive authentication terminal was not created"
                                        .to_string(),
                                );
                            }
                        } else {
                            this.agent_auth_reauthentication = false;
                            this.notice = Some(
                                management_locale_text_for(
                                    active_locale,
                                    "Default Agent account verified",
                                    "Agent 默认账号已验证",
                                    "Agent 預設帳號已驗證",
                                )
                                .to_string(),
                            );
                        }
                    }
                    Ok(Err(error)) if error.code == "agent_authentication_cancelled" => {
                        this.agent_auth_error = None;
                        this.notice = Some(
                            management_locale_text_for(
                                active_locale,
                                "Agent authentication stopped",
                                "已终止 Agent 登录认证",
                                "已終止 Agent 登入驗證",
                            )
                            .to_string(),
                        );
                    }
                    Ok(Err(error)) => {
                        this.agent_auth_error = Some(format!("{}: {}", error.code, error.message));
                    }
                    Err(error) => {
                        this.agent_auth_error = Some(format!(
                            "{}: {error}",
                            management_error_text(
                                "Authentication action failed",
                                "认证操作失败",
                                "驗證操作失敗",
                            )
                        ));
                    }
                }
                cx.notify();
            });
        });
        self.agent_auth_operation_tasks
            .retain(|_, existing| !existing.is_ready());
        self.agent_auth_operation_tasks.insert(agent_id_key, task);
        cx.notify();
    }

    fn authenticate_agent(&mut self, method_id: String, cx: &mut Context<Self>) {
        if self.mutation.is_some() {
            return;
        }
        let Some(backend) = self.backend.clone() else {
            return;
        };
        let Some(scope) = self.current_agent_auth_scope() else {
            return;
        };
        if scope.1.is_none() {
            self.authenticate_agent_context(method_id, scope, cx);
            return;
        }
        let Some(method) = self
            .agent_auth_catalog
            .as_ref()
            .and_then(|catalog| catalog.methods.iter().find(|method| method.id == method_id))
            .cloned()
        else {
            return;
        };
        let Ok(agent_id) = AgentId::parse(scope.0.clone()) else {
            return;
        };
        let agent_id_key = agent_id.as_str().to_string();
        if self.agent_mutations.contains_key(&agent_id_key) {
            return;
        }
        let provider_profile_id = scope
            .1
            .as_ref()
            .and_then(|profile_id| vibex_core::ProviderProfileId::parse(profile_id.clone()).ok());
        if method.kind == AgentAuthMethodKind::Environment && provider_profile_id.is_none() {
            self.agent_auth_error = Some(
                management_error_text(
                    "Select or create a Provider configuration before saving environment credentials",
                    "请先选择或创建模型供应商配置，再保存环境凭据",
                    "請先選擇或建立模型供應商設定，再儲存環境憑證",
                )
                .to_string(),
            );
            cx.notify();
            return;
        }
        let values = method
            .environment
            .iter()
            .filter_map(|variable| {
                let key = agent_auth_input_key(&method.id, &variable.name);
                let value = self
                    .agent_auth_inputs
                    .get(&key)
                    .map(|input| input.read(cx).value().trim().to_string())
                    .filter(|value| !value.is_empty());
                let clear = self.agent_auth_clear_values.contains(&key);
                if variable.configured && value.is_none() && !clear {
                    return None;
                }
                Some(AgentAuthEnvironmentValue {
                    name: variable.name.clone(),
                    value,
                    secret: variable.secret,
                    optional: variable.optional,
                    clear,
                })
            })
            .collect::<Vec<_>>();
        let required_credential_cleared = values.iter().any(|value| value.clear && !value.optional);
        let generation = self.agent_auth_generation;
        let operation_id = AgentAuthenticationOperationId::new();
        let mutation = ManagementMutation::AgentAuth {
            agent_id: agent_id_key.clone(),
            action: method.id.clone(),
        };
        self.agent_mutations
            .insert(agent_id_key.clone(), mutation.clone());
        self.agent_auth_operations.insert(
            agent_id_key.clone(),
            AgentAuthPendingOperation {
                operation_id: operation_id.clone(),
                scope: scope.clone(),
                method_id: method.id.clone(),
                phase: AgentAuthOperationPhase::Running,
                auth_context: None,
            },
        );
        self.agent_auth_error = None;
        let active_locale = locale::current_locale();
        let entity = cx.weak_entity();
        let method_id_for_request = method.id.clone();
        let scope_for_callback = scope.clone();
        let backend_for_callback = backend.clone();
        let Some(transport_for_callback) = self.terminal_transport.clone() else {
            return;
        };
        let agent_id_for_monitor = agent_id.clone();
        let provider_profile_id_for_monitor = provider_profile_id.clone();
        let operation_id_for_request = operation_id.clone();
        let runner = gpui_tokio::Tokio::spawn(cx, async move {
            if method.kind == AgentAuthMethodKind::Environment && !values.is_empty() {
                backend
                    .agent()
                    .update_agent_auth_environment(MutationRequest::new(
                        AgentAuthEnvironmentUpdateRequest {
                            agent_id: agent_id.clone(),
                            provider_profile_id: provider_profile_id
                                .clone()
                                .expect("environment authentication profile was validated"),
                            method_id: method_id_for_request.clone(),
                            values,
                        },
                    ))
                    .await
                    .map_err(crate::app::remote_error_into_vibex)?;
            }
            if required_credential_cleared {
                let mut catalog = backend
                    .agent()
                    .refresh_agent_auth_methods(MutationRequest::new(agent_id.clone()))
                    .await
                    .map_err(crate::app::remote_error_into_vibex)?;
                catalog.status = AgentAuthStatus::AuthenticationRequired;
                return Ok::<_, VibexError>((catalog, None, true));
            }
            let result = backend
                .agent()
                .authenticate_agent(MutationRequest::new(AgentAuthenticateRequest {
                    operation_id: operation_id_for_request,
                    agent_id: agent_id.clone(),
                    provider_profile_id: provider_profile_id.clone(),
                    method_id: method_id_for_request,
                }))
                .await
                .map_err(crate::app::remote_error_into_vibex)?;
            let mut catalog = backend
                .agent()
                .refresh_agent_auth_methods(MutationRequest::new(agent_id.clone()))
                .await
                .map_err(crate::app::remote_error_into_vibex)?;
            catalog.status = if result.terminal.is_some() {
                AgentAuthStatus::Unknown
            } else {
                AgentAuthStatus::Authenticated
            };
            Ok::<_, VibexError>((catalog, result.terminal, false))
        });
        let completed_mutation = mutation;
        let agent_id_for_callback = agent_id_key.clone();
        let operation_id_for_callback = operation_id.clone();
        let task = cx.spawn(async move |_, cx| {
            let outcome = runner.await;
            let _ = entity.update(cx, |this, cx| {
                let operation_is_registered = this
                    .agent_auth_operations
                    .get(&agent_id_for_callback)
                    .is_some_and(|operation| operation.operation_id == operation_id_for_callback);
                let scope_is_current = agent_auth_scope_matches(
                    this.agent_auth_generation,
                    this.agent_auth_scope.as_ref(),
                    generation,
                    &scope_for_callback,
                );
                let interactive = matches!(
                    &outcome,
                    Ok(Ok((_, Some(terminal), _))) if terminal.terminal_id.is_some()
                );
                if operation_is_registered && !(interactive && scope_is_current) {
                    this.agent_auth_operations.remove(&agent_id_for_callback);
                }
                if this.agent_mutations.get(&agent_id_for_callback) == Some(&completed_mutation) {
                    this.agent_mutations.remove(&agent_id_for_callback);
                }
                if !operation_is_registered || !scope_is_current {
                    if let Ok(Ok((_, Some(terminal), _))) = &outcome
                        && let Some(terminal_id) = terminal.terminal_id.clone()
                    {
                        let transport = transport_for_callback.clone();
                        std::mem::drop(gpui_tokio::Tokio::spawn(cx, async move {
                            let _ = transport.close_terminal(&terminal_id).await;
                        }));
                    }
                    cx.notify();
                    return;
                }
                match outcome {
                    Ok(Ok((catalog, terminal, credential_removed))) => {
                        let terminal_started = terminal
                            .as_ref()
                            .is_some_and(|terminal| terminal.terminal_id.is_some());
                        this.agent_auth_catalog = Some(catalog);
                        this.agent_auth_error = None;
                        this.agent_auth_inputs.clear();
                        this.agent_auth_clear_values.clear();
                        if let Some(terminal) = terminal {
                            let terminal_id = terminal.terminal_id.clone();
                            this.clear_agent_auth_terminal(cx);
                            this.agent_auth_terminal = Some(terminal);
                            if let Some(terminal_id) = terminal_id {
                                this.start_agent_auth_terminal_monitor(
                                    backend_for_callback.clone(),
                                    transport_for_callback.clone(),
                                    scope_for_callback.clone(),
                                    generation,
                                    agent_id_for_monitor.clone(),
                                    provider_profile_id_for_monitor.clone(),
                                    operation_id_for_callback.clone(),
                                    terminal_id,
                                    active_locale,
                                    cx,
                                );
                            } else {
                                if let Some(catalog) = this.agent_auth_catalog.as_mut() {
                                    catalog.status = AgentAuthStatus::AuthenticationRequired;
                                }
                                this.agent_auth_terminal_state =
                                    Some(AgentAuthTerminalState::Failed);
                                this.agent_auth_error = Some(
                                    "agent_terminal_auth_terminal_missing: Interactive authentication terminal was not created"
                                        .to_string(),
                                );
                            }
                        }
                        this.notice = this.agent_auth_error.is_none().then(|| {
                            if credential_removed {
                                management_locale_text_for(
                                    active_locale,
                                    "Saved credential removed; sign-in is required",
                                    "已移除保存的凭据，需要重新登录",
                                    "已移除儲存的憑證，需要重新登入",
                                )
                            } else if terminal_started {
                                management_locale_text_for(
                                    active_locale,
                                    "Interactive sign-in terminal opened",
                                    "交互式登录终端已打开",
                                    "互動式登入終端已開啟",
                                )
                            } else {
                                management_locale_text_for(
                                    active_locale,
                                    "Agent authentication completed",
                                    "Agent 认证已完成",
                                    "Agent 驗證已完成",
                                )
                            }
                            .to_string()
                        });
                    }
                    Ok(Err(error)) if error.code == "agent_authentication_cancelled" => {
                        if let Some(catalog) = this.agent_auth_catalog.as_mut() {
                            catalog.status = AgentAuthStatus::AuthenticationRequired;
                        }
                        this.agent_auth_error = None;
                        this.notice = Some(
                            management_locale_text_for(
                                active_locale,
                                "Agent authentication stopped",
                                "已终止 Agent 登录认证",
                                "已終止 Agent 登入驗證",
                            )
                            .to_string(),
                        );
                    }
                    Ok(Err(error)) => {
                        this.agent_auth_error = Some(format!("{}: {}", error.code, error.message));
                    }
                    Err(error) => {
                        this.agent_auth_error = Some(format!(
                            "{}: {error}",
                            management_error_text(
                                "Authentication action failed",
                                "认证操作失败",
                                "驗證操作失敗",
                            )
                        ));
                    }
                }
                cx.notify();
            });
        });
        self.agent_auth_operation_tasks
            .retain(|_, existing| !existing.is_ready());
        self.agent_auth_operation_tasks.insert(agent_id_key, task);
        cx.notify();
    }

    fn cancel_agent_authentication(
        &mut self,
        agent_id: String,
        operation_id: AgentAuthenticationOperationId,
        cx: &mut Context<Self>,
    ) {
        let Some(operation) = self.agent_auth_operations.get_mut(&agent_id) else {
            return;
        };
        if operation.operation_id != operation_id
            || operation.phase == AgentAuthOperationPhase::Cancelling
        {
            return;
        }
        let Some(backend) = self.backend.clone() else {
            return;
        };
        let Ok(parsed_agent_id) = AgentId::parse(agent_id.clone()) else {
            return;
        };
        operation.phase = AgentAuthOperationPhase::Cancelling;
        let auth_context = operation.auth_context.clone();
        self.agent_auth_error = None;
        let request = AgentAuthenticationCancelRequest {
            operation_id: operation_id.clone(),
            agent_id: parsed_agent_id,
        };
        let operation_id_for_runner = operation_id.clone();
        let runner = gpui_tokio::Tokio::spawn(cx, async move {
            if let Some((auth_context_id, expected_context_revision)) = auth_context {
                backend
                    .agent()
                    .cancel_agent_context_authentication(MutationRequest::new(
                        AgentAuthContextCancelAuthenticationRequest {
                            operation_id: operation_id_for_runner,
                            auth_context_id,
                            expected_context_revision,
                        },
                    ))
                    .await
                    .map_err(crate::app::remote_error_into_vibex)?;
                return Ok::<_, VibexError>(true);
            }
            for attempt in 0..40 {
                if backend
                    .agent()
                    .cancel_agent_authentication(MutationRequest::new(request.clone()))
                    .await
                    .map_err(crate::app::remote_error_into_vibex)?
                {
                    return Ok::<_, VibexError>(true);
                }
                if attempt < 39 {
                    tokio::time::sleep(Duration::from_millis(50)).await;
                }
            }
            Ok(false)
        });
        let entity = cx.weak_entity();
        let agent_id_for_callback = agent_id.clone();
        let task = cx.spawn(async move |_, cx| {
            let outcome = runner.await;
            let _ = entity.update(cx, |this, cx| {
                let operation_is_registered = this
                    .agent_auth_operations
                    .get(&agent_id_for_callback)
                    .is_some_and(|operation| operation.operation_id == operation_id);
                if !operation_is_registered {
                    return;
                }
                match outcome {
                    Ok(Ok(true)) => {
                        this.agent_auth_operations.remove(&agent_id_for_callback);
                        this.clear_agent_auth_terminal(cx);
                        this.agent_auth_error = None;
                        this.notice = Some(
                            management_locale_text(
                                "Agent authentication stopped",
                                "已终止 Agent 登录认证",
                                "已終止 Agent 登入驗證",
                            )
                            .to_string(),
                        );
                    }
                    Ok(Ok(false)) => {
                        if let Some(operation) =
                            this.agent_auth_operations.get_mut(&agent_id_for_callback)
                        {
                            operation.phase = AgentAuthOperationPhase::Running;
                        }
                        this.agent_auth_error = Some(
                            "agent_authentication_cancel_not_found: Authentication operation could not be stopped"
                                .to_string(),
                        );
                    }
                    Ok(Err(error)) => {
                        if let Some(operation) =
                            this.agent_auth_operations.get_mut(&agent_id_for_callback)
                        {
                            operation.phase = AgentAuthOperationPhase::Running;
                        }
                        this.agent_auth_error = Some(format!("{}: {}", error.code, error.message));
                    }
                    Err(error) => {
                        if let Some(operation) =
                            this.agent_auth_operations.get_mut(&agent_id_for_callback)
                        {
                            operation.phase = AgentAuthOperationPhase::Running;
                        }
                        this.agent_auth_error = Some(format!(
                            "{}: {error}",
                            management_error_text(
                                "Stopping authentication failed",
                                "终止认证失败",
                                "終止驗證失敗",
                            )
                        ));
                    }
                }
                cx.notify();
            });
        });
        self.agent_auth_cancel_tasks
            .retain(|_, existing| !existing.is_ready());
        self.agent_auth_cancel_tasks.insert(agent_id, task);
        cx.notify();
    }

    fn verify_agent_auth_context(&mut self, cx: &mut Context<Self>) {
        let (Some(backend), Some(context), Some(scope)) = (
            self.backend.clone(),
            self.agent_auth_context.clone(),
            self.current_agent_auth_scope(),
        ) else {
            return;
        };
        let agent_id_key = context.agent_id.as_str().to_string();
        if self.mutation.is_some() || self.agent_mutations.contains_key(&agent_id_key) {
            return;
        }
        let generation = self.agent_auth_generation;
        let mutation = ManagementMutation::AgentAuth {
            agent_id: agent_id_key.clone(),
            action: "verify".to_string(),
        };
        self.agent_mutations
            .insert(agent_id_key.clone(), mutation.clone());
        self.agent_auth_error = None;
        self.agent_auth_logout_preview = None;
        let entity = cx.weak_entity();
        let runner = gpui_tokio::Tokio::spawn(cx, async move {
            backend
                .agent()
                .verify_agent_auth_context(MutationRequest::new(AgentAuthContextVerifyRequest {
                    auth_context_id: context.id,
                    expected_context_revision: context.revision,
                    operation_id: None,
                }))
                .await
                .map_err(crate::app::remote_error_into_vibex)
        });
        let completed_mutation = mutation;
        let agent_id_for_callback = agent_id_key.clone();
        let task = cx.spawn(async move |_, cx| {
            let outcome = runner.await;
            let _ = entity.update(cx, |this, cx| {
                let operation_is_registered =
                    this.agent_mutations.get(&agent_id_for_callback) == Some(&completed_mutation);
                if operation_is_registered {
                    this.agent_mutations.remove(&agent_id_for_callback);
                }
                if !operation_is_registered
                    || !agent_auth_scope_matches(
                        this.agent_auth_generation,
                        this.agent_auth_scope.as_ref(),
                        generation,
                        &scope,
                    )
                {
                    cx.notify();
                    return;
                }
                match outcome {
                    Ok(Ok(result)) => {
                        this.agent_auth_context = Some(result.context);
                        this.agent_auth_model_catalog = result.model_catalog;
                        this.agent_auth_error = None;
                        this.notice = Some(
                            management_locale_text(
                                "Default Agent account verified",
                                "Agent 默认账号已验证",
                                "Agent 預設帳號已驗證",
                            )
                            .to_string(),
                        );
                    }
                    Ok(Err(error)) => {
                        this.agent_auth_error = Some(format!("{}: {}", error.code, error.message));
                        this.load_agent_auth(true, cx);
                    }
                    Err(error) => {
                        this.agent_auth_error = Some(format!(
                            "{}: {error}",
                            management_error_text(
                                "Account verification failed",
                                "账号验证失败",
                                "帳號驗證失敗",
                            )
                        ));
                    }
                }
                cx.notify();
            });
        });
        self.agent_mutation_tasks
            .retain(|_, existing| !existing.is_ready());
        self.agent_mutation_tasks.insert(agent_id_key, task);
        cx.notify();
    }

