    fn open_profile_editor(
        &mut self,
        profile: vibex_desktop_model::ProviderProfileProjection,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        self.select_provider_profile(profile.id.clone(), cx);
        let full_profile = self
            .provider_profiles
            .iter()
            .find(|candidate| candidate.id.as_str() == profile.id)
            .cloned();
        let website_url = full_profile
            .as_ref()
            .and_then(|profile| {
                profile
                    .provider_options
                    .entries
                    .iter()
                    .find(|entry| entry.key == PROVIDER_OPTION_WEBSITE_URL)
            })
            .map(|entry| entry.value.clone())
            .unwrap_or_default();
        self.profile_name.update(cx, |state, cx| {
            state.set_value(profile.display_name.clone(), window, cx)
        });
        self.profile_note.update(cx, |state, cx| {
            state.set_value(
                profile.account_alias.clone().unwrap_or_default(),
                window,
                cx,
            )
        });
        self.profile_website_url
            .update(cx, |state, cx| state.set_value(website_url, window, cx));
        self.profile_base_url.update(cx, |state, cx| {
            state.set_value(profile.base_url.clone().unwrap_or_default(), window, cx)
        });
        self.profile_model_draft
            .update(cx, |state, cx| state.set_value("", window, cx));
        self.profile_model_search
            .update(cx, |state, cx| state.set_value("", window, cx));
        self.profile_model_edit_id
            .update(cx, |state, cx| state.set_value("", window, cx));
        self.profile_model_edit_name
            .update(cx, |state, cx| state.set_value("", window, cx));
        self.profile_model_edit_efforts
            .update(cx, |state, cx| state.set_value("", window, cx));
        self.profile_model_edit_context_tokens
            .update(cx, |state, cx| state.set_value("", window, cx));
        self.profile_model_edit_output_tokens
            .update(cx, |state, cx| state.set_value("", window, cx));
        self.profile_api_key.update(cx, |state, cx| {
            state.set_masked(true, window, cx);
            state.set_placeholder(PROVIDER_API_KEY_PLACEHOLDER, window, cx);
            state.set_value("", window, cx);
        });
        self.profile_configured_models = full_profile
            .as_ref()
            .map(|profile| profile.configured_models.clone())
            .unwrap_or_default();
        // The catalogue is not persisted with the profile, so a reopened editor
        // starts with only the configured Models as known rows until the user
        // asks the endpoint again.
        self.profile_available_models.clear();
        self.profile_detached_models.clear();
        self.profile_model_selection = None;
        self.profile_model_edit_wire_api = None;
        self.profile_model_edit_reasoning_disabled = false;
        self.profile_model_edit_error = None;
        self.profile_model_advanced_open = false;
        self.profile_provider_options = full_profile
            .map(|profile| profile.provider_options)
            .unwrap_or_else(vibex_core::ProviderOptions::empty);
        self.rebuild_profile_protocol_base_urls(window, cx);
        // An override the user already set stays visible instead of hiding
        // behind a disclosure that looks empty.
        self.profile_protocol_advanced_open = self.pending_protocol_overrides() > 0;
        self.editing_profile_id = Some(profile.id.clone());
        self.projection_editor.draft_revision = 0;
        // The stored Secret is read back so the field can show it masked and
        // reveal it on request; until the read lands the field stays blank,
        // which is the "keep the stored value" answer either way.
        self.profile_secret_configured = profile.secret_configured;
        self.profile_secret_loaded = None;
        self.profile_secret_clear = false;
        if profile.secret_configured {
            self.load_profile_secret(profile.id.clone(), window, cx);
        }
        self.profile_name_error = None;
        self.profile_submit_error = None;
        self.projection_editor.set_secret_intent(false, false);
        self.profile_editor_open = true;
        self.error = None;
        self.navigation.mark_dirty(ManagementSection::Agents, false);
        self.present_profile_editor_dialog(window, cx);
        cx.notify();
    }

    fn close_profile_editor(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        self.reset_profile_editor_state(window, cx);
        if window.has_active_dialog(cx) {
            window.close_dialog(cx);
        }
    }

    /// Reads the stored Secret back so the API key field can show it.
    ///
    /// The field renders it masked and the eye reveals it, so the value is only
    /// ever legible on the user's own request. The read fills the field only
    /// while the same Provider is still open and the user has typed nothing, so
    /// a late answer can never overwrite a replacement; a failed read leaves the
    /// blank field, which is still the "keep the stored value" answer.
    fn load_profile_secret(&mut self, profile_id: String, window: &Window, cx: &mut Context<Self>) {
        let (Ok(provider_profile_id), Some(agent_id), Some(backend)) = (
            vibex_core::ProviderProfileId::parse(profile_id.clone()),
            self.selected_agent_id
                .clone()
                .and_then(|agent_id| AgentId::parse(agent_id).ok()),
            self.backend.clone(),
        ) else {
            return;
        };
        let entity = cx.weak_entity();
        self.profile_secret_task = Some(cx.spawn_in(window, async move |_, cx| {
            let outcome = backend
                .management()
                .get_agent_model_provider_profile_secret_value(
                    vibex_core::AgentModelProviderProfileSecretValueRequest {
                        agent_id,
                        provider_profile_id,
                    },
                )
                .await;
            let _ = entity.update_in(cx, |this, window, cx| {
                if this.editing_profile_id.as_deref() != Some(profile_id.as_str())
                    || !this.profile_api_key.read(cx).value().is_empty()
                {
                    return;
                }
                let Ok(response) = outcome else {
                    return;
                };
                let Some(secret) = response.value.filter(|value| !value.trim().is_empty()) else {
                    return;
                };
                this.profile_secret_loaded = Some(secret.clone());
                this.profile_api_key.update(cx, |state, cx| {
                    state.set_masked(true, window, cx);
                    state.set_value(secret, window, cx);
                });
                cx.notify();
            });
        }));
    }

    fn reset_profile_editor_state(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        self.profile_api_key.update(cx, |state, cx| {
            state.set_placeholder(PROVIDER_API_KEY_PLACEHOLDER, window, cx);
            state.set_value("", window, cx);
        });
        self.profile_model_search
            .update(cx, |state, cx| state.set_value("", window, cx));
        self.profile_editor_open = false;
        self.editing_profile_id = None;
        self.projection_editor.draft_revision = 0;
        self.profile_secret_configured = false;
        self.profile_secret_loaded = None;
        self.profile_secret_clear = false;
        self.profile_name_error = None;
        self.projection_editor.set_secret_intent(false, false);
        self.profile_configured_models.clear();
        self.profile_available_models.clear();
        self.profile_detached_models.clear();
        self.profile_model_selection = None;
        self.profile_model_edit_wire_api = None;
        self.profile_model_edit_error = None;
        self.profile_model_advanced_open = false;
        self.profile_protocol_advanced_open = false;
        self.profile_provider_options = vibex_core::ProviderOptions::empty();
        self.profile_protocol_base_urls.clear();
        self.navigation.mark_dirty(ManagementSection::Agents, false);
        cx.notify();
    }

    fn rebuild_profile_protocol_base_urls(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        self.profile_protocol_base_urls.clear();
        for wire_api in self.projection_editor.supported_wire_apis() {
            let option_key = wire_api.protocol_base_url_option_key();
            let value = provider_option_value(&self.profile_provider_options, &option_key)
                .unwrap_or_default()
                .to_string();
            let input = cx.new(|cx| {
                InputState::new(window, cx)
                    .default_value(value)
                    .placeholder("https://provider.example")
            });
            self._subscriptions
                .push(cx.subscribe(&input, |this, _, event: &InputEvent, cx| {
                    if !management_input_changed(event) {
                        return;
                    }
                    this.projection_editor.mark_draft_changed();
                    this.navigation.mark_dirty(ManagementSection::Agents, true);
                    cx.notify();
                }));
            self.profile_protocol_base_urls.push((wire_api, input));
        }
    }

    /// Per-protocol endpoint overrides the user has already filled in.
    fn pending_protocol_overrides(&self) -> usize {
        self.profile_protocol_base_urls
            .iter()
            .filter(|(wire_api, _)| {
                provider_option_value(
                    &self.profile_provider_options,
                    &wire_api.protocol_base_url_option_key(),
                )
                .is_some_and(|value| !value.trim().is_empty())
            })
            .count()
    }

    fn present_profile_editor_dialog(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        let center = cx.entity();
        let dialog_center = center.clone();
        let confirm_center = center.clone();
        let dialog_content = cx.new(|cx| ManagementProfileDialog::new(center.clone(), cx));
        // Wide enough for the Model picker and its settings side by side, and
        // tall enough that the two panes, not the whole form, are what scrolls.
        let dialog_width = (f32::from(window.viewport_size().width) - 32.0).clamp(360.0, 1040.0);
        let dialog_height = (f32::from(window.viewport_size().height) - 32.0).clamp(360.0, 760.0);
        let title = if self.editing_profile_id.is_some() {
            management_locale_text("Edit model provider", "编辑模型供应商", "編輯模型供應商")
        } else {
            management_locale_text("Add model provider", "添加模型供应商", "新增模型供應商")
        };
        window.open_dialog(cx, move |dialog, _, _| {
            let dialog_center = dialog_center.clone();
            let confirm_center = confirm_center.clone();
            dialog
                .title(title)
                .w(px(dialog_width))
                .max_w(px(dialog_width))
                .h(px(dialog_height))
                .child(dialog_content.clone())
                // The Dialog answers Enter with its own confirm action, whose
                // default is "close this overlay". Enter in a form means the
                // form's commit, so it saves here, and the dialog is closed by
                // the save path only after the backend accepted it.
                .on_ok(move |_, _, cx| {
                    confirm_center.update(cx, |center, cx| center.save_profile(cx));
                    false
                })
                .on_close(move |_, window, cx| {
                    dialog_center.update(cx, |center, cx| {
                        center.reset_profile_editor_state(window, cx);
                    });
                })
        });
    }

    fn add_profile_model(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        let model_id = self.profile_model_draft.read(cx).value().trim().to_string();
        if model_id.is_empty() {
            return;
        }
        self.choose_profile_model(model_id.clone(), None);
        self.profile_model_draft
            .update(cx, |state, cx| state.set_value("", window, cx));
        // A hand-typed Model has no row to click, so adding it is also the
        // gesture that opens its settings.
        self.select_profile_model(model_id, window, cx);
        self.navigation.mark_dirty(ManagementSection::Agents, true);
        cx.notify();
    }

    /// Adds the Model the settings pane is showing and opens its editor.
    fn add_selected_profile_model(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        let Some(model_id) = self.profile_model_selection.clone() else {
            return;
        };
        let entry = self
            .profile_candidate_rows()
            .into_iter()
            .find(|row| row.id == model_id)
            .map(|row| row.as_configured_model());
        if self.choose_profile_model(model_id.clone(), entry) {
            self.navigation.mark_dirty(ManagementSection::Agents, true);
        }
        self.select_profile_model(model_id, window, cx);
    }

    /// Moves one Model id into the draft, restoring a released configuration
    /// when the id was unchecked earlier.
    ///
    /// Returns whether the draft changed, so a bulk caller can decide if it
    /// needs to mark the section dirty.
    fn choose_profile_model(
        &mut self,
        model_id: String,
        catalogue_entry: Option<vibex_core::ProviderConfiguredModel>,
    ) -> bool {
        if self
            .profile_configured_models
            .iter()
            .any(|model| model.id == model_id)
        {
            return false;
        }
        let restored = self
            .profile_detached_models
            .iter()
            .position(|model| model.id == model_id)
            .map(|index| self.profile_detached_models.remove(index));
        let model =
            restored
                .or(catalogue_entry)
                .unwrap_or_else(|| vibex_core::ProviderConfiguredModel {
                    id: model_id,
                    display_name: None,
                    enabled: true,
                    wire_api: None,
                    capabilities: Default::default(),
                });
        self.profile_configured_models.push(model);
        true
    }

    /// Releases a configured Model at `index` while keeping its declaration
    /// available for a later re-check.
    fn detach_profile_model_at(&mut self, index: usize) -> bool {
        if index >= self.profile_configured_models.len() {
            return false;
        }
        let model = self.profile_configured_models.remove(index);
        if !self
            .profile_detached_models
            .iter()
            .any(|detached| detached.id == model.id)
        {
            self.profile_detached_models.push(model);
        }
        true
    }

    /// The configured Model the settings pane is editing, if the selection
    /// still names one.
    fn selected_profile_model_index(&self) -> Option<usize> {
        let selected = self.profile_model_selection.as_deref()?;
        self.profile_configured_models
            .iter()
            .position(|model| model.id == selected)
    }

    /// Checks or unchecks one picker row against the draft.
    fn select_profile_candidate(
        &mut self,
        row: &ProfileCandidateRow,
        selected: bool,
        cx: &mut Context<Self>,
    ) {
        let changed = if selected {
            self.choose_profile_model(row.id.clone(), Some(row.as_configured_model()))
        } else {
            match self
                .profile_configured_models
                .iter()
                .position(|model| model.id == row.id)
            {
                Some(index) => self.detach_profile_model_at(index),
                None => false,
            }
        };
        if changed {
            self.navigation.mark_dirty(ManagementSection::Agents, true);
        }
        cx.notify();
    }

    /// The picker's rows: what the endpoint advertised, plus every configured
    /// Model the last answer did not mention, plus every Model the user released
    /// by unchecking it, so nothing already saved or hand-typed can silently
    /// disappear from the list.
    fn profile_candidate_rows(&self) -> Vec<ProfileCandidateRow> {
        let mut rows: Vec<ProfileCandidateRow> = Vec::new();
        for model in &self.profile_available_models {
            match rows.iter_mut().find(|row| row.id == model.id) {
                Some(row) => {
                    if row.display_name.is_none() {
                        row.display_name = model.display_name.clone();
                    }
                    if row.wire_api.is_none() {
                        row.wire_api = model.wire_api;
                    }
                    if row.capabilities.is_empty() {
                        row.capabilities = model.capabilities.clone();
                    }
                }
                None => rows.push(ProfileCandidateRow {
                    id: model.id.clone(),
                    display_name: model.display_name.clone(),
                    wire_api: model.wire_api,
                    capabilities: model.capabilities.clone(),
                    configured_index: None,
                    released: false,
                }),
            }
        }
        for (index, model) in self.profile_configured_models.iter().enumerate() {
            match rows.iter_mut().find(|row| row.id == model.id) {
                Some(row) => {
                    row.configured_index = Some(index);
                    // A declared capability is user data, so it outranks the
                    // catalogue's own answer for the same Model.
                    if !model.capabilities.is_empty() {
                        row.capabilities = model.capabilities.clone();
                    }
                    if row.display_name.is_none() {
                        row.display_name = model.display_name.clone();
                    }
                    if row.wire_api.is_none() {
                        row.wire_api = model.wire_api;
                    }
                }
                None => rows.push(ProfileCandidateRow {
                    id: model.id.clone(),
                    display_name: model.display_name.clone(),
                    wire_api: model.wire_api,
                    capabilities: model.capabilities.clone(),
                    configured_index: Some(index),
                    released: false,
                }),
            }
        }
        for model in &self.profile_detached_models {
            match rows.iter_mut().find(|row| row.id == model.id) {
                Some(row) => {
                    // Unchecking keeps the row where it was, unchecked and
                    // still holding the declaration a re-check restores.
                    row.released = true;
                    if !model.capabilities.is_empty() {
                        row.capabilities = model.capabilities.clone();
                    }
                    if row.display_name.is_none() {
                        row.display_name = model.display_name.clone();
                    }
                    if row.wire_api.is_none() {
                        row.wire_api = model.wire_api;
                    }
                }
                None => rows.push(ProfileCandidateRow {
                    id: model.id.clone(),
                    display_name: model.display_name.clone(),
                    wire_api: model.wire_api,
                    capabilities: model.capabilities.clone(),
                    configured_index: None,
                    released: true,
                }),
            }
        }
        rows
    }

    fn toggle_profile_model(&mut self, index: usize, enabled: bool, cx: &mut Context<Self>) {
        if let Some(model) = self.profile_configured_models.get_mut(index) {
            model.enabled = enabled;
            self.navigation.mark_dirty(ManagementSection::Agents, true);
            cx.notify();
        }
    }

    /// Removes a Model from the draft entirely, wherever its declaration lives.
    ///
    /// Unchecking a row only releases a Model and keeps its declaration for a
    /// later re-check; the row's delete command is the stronger answer, so it
    /// drops the declaration too and leaves a catalogue row as the plain,
    /// unconfigured row it started as.
    fn delete_profile_model(
        &mut self,
        model_id: String,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let mut removed = false;
        if let Some(index) = self
            .profile_configured_models
            .iter()
            .position(|model| model.id == model_id)
        {
            self.profile_configured_models.remove(index);
            removed = true;
        }
        if let Some(index) = self
            .profile_detached_models
            .iter()
            .position(|model| model.id == model_id)
        {
            self.profile_detached_models.remove(index);
            removed = true;
        }
        if !removed {
            return;
        }
        // The settings pane must not keep editing a Model the draft no longer
        // holds, so deleting the open one closes it.
        if self.profile_model_selection.as_deref() == Some(model_id.as_str()) {
            self.profile_model_selection = None;
            self.profile_model_edit_wire_api = None;
            self.profile_model_edit_reasoning_disabled = false;
            self.profile_model_edit_error = None;
            self.profile_model_advanced_open = false;
            for input in [
                &self.profile_model_edit_id,
                &self.profile_model_edit_name,
                &self.profile_model_edit_efforts,
                &self.profile_model_edit_context_tokens,
                &self.profile_model_edit_output_tokens,
            ] {
                input.update(cx, |state, cx| state.set_value("", window, cx));
            }
        }
        self.navigation.mark_dirty(ManagementSection::Agents, true);
        cx.notify();
    }

    /// Flips one of the Provider editor's disclosures.
    fn toggle_profile_editor_disclosure(&mut self, id: &str, cx: &mut Context<Self>) {
        match id {
            PROFILE_PROTOCOL_DISCLOSURE_ID => {
                self.profile_protocol_advanced_open = !self.profile_protocol_advanced_open;
            }
            PROFILE_MODEL_ADVANCED_DISCLOSURE_ID => {
                self.profile_model_advanced_open = !self.profile_model_advanced_open;
            }
            _ => return,
        }
        cx.notify();
    }

    /// Points the settings pane at one picker row.
    ///
    /// A row the Provider does not configure yet has no settings to show, so
    /// the pane presents the command that adds it instead of an editor.
    fn select_profile_model(
        &mut self,
        model_id: String,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        self.profile_model_selection = Some(model_id.clone());
        match self
            .profile_configured_models
            .iter()
            .position(|model| model.id == model_id)
        {
            Some(index) => self.load_profile_model_editor(index, window, cx),
            None => {
                self.profile_model_edit_wire_api = None;
                self.profile_model_edit_reasoning_disabled = false;
                self.profile_model_edit_error = None;
                self.profile_model_advanced_open = false;
                cx.notify();
            }
        }
    }

    /// Loads one configured Model into the settings pane's fields.
    fn load_profile_model_editor(
        &mut self,
        index: usize,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let Some(model) = self.profile_configured_models.get(index).cloned() else {
            return;
        };
        let was_dirty = self.navigation.is_dirty(ManagementSection::Agents);
        self.profile_model_edit_wire_api = model.wire_api;
        let model_id = model.id.clone();
        self.profile_model_edit_id
            .update(cx, |state, cx| state.set_value(model_id, window, cx));
        self.profile_model_edit_name.update(cx, |state, cx| {
            state.set_value(model.display_name.unwrap_or_default(), window, cx)
        });
        // Two answers share the reasoning control: an opt-out and "not
        // declared". The levels are the wire spellings the user declared, and
        // the field is the only copy they have.
        self.profile_model_edit_reasoning_disabled = model.capabilities.reasoning == Some(false);
        let efforts = model
            .capabilities
            .reasoning_efforts
            .as_ref()
            .map(ToString::to_string)
            .unwrap_or_default();
        self.profile_model_edit_efforts
            .update(cx, |state, cx| state.set_value(efforts, window, cx));
        // A declared limit is shown as the number the user will write back; an
        // undeclared one stays an empty field, which is what "not declared"
        // looks like everywhere else in this editor.
        let context_tokens = model
            .capabilities
            .context_tokens
            .map_or_else(String::new, |tokens| tokens.to_string());
        let output_tokens = model
            .capabilities
            .output_tokens
            .map_or_else(String::new, |tokens| tokens.to_string());
        self.profile_model_edit_context_tokens
            .update(cx, |state, cx| state.set_value(context_tokens, window, cx));
        self.profile_model_edit_output_tokens
            .update(cx, |state, cx| state.set_value(output_tokens, window, cx));
        self.profile_model_selection = Some(model.id);
        self.profile_model_edit_error = None;
        // Advanced values the Model already declares are shown instead of
        // hiding behind a disclosure that looks untouched.
        self.profile_model_advanced_open = model.capabilities.reasoning_efforts.is_some()
            || model.capabilities.context_tokens.is_some()
            || model.capabilities.output_tokens.is_some();
        self.navigation
            .mark_dirty(ManagementSection::Agents, was_dirty);
        cx.notify();
    }

    /// Writes the open Model editor's fields into the draft as they are typed.
    ///
    /// The editor has no Apply step, so nothing typed here can be left behind
    /// when the dialog saves. Each field is written only while it parses: a
    /// half-typed level list or token count keeps the Model's previous value
    /// and reports the problem under the field it came from.
    fn apply_profile_model_edit(&mut self, cx: &mut Context<Self>) {
        let Some(index) = self.selected_profile_model_index() else {
            return;
        };
        if self.profile_configured_models.get(index).is_none() {
            return;
        }
        let model_id = self
            .profile_model_edit_id
            .read(cx)
            .value()
            .trim()
            .to_string();
        let display_name = self
            .profile_model_edit_name
            .read(cx)
            .value()
            .trim()
            .to_string();
        let efforts_text = self
            .profile_model_edit_efforts
            .read(cx)
            .value()
            .trim()
            .to_string();
        let context_tokens_text = self
            .profile_model_edit_context_tokens
            .read(cx)
            .value()
            .trim()
            .to_string();
        let output_tokens_text = self
            .profile_model_edit_output_tokens
            .read(cx)
            .value()
            .trim()
            .to_string();
        let reasoning_disabled = self.profile_model_edit_reasoning_disabled;

        let mut error = None;
        if model_id.is_empty() {
            error = Some((
                ProfileModelEditField::Id,
                management_error_text(
                    "Model id is required",
                    "模型 ID 不能为空",
                    "模型 ID 不能為空",
                )
                .to_string(),
            ));
        }
        // `None` keeps the declared levels, `Some(None)` clears them, and
        // `Some(Some(..))` replaces them. Both the opt-out and an emptied field
        // are the "clear" answer.
        let mut declared_efforts = None;
        if reasoning_disabled || efforts_text.is_empty() {
            declared_efforts = Some(None);
        } else {
            match vibex_core::ProviderModelReasoningEfforts::parse(&efforts_text) {
                Ok(parsed) => declared_efforts = Some(parsed),
                Err(reason) => {
                    if error.is_none() {
                        error = Some((
                            ProfileModelEditField::Reasoning,
                            declared_reasoning_efforts_error(&reason),
                        ));
                    }
                }
            }
        }
        let declared_limits = match declared_token_limits(&context_tokens_text, &output_tokens_text)
        {
            Ok(limits) => Some(limits),
            Err(reason) => {
                if error.is_none() {
                    error = Some((
                        ProfileModelEditField::Limits,
                        declared_token_limit_error(&reason),
                    ));
                }
                None
            }
        };

        let Some(model) = self.profile_configured_models.get_mut(index) else {
            return;
        };
        let renamed = if model_id.is_empty() {
            None
        } else {
            model.id = model_id.clone();
            Some(model_id)
        };
        model.display_name = (!display_name.is_empty()).then_some(display_name);
        model.wire_api = self.profile_model_edit_wire_api;
        if reasoning_disabled {
            model.capabilities.reasoning = Some(false);
            model.capabilities.reasoning_efforts = None;
        } else if let Some(declared) = declared_efforts {
            // Declaring levels is declaring the capability; an emptied field
            // returns the Model to the Agent's default, which also clears an
            // opt-out this editor wrote.
            model.capabilities.reasoning = match (declared.is_some(), model.capabilities.reasoning)
            {
                (true, _) => Some(true),
                (false, Some(false)) => None,
                (false, declared) => declared,
            };
            model.capabilities.reasoning_efforts = declared;
        }
        if let Some((context, output)) = declared_limits {
            // Both limits are always written from the field: an emptied field is
            // the "not declared" answer, so it clears a previous declaration
            // instead of preserving it.
            model.capabilities.context_tokens = context;
            model.capabilities.output_tokens = output;
        }
        // The selection names the Model by id, so a rename has to carry it or
        // the pane would lose the Model it is editing.
        if let Some(renamed) = renamed {
            self.profile_model_selection = Some(renamed);
        }
        self.profile_model_edit_error = error;
        self.projection_editor.mark_draft_changed();
        self.navigation.mark_dirty(ManagementSection::Agents, true);
        cx.notify();
    }

    /// Keeps the per-Protocol interface selection consistent with the projection.
    fn set_profile_model_wire_api(
        &mut self,
        index: usize,
        wire_api: Option<vibex_core::ProviderModelWireApi>,
        cx: &mut Context<Self>,
    ) {
        if wire_api.is_some_and(|wire_api| !self.projection_editor.accepts_wire_api(wire_api)) {
            self.error = Some(
                "agent_model_interface_unsupported: model interface is not supported by the selected Agent projection descriptor"
                    .to_string(),
            );
            cx.notify();
            return;
        }
        if self.selected_profile_model_index() == Some(index) {
            self.profile_model_edit_wire_api = wire_api;
            self.apply_profile_model_edit(cx);
        }
    }

    /// Selects one answer of the Model's reasoning control.
    ///
    /// `disabled` is the Model's opt-out; the levels themselves are the set the
    /// chips toggle, and both answers leave the field as the declaration the
    /// Agent reads.
    fn set_profile_model_reasoning_draft(
        &mut self,
        index: usize,
        disabled: bool,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        if self.selected_profile_model_index() != Some(index) {
            return;
        }
        self.profile_model_edit_reasoning_disabled = disabled;
        self.profile_model_edit_efforts
            .update(cx, |state, cx| state.set_value("", window, cx));
        self.apply_profile_model_edit(cx);
    }

    /// Adds or removes one level of the Model's declared thinking levels.
    ///
    /// The chips and the field are two views of one declaration: a chip toggles
    /// the level it names, the field keeps every wire spelling, and an entry the
    /// vocabulary does not name stays exactly where the user wrote it.
    fn toggle_profile_model_reasoning_level(
        &mut self,
        index: usize,
        level: vibex_core::ProviderReasoningEffortLevel,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        if self.selected_profile_model_index() != Some(index) {
            return;
        }
        let declaration =
            toggled_reasoning_levels(&self.profile_model_edit_efforts.read(cx).value(), level);
        // A declaration is the more specific answer, so choosing levels leaves
        // the non-reasoning opt-out behind.
        self.profile_model_edit_reasoning_disabled = false;
        self.profile_model_edit_efforts
            .update(cx, |state, cx| state.set_value(declaration, window, cx));
        self.apply_profile_model_edit(cx);
    }

    /// Selects a Model from the Agent-owned catalogue.
    ///
    /// The catalogue entry also carries the wire protocol it was advertised
    /// under, so picking a Model picks the protocol the projection writes
    /// instead of leaving the previous selection in place.
    fn set_profile_model_id_from_catalog(
        &mut self,
        index: usize,
        model_id: String,
        wire_api: Option<vibex_core::ProviderModelWireApi>,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        if self.selected_profile_model_index() != Some(index) {
            return;
        }
        self.profile_model_edit_id
            .update(cx, |state, cx| state.set_value(model_id, window, cx));
        if let Some(wire_api) = wire_api
            && self.projection_editor.accepts_wire_api(wire_api)
        {
            self.profile_model_edit_wire_api = Some(wire_api);
        }
        self.apply_profile_model_edit(cx);
    }

    fn duplicate_provider_profile(&mut self, profile_id: String, cx: &mut Context<Self>) {
        let Some(profile) = self
            .provider_profiles
            .iter()
            .find(|profile| profile.id.as_str() == profile_id)
            .cloned()
        else {
            return;
        };
        let Some(backend) = self.backend.clone() else {
            return;
        };
        let active_locale = locale::current_locale();
        let copy_name = match active_locale {
            ResolvedLocale::En => format!("{} copy", profile.display_name),
            ResolvedLocale::ZhCn => format!("{} 副本", profile.display_name),
            ResolvedLocale::ZhTw => format!("{} 副本", profile.display_name),
        };
        self.begin_simple_task(ManagementMutation::ProfileCreate, cx, async move {
            let agent_id = profile.agent_id.clone();
            let created = backend
                .management()
                .create_agent_model_provider_profile(MutationRequest::new(
                    vibex_core::AgentModelProviderProfileCreateRequest {
                        agent_id: agent_id.clone(),
                        display_name: copy_name,
                        account_alias: profile.account_alias,
                        base_url: profile.base_url,
                        default_model: profile.default_model,
                        small_model: profile.small_model,
                        large_model: profile.large_model,
                        configured_models: profile.configured_models,
                        reasoning_effort: profile.reasoning_effort,
                        sandbox_defaults: Some(profile.sandbox_defaults),
                        network_defaults: Some(profile.network_defaults),
                        permission_defaults: Some(profile.permission_defaults),
                        provider_options: Some(profile.provider_options),
                        secret_references: Vec::new(),
                    },
                ))
                .await
                .map_err(crate::app::remote_error_into_vibex)?;
            let message = match active_locale {
                ResolvedLocale::En => {
                    format!("Duplicated provider configuration {}", created.display_name)
                }
                ResolvedLocale::ZhCn => {
                    format!("已复制供应商配置 {}", created.display_name)
                }
                ResolvedLocale::ZhTw => {
                    format!("已複製供應商配置 {}", created.display_name)
                }
            };
            Ok(message)
        });
    }

    fn save_profile(&mut self, cx: &mut Context<Self>) {
        let Some(agent) = self.snapshot.agents.iter().find(|agent| {
            agent.added && self.selected_agent_id.as_deref() == Some(agent.id.as_str())
        }) else {
            self.profile_submit_error = Some(
                management_error_text(
                    "Select an Agent before creating a provider profile",
                    "请先选择 Agent，再创建供应商配置",
                    "請先選擇 Agent，再建立供應商配置",
                )
                .into(),
            );
            cx.notify();
            return;
        };
        let name = self.profile_name.read(cx).value().trim().to_string();
        // The name is the one field the backend refuses outright, so it reports
        // under its own control instead of in the dialog's status line.
        self.profile_name_error = name.is_empty().then(|| {
            management_error_text(
                "Provider name is required",
                "请填写供应商名称",
                "請填寫供應商名稱",
            )
            .to_string()
        });
        if self.profile_name_error.is_some() {
            self.error = None;
            cx.notify();
            return;
        }
        let note = self.profile_note.read(cx).value().trim().to_string();
        let website_url = self.profile_website_url.read(cx).value().trim().to_string();
        // An Agent-owned endpoint is stored as the value the Agent calls, never
        // as whatever the draft input happens to hold.
        let fixed_endpoint = self.projection_editor.fixed_endpoint().map(str::to_string);
        let base_url = match &fixed_endpoint {
            Some(endpoint) => endpoint.clone(),
            None => self.profile_base_url.read(cx).value().trim().to_string(),
        };
        let api_key = self.profile_api_key.read(cx).value().trim().to_string();
        // A value the editor loaded and the user left alone is not a
        // replacement: writing it back would rewrite the same Secret for no
        // reason. Only a different value counts as the user's new key.
        let secret_edited = self.profile_secret_loaded.as_deref() != Some(api_key.as_str());
        let configured_models = normalized_provider_models(&self.profile_configured_models);
        let default_model = configured_models
            .iter()
            .find(|model| model.enabled)
            .map(|model| model.id.clone());
        let mut provider_options = with_provider_option(
            self.profile_provider_options.clone(),
            PROVIDER_OPTION_WEBSITE_URL,
            (!website_url.is_empty()).then_some(website_url),
        );
        for (wire_api, input) in &self.profile_protocol_base_urls {
            // A pinned endpoint cannot be overridden per protocol, so a stale
            // override is cleared instead of being persisted.
            let value = if fixed_endpoint.is_some() {
                String::new()
            } else {
                input.read(cx).value().trim().to_string()
            };
            provider_options = with_provider_option(
                provider_options,
                &wire_api.protocol_base_url_option_key(),
                (!value.is_empty()).then_some(value),
            );
        }
        let editing_profile_id = match self
            .editing_profile_id
            .as_deref()
            .map(vibex_core::ProviderProfileId::parse)
            .transpose()
        {
            Ok(id) => id,
            Err(_) => {
                self.profile_submit_error = Some(
                    management_error_text(
                        "Provider profile identity is invalid",
                        "供应商配置标识无效",
                        "供應商配置識別碼無效",
                    )
                    .into(),
                );
                cx.notify();
                return;
            }
        };
        let agent_id = agent.id.clone();
        // A typed value replaces the stored Secret; an untouched field keeps it,
        // and only the explicit Clear command removes it.
        let secret_surface =
            self.projection_editor.credential_surface() == ProjectionCredentialSurface::ApiKey;
        let secret_clear = secret_surface && self.profile_secret_clear;
        let Some(backend) = self.backend.clone() else {
            self.profile_submit_error = Some(
                management_error_text(
                    "Management runtime is not connected",
                    "配置中心运行时未连接",
                    "配置中心執行階段未連線",
                )
                .into(),
            );
            cx.notify();
            return;
        };
        if self.mutation.is_some() {
            return;
        }
        self.profile_submit_error = None;
        self.mutation = Some(
            editing_profile_id
                .as_ref()
                .map(|id| ManagementMutation::ProfileUpdate(id.as_str().to_string()))
                .unwrap_or(ManagementMutation::ProfileCreate),
        );
        let active_locale = locale::current_locale();
        let entity = cx.weak_entity();
        let runner = gpui_tokio::Tokio::spawn(cx, async move {
            let updating = editing_profile_id.is_some();
            let profile = if let Some(provider_profile_id) = editing_profile_id {
                backend
                    .management()
                    .update_agent_model_provider_profile(MutationRequest::new(
                        vibex_core::AgentModelProviderProfileUpdateRequest {
                            agent_id: agent_id.clone(),
                            provider_profile_id,
                            display_name: Some(name),
                            status: None,
                            account_alias: (!note.is_empty()).then_some(note),
                            base_url: (!base_url.is_empty()).then_some(base_url),
                            default_model: default_model.clone(),
                            small_model: None,
                            large_model: None,
                            configured_models: Some(configured_models.clone()),
                            reasoning_effort: None,
                            sandbox_defaults: None,
                            network_defaults: None,
                            permission_defaults: None,
                            provider_options: Some(provider_options.clone()),
                        },
                    ))
                    .await
                    .map_err(crate::app::remote_error_into_vibex)?
            } else {
                backend
                    .management()
                    .create_agent_model_provider_profile(MutationRequest::new(
                        vibex_core::AgentModelProviderProfileCreateRequest {
                            agent_id: agent_id.clone(),
                            display_name: name,
                            account_alias: (!note.is_empty()).then_some(note),
                            base_url: (!base_url.is_empty()).then_some(base_url),
                            default_model,
                            small_model: None,
                            large_model: None,
                            configured_models,
                            reasoning_effort: None,
                            sandbox_defaults: None,
                            network_defaults: None,
                            permission_defaults: None,
                            provider_options: Some(provider_options),
                            secret_references: Vec::new(),
                        },
                    ))
                    .await
                    .map_err(crate::app::remote_error_into_vibex)?
            };
            let saved_profile_id = profile.id.as_str().to_string();
            let replaces_secret = !api_key.is_empty() && secret_edited;
            if replaces_secret || secret_clear {
                backend
                    .management()
                    .mutate_agent_model_provider_profile_secret(MutationRequest::new(
                        vibex_core::AgentModelProviderProfileSecretValueUpdateRequest {
                            agent_id: agent_id.clone(),
                            provider_profile_id: profile.id.clone(),
                            value: replaces_secret.then_some(api_key),
                            clear: secret_clear,
                        },
                    ))
                    .await
                    .map_err(crate::app::remote_error_into_vibex)?;
            }
            let message = if updating {
                management_locale_text_for(
                    active_locale,
                    "Provider configuration updated",
                    "供应商配置已更新",
                    "供應商配置已更新",
                )
                .to_string()
            } else {
                management_locale_text_for(
                    active_locale,
                    "Provider configuration created",
                    "供应商配置已创建",
                    "供應商配置已建立",
                )
                .to_string()
            };
            Ok::<_, VibexError>((message, saved_profile_id))
        });
        self.mutation_task = Some(cx.spawn(async move |_, cx| {
            let outcome = runner.await;
            let _ = entity.update(cx, |this, cx| {
                this.mutation = None;
                match outcome {
                    Ok(Ok((message, saved_profile_id))) => {
                        this.navigation.mark_dirty(ManagementSection::Agents, false);
                        this.profile_editor_open = false;
                        this.editing_profile_id = None;
                        this.selected_provider_profile_id = Some(saved_profile_id);
                        this.profile_secret_clear = false;
                        this.projection_editor.set_secret_intent(false, false);
                        this.notice = Some(message);
                        this.refresh(cx);
                    }
                    Ok(Err(error)) => {
                        this.profile_submit_error =
                            Some(format!("{}: {}", error.code, error.message));
                        cx.notify();
                    }
                    Err(error) => {
                        this.profile_submit_error = Some(format!(
                            "{}: {error}",
                            management_error_text(
                                "Provider configuration save failed",
                                "供应商配置保存失败",
                                "供應商配置儲存失敗",
                            )
                        ));
                        cx.notify();
                    }
                }
            });
        }));
    }

