    fn ordered_provider_profile_ids(&self, agent_id: &str) -> Vec<String> {
        let mut ids = self
            .snapshot
            .profiles
            .iter()
            .filter(|profile| profile.agent_id == agent_id)
            .map(|profile| profile.id.as_str().to_string())
            .collect::<Vec<_>>();
        ids.sort_by_key(|profile_id| {
            (
                !self
                    .provider_display_order
                    .contains_key(profile_id.as_str()),
                self.provider_display_order
                    .get(profile_id.as_str())
                    .copied()
                    .unwrap_or(i64::MAX),
            )
        });
        ids
    }

    fn start_provider_profile_drag(
        &mut self,
        agent_id: &str,
        profile_id: &str,
        cursor_offset_y: f32,
        cx: &mut Context<Self>,
    ) {
        let original_ids = self.ordered_provider_profile_ids(agent_id);
        if !original_ids.iter().any(|id| id == profile_id) {
            return;
        }
        let initial_target = reorder_target_from_cursor_offset(
            &original_ids,
            profile_id,
            cursor_offset_y,
            MANAGEMENT_PROVIDER_ROW_HEIGHT,
            MANAGEMENT_PROVIDER_ROW_GAP,
        );
        let preview_ids = initial_target
            .as_ref()
            .map(|(target_id, after)| {
                reordered_provider_profile_ids(&original_ids, profile_id, target_id, *after)
            })
            .unwrap_or_else(|| original_ids.clone());
        self.provider_display_order_drag_state = Some(ProviderDisplayOrderDragState {
            agent_id: agent_id.to_string(),
            profile_id: profile_id.to_string(),
            preview_ids,
            original_ids,
        });
        self.provider_display_order_drop_target = initial_target
            .map(|(profile_id, after)| ProviderDisplayOrderDropTarget { profile_id, after });
        cx.notify();
    }

    fn preview_provider_profile_reorder(
        &mut self,
        drag: &ProviderDisplayOrderDrag,
        target_id: &str,
        after: bool,
        cx: &mut Context<Self>,
    ) {
        let Some(state) = self
            .provider_display_order_drag_state
            .as_mut()
            .filter(|state| state.agent_id == drag.agent_id && state.profile_id == drag.profile_id)
        else {
            return;
        };
        let next_target = ProviderDisplayOrderDropTarget {
            profile_id: target_id.to_string(),
            after,
        };
        let next_ids =
            reordered_provider_profile_ids(&state.original_ids, &drag.profile_id, target_id, after);
        if self.provider_display_order_drop_target.as_ref() == Some(&next_target)
            && state.preview_ids == next_ids
        {
            return;
        }
        state.preview_ids = next_ids;
        self.provider_display_order_drop_target = Some(next_target);
        cx.notify();
    }

    fn finish_provider_profile_drag(
        &mut self,
        agent_id: &str,
        profile_id: &str,
        cx: &mut Context<Self>,
    ) {
        let valid_drag = self
            .provider_display_order_drag_state
            .as_ref()
            .is_some_and(|state| state.agent_id == agent_id && state.profile_id == profile_id);
        if !valid_drag {
            return;
        }
        self.provider_display_order_drop_target = None;
        let state = self
            .provider_display_order_drag_state
            .take()
            .expect("validated provider drag state above");
        if state.preview_ids == state.original_ids {
            cx.notify();
            return;
        }
        self.persist_provider_profile_order(&state.agent_id, state.preview_ids, cx);
    }

    fn persist_provider_profile_order(
        &mut self,
        agent_id: &str,
        ordered_ids: Vec<String>,
        cx: &mut Context<Self>,
    ) {
        let current_ids = self.ordered_provider_profile_ids(agent_id);
        if ordered_ids == current_ids {
            return;
        }
        let Ok(parsed_agent_id) = AgentId::parse(agent_id.to_string()) else {
            return;
        };
        let Some(backend) = self.backend.clone() else {
            return;
        };
        let active_locale = locale::current_locale();
        let entries = ordered_ids
            .iter()
            .map(
                |provider_profile_id| vibex_core::AgentModelProviderDisplayOrderSetEntry {
                    provider_profile_id: vibex_core::ProviderProfileId::parse(
                        provider_profile_id.clone(),
                    )
                    .expect("provider profile ids originate from the loaded snapshot"),
                },
            )
            .collect::<Vec<_>>();
        self.provider_display_order
            .extend(ordered_ids.iter().enumerate().map(|(index, profile_id)| {
                (
                    profile_id.clone(),
                    i64::try_from(index).expect("provider order index fits in i64"),
                )
            }));
        cx.notify();
        self.begin_simple_task(
            ManagementMutation::ProviderDisplayOrder(agent_id.to_string()),
            cx,
            async move {
                backend
                    .management()
                    .set_agent_model_provider_display_order(MutationRequest::new(
                        vibex_core::AgentModelProviderDisplayOrderSetRequest {
                            agent_id: parsed_agent_id,
                            entries,
                        },
                    ))
                    .await
                    .map_err(crate::app::remote_error_into_vibex)?;
                Ok(management_locale_text_for(
                    active_locale,
                    "Provider order updated",
                    "模型供应商顺序已更新",
                    "模型供應商順序已更新",
                )
                .to_string())
            },
        );
    }

    fn begin_simple_task<F>(
        &mut self,
        mutation: ManagementMutation,
        cx: &mut Context<Self>,
        work: F,
    ) where
        F: std::future::Future<Output = VibexResult<String>> + Send + 'static,
    {
        self.begin_task_with_success(mutation, cx, async move {
            work.await.map(ManagementTaskSuccess::from)
        });
    }

    fn begin_task_with_success<F>(
        &mut self,
        mutation: ManagementMutation,
        cx: &mut Context<Self>,
        work: F,
    ) where
        F: std::future::Future<Output = VibexResult<ManagementTaskSuccess>> + Send + 'static,
    {
        let concurrent_agent_id = mutation.concurrent_agent_id().map(str::to_string);
        if let Some(agent_id) = concurrent_agent_id.as_deref() {
            if self.agent_mutations.contains_key(agent_id) {
                self.notice = Some(
                    management_locale_text(
                        "Another action for this Agent is still pending",
                        "此 Agent 的另一项操作仍在处理中",
                        "此 Agent 的另一項操作仍在處理中",
                    )
                    .into(),
                );
                cx.notify();
                return;
            }
            self.agent_mutations
                .insert(agent_id.to_string(), mutation.clone());
        } else {
            if self.mutation.is_some() {
                self.notice = Some(
                    management_locale_text(
                        "Another management action is still pending",
                        "另一项配置操作仍在处理中",
                        "另一項配置操作仍在處理中",
                    )
                    .into(),
                );
                cx.notify();
                return;
            }
            self.mutation = Some(mutation.clone());
        }
        let completed_mutation = mutation;
        let entity = cx.weak_entity();
        let runner = gpui_tokio::Tokio::spawn(cx, work);
        let task = cx.spawn(async move |_, cx| {
            let outcome = runner.await;
            let _ = entity.update(cx, |this, cx| {
                if let Some(agent_id) = completed_mutation.concurrent_agent_id() {
                    this.agent_mutations.remove(agent_id);
                } else {
                    this.mutation = None;
                }
                let agent_registry_changed = matches!(
                    &completed_mutation,
                    ManagementMutation::AgentToggle(_)
                        | ManagementMutation::AgentInstall(_)
                        | ManagementMutation::AgentRollback(_)
                        | ManagementMutation::AgentUpdateCheck(_)
                        | ManagementMutation::AgentUninstall(_)
                        | ManagementMutation::AgentDiscovery
                );
                let refresh_after_failure = agent_registry_changed
                    || matches!(
                        &completed_mutation,
                        ManagementMutation::ProviderDisplayOrder(_)
                    );
                match outcome {
                    Ok(Ok(success)) => {
                        match &completed_mutation {
                            ManagementMutation::PromptAction(action)
                            | ManagementMutation::HookAction(action)
                                if action.starts_with("create") =>
                            {
                                this.navigation
                                    .mark_dirty(ManagementSection::Advanced, false);
                            }
                            ManagementMutation::AcpConfig(_) => {
                                this.navigation
                                    .mark_dirty(ManagementSection::Advanced, false);
                                this.selected_acp_profile_id = None;
                                this.acp_config_draft = None;
                            }
                            ManagementMutation::ProviderPreview(action)
                                if matches!(
                                    action.as_str(),
                                    "native-export-apply" | "native-export-rollback"
                                ) =>
                            {
                                this.native_export_preview = None;
                            }
                            ManagementMutation::ScheduledUpdate(_) => {
                                this.navigation
                                    .mark_dirty(ManagementSection::Scheduled, false);
                            }
                            ManagementMutation::BackupInspect
                            | ManagementMutation::BackupRestore
                            | ManagementMutation::BackupCreate => {
                                this.navigation
                                    .mark_dirty(ManagementSection::Recovery, false);
                                this.recovery.phase = "succeeded".into();
                                this.recovery.progress_percent = 100;
                                this.recovery.error_code = None;
                                if let Some(destination) = &success.recovery_destination {
                                    this.recovery.destination = Some(destination.clone());
                                }
                            }
                            _ => {}
                        }
                        if let Some((agent_id, state)) = success.agent_install_state
                            && let Some(agent) = this
                                .snapshot
                                .agents
                                .iter_mut()
                                .find(|agent| agent.id == agent_id)
                        {
                            agent.apply_managed_install_state(state);
                        }
                        this.apply_provider_profile_success(&success.provider_profiles);
                        this.notice = Some(success.message);
                        cx.notify();
                        if !matches!(&completed_mutation, ManagementMutation::AgentUpdateCheck(_)) {
                            this.refresh(cx);
                        }
                        if agent_registry_changed {
                            cx.emit(ManagementEvent::AgentRegistryChanged);
                        }
                    }
                    Ok(Err(error)) => {
                        if matches!(
                            &completed_mutation,
                            ManagementMutation::BackupInspect
                                | ManagementMutation::BackupRestore
                                | ManagementMutation::BackupCreate
                        ) {
                            this.recovery.phase = "error".into();
                            this.recovery.error_code = Some(error.code.clone());
                        }
                        let message = format!("{}: {}", error.code, error.message);
                        if refresh_after_failure {
                            this.refresh(cx);
                        }
                        if agent_registry_changed {
                            cx.emit(ManagementEvent::AgentRegistryChanged);
                        }
                        this.error = Some(message);
                        cx.notify();
                    }
                    Err(error) => {
                        this.error = Some(format!(
                            "{}: {error}",
                            management_error_text(
                                "Config center action failed",
                                "配置中心操作失败",
                                "配置中心操作失敗",
                            )
                        ));
                        if refresh_after_failure {
                            this.refresh(cx);
                        }
                        if agent_registry_changed {
                            cx.emit(ManagementEvent::AgentRegistryChanged);
                        }
                        cx.notify();
                    }
                }
            });
        });
        if let Some(agent_id) = concurrent_agent_id {
            self.agent_mutation_tasks
                .retain(|_, existing| !existing.is_ready());
            self.agent_mutation_tasks.insert(agent_id, task);
        } else {
            self.mutation_task = Some(task);
        }
    }

    fn present_feedback(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        let agent_auth_error = self.agent_auth_error.take();
        let notice = self.notice.take();
        let notification = self
            .error
            .take()
            .map(|error| {
                hint_notification(
                    NotificationType::Error,
                    locale::localize_error_message(&error),
                    cx,
                )
            })
            .or_else(|| {
                agent_auth_error.map(|error| {
                    hint_notification(
                        NotificationType::Error,
                        locale::localize_error_message(&error),
                        cx,
                    )
                })
            })
            .or_else(|| {
                notice.map(|notice| {
                    hint_notification(
                        NotificationType::Info,
                        locale::localize_ui_message(&notice),
                        cx,
                    )
                })
            });
        let Some(notification) = notification else {
            return;
        };

        window.defer(cx, move |window, cx| {
            Theme::global_mut(cx).notification.placement = Anchor::TopCenter;
            window.push_notification(
                notification
                    .id::<ManagementCenterFeedbackNotification>()
                    .autohide(true)
                    .on_click(|_, _, _| {}),
                cx,
            );
        });
    }

    /// Opens the MCP editor, either for a new server or for an existing one.
    fn open_mcp_editor(
        &mut self,
        server_id: Option<String>,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let existing = server_id.as_deref().and_then(|id| {
            self.snapshot
                .mcp_servers
                .iter()
                .find(|server| server.id.as_str() == id)
                .cloned()
        });
        // The editor takes the section body, so the other panes stand down.
        self.mcp_market_open = false;
        self.mcp_import_open = false;
        self.mcp_discovery = None;
        self.mcp_market_install_target = None;
        self.mcp_transport_draft = existing
            .as_ref()
            .map(|server| server.transport_kind)
            .unwrap_or(vibex_core::McpServerTransportKind::Stdio);
        self.mcp_scope_draft = existing
            .as_ref()
            .map(|server| server.scope_kind)
            .unwrap_or(vibex_core::McpServerScopeKind::User);
        let set = |state: &Entity<InputState>,
                   value: String,
                   window: &mut Window,
                   cx: &mut Context<Self>| {
            state.update(cx, |state, cx| state.set_value(value, window, cx));
        };
        set(
            &self.mcp_name_draft,
            existing
                .as_ref()
                .map(|server| server.display_name.clone())
                .unwrap_or_default(),
            window,
            cx,
        );
        set(
            &self.mcp_command_draft,
            existing
                .as_ref()
                .and_then(|server| server.command.clone())
                .unwrap_or_default(),
            window,
            cx,
        );
        let args = existing
            .as_ref()
            .map(|server| server.args.join("\n"))
            .unwrap_or_default();
        self.mcp_args_draft
            .update(cx, |state, cx| state.set_value(args, window, cx));
        set(
            &self.mcp_url_draft,
            existing
                .as_ref()
                .and_then(|server| server.url.clone())
                .unwrap_or_default(),
            window,
            cx,
        );
        set(
            &self.mcp_description_draft,
            existing
                .as_ref()
                .and_then(|server| server.description.clone())
                .unwrap_or_default(),
            window,
            cx,
        );
        let env = existing
            .as_ref()
            .map(|server| {
                server
                    .env
                    .iter()
                    .map(|entry| format!("{}={}", entry.name, entry.value))
                    .collect::<Vec<_>>()
                    .join("\n")
            })
            .unwrap_or_default();
        let headers = existing
            .as_ref()
            .map(|server| {
                server
                    .headers
                    .iter()
                    .map(|entry| format!("{}={}", entry.name, entry.value))
                    .collect::<Vec<_>>()
                    .join("\n")
            })
            .unwrap_or_default();
        self.mcp_env_draft
            .update(cx, |state, cx| state.set_value(env, window, cx));
        self.mcp_headers_draft
            .update(cx, |state, cx| state.set_value(headers, window, cx));

        self.editing_mcp_server_id = server_id;
        self.mcp_editor_open = true;
        self.error = None;
        cx.notify();
    }

    fn close_mcp_editor(&mut self, cx: &mut Context<Self>) {
        self.mcp_editor_open = false;
        self.editing_mcp_server_id = None;
        cx.notify();
    }

    /// Persists the MCP editor, creating or updating as appropriate.
    fn save_mcp_editor(&mut self, cx: &mut Context<Self>) {
        let display_name = self.mcp_name_draft.read(cx).value().trim().to_string();
        if display_name.is_empty() {
            self.error = Some(
                management_error_text(
                    "An MCP server needs a name",
                    "MCP 服务需要名称",
                    "MCP 服務需要名稱",
                )
                .into(),
            );
            cx.notify();
            return;
        }
        let transport_kind = self.mcp_transport_draft;
        let command = self.mcp_command_draft.read(cx).value().trim().to_string();
        let url = self.mcp_url_draft.read(cx).value().trim().to_string();
        let args = management_lines(self.mcp_args_draft.read(cx).value().as_ref());
        let env = management_key_value_lines(self.mcp_env_draft.read(cx).value().as_ref());
        let headers = management_key_value_lines(self.mcp_headers_draft.read(cx).value().as_ref());
        let description = self
            .mcp_description_draft
            .read(cx)
            .value()
            .trim()
            .to_string();
        if transport_kind == vibex_core::McpServerTransportKind::Stdio && command.is_empty() {
            self.error = Some(
                management_error_text(
                    "A stdio MCP server needs a command",
                    "stdio MCP 服务需要命令",
                    "stdio MCP 服務需要命令",
                )
                .into(),
            );
            cx.notify();
            return;
        }
        if transport_kind != vibex_core::McpServerTransportKind::Stdio && url.is_empty() {
            self.error = Some(
                management_error_text(
                    "An HTTP or SSE MCP server needs a URL",
                    "HTTP 或 SSE MCP 服务需要 URL",
                    "HTTP 或 SSE MCP 服務需要 URL",
                )
                .into(),
            );
            cx.notify();
            return;
        }

        let Some(backend) = self.backend.clone() else {
            return;
        };
        let scope_kind = self.mcp_scope_draft;
        let editing_id = self.editing_mcp_server_id.clone();
        let command_option =
            (transport_kind == vibex_core::McpServerTransportKind::Stdio).then(|| command.clone());
        let url_option =
            (transport_kind != vibex_core::McpServerTransportKind::Stdio).then(|| url.clone());
        let description = (!description.is_empty()).then_some(description);
        let enabled_agents = self
            .snapshot
            .agents
            .iter()
            .filter(|agent| {
                agent.added && agent.id.as_str() == self.selected_mcp_source_agent().as_str()
            })
            .map(|agent| vibex_core::McpServerAgentMatrix {
                agent_id: agent.id.clone(),
                enabled: true,
                source_kind: vibex_core::ResourceAgentMatrixSourceKind::Manual,
                updated_at_ms: vibex_core::unix_timestamp_ms(),
            })
            .collect::<Vec<_>>();
        let action = match &editing_id {
            Some(id) => format!("edit:{id}"),
            None => "create".to_string(),
        };
        let active_locale = locale::current_locale();
        self.begin_simple_task(ManagementMutation::McpAction(action), cx, async move {
            let request = match editing_id {
                Some(id) => {
                    let mcp_server_id = vibex_core::McpServerId::parse(id.clone())?;
                    backend
                        .management()
                        .update_mcp_server(MutationRequest::new(
                            vibex_core::McpServerUpdateRequest {
                                mcp_server_id,
                                display_name: Some(display_name),
                                transport_kind: Some(transport_kind),
                                status: None,
                                scope_kind: Some(scope_kind),
                                project_id: None,
                                workspace_id: None,
                                command: command_option,
                                args: Some(args),
                                env: Some(
                                    env.iter()
                                        .map(|(name, value)| vibex_core::McpServerEnvEntry {
                                            name: name.clone(),
                                            value: value.clone(),
                                        })
                                        .collect(),
                                ),
                                url: url_option,
                                headers: Some(
                                    headers
                                        .iter()
                                        .map(|(name, value)| vibex_core::McpServerHeaderEntry {
                                            name: name.clone(),
                                            value: value.clone(),
                                        })
                                        .collect(),
                                ),
                                description,
                                tags: None,
                            },
                        ))
                        .await
                        .map_err(crate::app::remote_error_into_vibex)?;
                    None
                }
                None => Some(
                    backend
                        .management()
                        .create_mcp_server(MutationRequest::new(
                            vibex_core::McpServerCreateRequest {
                                display_name,
                                transport_kind,
                                status: vibex_core::McpServerStatus::Enabled,
                                scope_kind,
                                project_id: None,
                                workspace_id: None,
                                command: command_option,
                                args,
                                env: env
                                    .iter()
                                    .map(|(name, value)| vibex_core::McpServerEnvEntry {
                                        name: name.clone(),
                                        value: value.clone(),
                                    })
                                    .collect(),
                                url: url_option,
                                headers: headers
                                    .iter()
                                    .map(|(name, value)| vibex_core::McpServerHeaderEntry {
                                        name: name.clone(),
                                        value: value.clone(),
                                    })
                                    .collect(),
                                description,
                                tags: Vec::new(),
                                secret_references: Vec::new(),
                                provider_matrix: Vec::new(),
                            },
                        ))
                        .await
                        .map_err(crate::app::remote_error_into_vibex)?,
                ),
            };
            if let (Some(server), enabled_agents) = (request, enabled_agents)
                && !enabled_agents.is_empty()
            {
                backend
                    .management()
                    .set_mcp_server_agent_matrix(MutationRequest::new(
                        vibex_core::McpServerSetAgentMatrixRequest {
                            mcp_server_id: server.id.clone(),
                            agent_matrix: enabled_agents,
                        },
                    ))
                    .await
                    .map_err(crate::app::remote_error_into_vibex)?;
            }
            Ok(management_locale_text_for(
                active_locale,
                "MCP server saved",
                "MCP 服务已保存",
                "MCP 服務已儲存",
            )
            .to_string())
        });
        self.mcp_editor_open = false;
        self.editing_mcp_server_id = None;
    }

    /// Skill editor: opens for a new Skill or for an existing one.
    fn open_skill_editor(
        &mut self,
        skill_id: Option<String>,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let existing = skill_id.as_deref().and_then(|id| {
            self.snapshot
                .skills
                .iter()
                .find(|skill| skill.id.as_str() == id)
                .cloned()
        });
        self.skill_market_open = false;
        self.skill_import_open = false;
        self.skill_discovery = None;
        self.skill_market_install_target = None;
        self.skill_market_document = None;
        self.skill_name_draft.update(cx, |state, cx| {
            state.set_value(
                existing
                    .as_ref()
                    .map(|skill| skill.display_name.clone())
                    .unwrap_or_default(),
                window,
                cx,
            )
        });
        self.skill_description_draft.update(cx, |state, cx| {
            state.set_value(
                existing
                    .as_ref()
                    .and_then(|skill| skill.description.clone())
                    .unwrap_or_default(),
                window,
                cx,
            )
        });
        self.skill_body_draft.update(cx, |state, cx| {
            state.set_value(
                existing
                    .as_ref()
                    .and_then(|skill| skill.body.clone())
                    .unwrap_or_default(),
                window,
                cx,
            )
        });
        self.editing_skill_id = skill_id;
        self.skill_editor_open = true;
        self.error = None;
        cx.notify();
    }

    fn close_skill_editor(&mut self, cx: &mut Context<Self>) {
        self.skill_editor_open = false;
        self.editing_skill_id = None;
        cx.notify();
    }

    /// Persists the Skill editor, creating or updating as appropriate.
    fn save_skill_editor(&mut self, cx: &mut Context<Self>) {
        let display_name = self.skill_name_draft.read(cx).value().trim().to_string();
        if display_name.is_empty() {
            self.error = Some(
                management_error_text("A Skill needs a name", "Skill 需要名称", "Skill 需要名稱")
                    .into(),
            );
            cx.notify();
            return;
        }
        let description = self
            .skill_description_draft
            .read(cx)
            .value()
            .trim()
            .to_string();
        let body = self.skill_body_draft.read(cx).value().to_string();
        if body.trim().is_empty() {
            self.error = Some(
                management_error_text(
                    "A Skill needs instructions",
                    "Skill 需要说明内容",
                    "Skill 需要說明內容",
                )
                .into(),
            );
            cx.notify();
            return;
        }
        let Some(backend) = self.backend.clone() else {
            return;
        };
        let description = (!description.is_empty()).then_some(description);
        let editing_id = self.editing_skill_id.clone();
        let preview: String = body.chars().take(2048).collect();
        let active_locale = locale::current_locale();
        self.begin_simple_task(
            ManagementMutation::SkillAction(match &editing_id {
                Some(id) => format!("edit:{id}"),
                None => "create".to_string(),
            }),
            cx,
            async move {
                match editing_id {
                    Some(id) => {
                        let skill_id = vibex_core::SkillId::parse(id.clone())?;
                        backend
                            .management()
                            .update_skill(MutationRequest::new(vibex_core::SkillUpdateRequest {
                                skill_id,
                                display_name: Some(display_name),
                                source_kind: None,
                                status: None,
                                scope_kind: None,
                                project_id: None,
                                workspace_id: None,
                                source_uri: None,
                                description,
                                tags: None,
                                content_preview: Some(preview),
                                body: Some(body),
                            }))
                            .await
                            .map_err(crate::app::remote_error_into_vibex)?;
                    }
                    None => {
                        backend
                            .management()
                            .create_skill(MutationRequest::new(vibex_core::SkillCreateRequest {
                                display_name,
                                source_kind: vibex_core::SkillSourceKind::Manual,
                                status: vibex_core::SkillStatus::Enabled,
                                scope_kind: vibex_core::SkillScopeKind::User,
                                project_id: None,
                                workspace_id: None,
                                source_uri: None,
                                description,
                                tags: Vec::new(),
                                content_preview: Some(preview),
                                body: Some(body),
                                provider_matrix: Vec::new(),
                            }))
                            .await
                            .map_err(crate::app::remote_error_into_vibex)?;
                    }
                }
                Ok(management_locale_text_for(
                    active_locale,
                    "Skill saved",
                    "Skill 已保存",
                    "Skill 已儲存",
                )
                .to_string())
            },
        );
        self.skill_editor_open = false;
        self.editing_skill_id = None;
    }

    /// Agent a newly created MCP server is enabled for.
    ///
    /// The Config Center has no project-scoped selector, so a server authored
    /// here is a user-scope resource; it is enabled for the Agent that is
    /// currently selected so it can be used straight away.
    fn selected_mcp_source_agent(&self) -> AgentId {
        self.selected_agent_id
            .as_deref()
            .and_then(|id| AgentId::parse(id).ok())
            .or_else(|| {
                self.snapshot
                    .agents
                    .iter()
                    .find(|agent| agent.added)
                    .map(|agent| agent.id.clone())
            })
            .unwrap_or_else(|| AgentId::parse("claude").expect("builtin Agent id is valid"))
    }

    /// Show the native-import view in the section body.
    fn open_mcp_import(&mut self, _window: &mut Window, cx: &mut Context<Self>) {
        if self.mutation.is_some() {
            return;
        }
        self.mcp_market_open = false;
        self.mcp_editor_open = false;
        self.mcp_import_open = true;
        self.mcp_discovery = None;
        self.discover_mcp_servers(cx);
    }

    fn discover_mcp_servers(&mut self, cx: &mut Context<Self>) {
        let Some(backend) = self.backend.clone() else {
            return;
        };
        self.mutation = Some(ManagementMutation::McpAction("discover".into()));
        self.error = None;
        let entity = cx.weak_entity();
        let runner = gpui_tokio::Tokio::spawn(cx, async move {
            backend
                .management()
                .discover_mcp_sources(vibex_core::McpServerDiscoverRequest {
                    source_agent_id: None,
                })
                .await
                .map_err(crate::app::remote_error_into_vibex)
        });
        self.mutation_task = Some(cx.spawn(async move |_, cx| {
            let outcome = runner.await;
            let _ = entity.update(cx, |this, cx| {
                this.mutation = None;
                match outcome {
                    Ok(Ok(discovery)) => {
                        this.notice = Some(match locale::current_locale() {
                            ResolvedLocale::En => format!(
                                "Discovered {} MCP candidate(s)",
                                discovery.discoveries.len()
                            ),
                            ResolvedLocale::ZhCn => {
                                format!("发现 {} 个 MCP 候选项", discovery.discoveries.len())
                            }
                            ResolvedLocale::ZhTw => {
                                format!("發現 {} 個 MCP 候選項", discovery.discoveries.len())
                            }
                        });
                        this.mcp_discovery = Some(discovery);
                    }
                    Ok(Err(error)) => {
                        this.error = Some(format!("{}: {}", error.code, error.message));
                    }
                    Err(error) => {
                        this.error = Some(format!(
                            "{}: {error}",
                            management_error_text(
                                "MCP discovery failed",
                                "MCP 探测失败",
                                "MCP 探測失敗",
                            )
                        ));
                    }
                }
                cx.notify();
            });
        }));
    }

    /// Agents a market install may target, defaulting to every added Agent.
    fn market_default_agents(&self) -> BTreeSet<String> {
        self.snapshot
            .agents
            .iter()
            .filter(|agent| agent.added)
            .map(|agent| agent.id.as_str().to_string())
            .collect()
    }

    /// Show the MCP market in place of the server list.
    ///
    /// The market is a view of the section rather than an overlay, so it can
    /// keep the sidebar and section chrome the user navigated from.
    fn open_mcp_market(&mut self, _window: &mut Window, cx: &mut Context<Self>) {
        if self.mutation.is_some() {
            return;
        }
        self.mcp_market_open = true;
        self.mcp_import_open = false;
        self.mcp_editor_open = false;
        self.mcp_market_install_target = None;
        self.mcp_market_install_env.clear();
        self.mcp_market_install_agents = self.market_default_agents();
        // The index lives in the runtime and outlives this view, so what is
        // shown here is whatever it has already walked; the window is cleared
        // only so the first reply is what fills it in.
        self.mcp_market_entries.clear();
        self.mcp_market_total = 0;
        self.mcp_market_page = 1;
        self.mcp_market_transport = None;
        // Opening the view must not wait on the registry: whatever the runtime
        // has already indexed is enough to paint, and the poll fills the rest.
        self.request_mcp_market(McpMarketRequest::Open, cx);
    }

    /// Load one window of the registry for the current query.
    ///
    /// The runtime indexes the registry a page at a time rather than asking the
    /// registry to search, because the registry's own search takes tens of
    /// seconds. So a reply describes how much of the catalog it covered, and
    /// this keeps asking while that is still growing — which is what makes
    /// results appear as the index fills instead of stopping at whatever the
    /// first page happened to hold.
    fn search_mcp_market(&mut self, _window: &mut Window, cx: &mut Context<Self>) {
        self.request_mcp_market(McpMarketRequest::Search, cx);
    }

    fn request_mcp_market(&mut self, request: McpMarketRequest, cx: &mut Context<Self>) {
        let Some(backend) = self.backend.clone() else {
            return;
        };
        let query = self.mcp_market_query.read(cx).value().trim().to_string();
        // A poll is not something the user did, so it must not put the Search
        // button into a spinner every few seconds.
        if request.starts_a_new_result_set() {
            self.mcp_market_loading = true;
            self.mcp_market_page = 1;
        }
        self.mcp_market_error = None;
        self.mcp_market_generation = self.mcp_market_generation.wrapping_add(1);
        let generation = self.mcp_market_generation;
        let extend = request.waits_for_a_wider_index();
        // The index holds the whole registry, so the view asks for the page it
        // is on rather than for a window it then has to page through itself.
        let page = self.mcp_market_page.max(1);
        let offset = page.saturating_sub(1).saturating_mul(MARKET_PAGE_SIZE);
        let transport = self
            .mcp_market_transport
            .map(MarketTransportFilter::request_filter);
        let entity = cx.weak_entity();
        let runner = gpui_tokio::Tokio::spawn(cx, async move {
            backend
                .management()
                .search_mcp_market(vibex_core::McpMarketSearchRequest {
                    query: (!query.is_empty()).then_some(query),
                    limit: Some(MARKET_PAGE_SIZE as u32),
                    offset: Some(offset.min(u32::MAX as usize) as u32),
                    transport,
                    extend: Some(extend),
                })
                .await
                .map_err(crate::app::remote_error_into_vibex)
        });
        self.mutation_task = Some(cx.spawn(async move |_, cx| {
            let outcome = runner.await;
            let _ = entity.update(cx, |this, cx| {
                // A reply from a request the user has already moved past would
                // otherwise replace the list under them.
                if this.mcp_market_generation != generation {
                    return;
                }
                this.mcp_market_loading = false;
                match outcome {
                    Ok(Ok(response)) => {
                        // A page past the end can only happen when the result
                        // set shrank under the pager; asking for the last page
                        // that exists is better than showing an empty grid.
                        let last_page = market_page_count(response.total_matches);
                        if response.entries.is_empty()
                            && this.mcp_market_page > last_page
                            && response.total_matches > 0
                        {
                            this.mcp_market_page = last_page;
                            this.request_mcp_market(McpMarketRequest::Page, cx);
                            return;
                        }
                        this.mcp_market_entries = response.entries;
                        this.mcp_market_total = response.total_matches;
                        this.mcp_market_has_more = response.has_more;
                        this.schedule_mcp_market_index_poll(cx);
                    }
                    Ok(Err(error)) => {
                        this.mcp_market_error =
                            Some(management_market_error_text(&error.code, &error.message));
                    }
                    Err(error) => this.mcp_market_error = Some(format!("{error}")),
                }
                cx.notify();
            });
        }));
    }

    /// Re-query once the index has had time to gain another page.
    ///
    /// The delay is longer than a page takes to land, so this settles into a
    /// poll that refreshes the count every few seconds rather than one that
    /// spins. It stops once the registry has been walked to its end: the page
    /// in view does not grow, but the number of pages behind it does.
    fn schedule_mcp_market_index_poll(&mut self, cx: &mut Context<Self>) {
        if !self.mcp_market_has_more || !self.mcp_market_open {
            self.mcp_market_index_task = None;
            return;
        }
        let generation = self.mcp_market_generation;
        self.mcp_market_index_task = Some(cx.spawn(
            async move |entity: WeakEntity<Self>, cx: &mut gpui::AsyncApp| {
                cx.background_executor()
                    .timer(MCP_MARKET_INDEX_POLL_INTERVAL)
                    .await;
                let _ = entity.update(cx, |this, cx| {
                    // The view may have closed, or the user may have searched
                    // again, while this was waiting.
                    if this.mcp_market_generation != generation || !this.mcp_market_open {
                        return;
                    }
                    this.request_mcp_market(McpMarketRequest::Poll, cx);
                });
            },
        ));
    }

    /// Open an entry's own page in the browser.
    ///
    /// The URL comes out of a registry record, so it is validated before it
    /// reaches the platform opener exactly like every other external link.
    fn open_mcp_market_link(&mut self, url: String, cx: &mut Context<Self>) {
        match validate_external_open_url(&url)
            .and_then(|validated| crate::platform::open_external_url(&validated.url))
        {
            Ok(()) => {}
            Err(error) => {
                self.mcp_market_error =
                    Some(management_market_error_text(&error.code, &error.message));
                cx.notify();
            }
        }
    }

    /// Open the install form for one entry, seeding an input per declared
    /// environment variable so a credential is entered rather than guessed.
    fn begin_mcp_market_install(
        &mut self,
        entry: vibex_core::McpMarketEntry,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        self.mcp_market_install_env.clear();
        for requirement in &entry.env {
            let placeholder = requirement
                .placeholder
                .clone()
                .or_else(|| requirement.description.clone())
                .unwrap_or_else(|| requirement.name.clone());
            let default = requirement.default_value.clone();
            let input = cx.new(|cx| {
                let state = InputState::new(window, cx).placeholder(placeholder);
                match default {
                    Some(value) => state.default_value(value),
                    None => state,
                }
            });
            self.mcp_market_install_env
                .insert(requirement.name.clone(), input);
        }
        self.mcp_market_install_agents = self.market_default_agents();
        self.mcp_market_install_target = Some(entry);
        cx.notify();
    }

    fn confirm_mcp_market_install(&mut self, cx: &mut Context<Self>) {
        let Some(entry) = self.mcp_market_install_target.clone() else {
            return;
        };
        let Some(backend) = self.backend.clone() else {
            return;
        };
        let mut agent_ids = Vec::new();
        for agent_id in &self.mcp_market_install_agents {
            if let Ok(parsed) = vibex_core::AgentId::parse(agent_id) {
                agent_ids.push(parsed);
            }
        }
        if agent_ids.is_empty() {
            self.error = Some(
                management_error_text(
                    "Select at least one Agent",
                    "请至少选择一个 Agent",
                    "請至少選擇一個 Agent",
                )
                .to_string(),
            );
            return;
        }
        let mut env_values = Vec::new();
        for (name, input) in &self.mcp_market_install_env {
            let value = input.read(cx).value().trim().to_string();
            if !value.is_empty() {
                env_values.push(vibex_core::McpServerEnvEntry {
                    name: name.clone(),
                    value,
                });
            }
        }
        let entry_id = entry.id.clone();
        let display_name = entry.name.clone();
        let candidate = market_entry_to_candidate(&entry, &env_values);
        let active_locale = locale::current_locale();
        self.mutation = Some(ManagementMutation::McpAction(format!(
            "marketInstall:{entry_id}"
        )));
        self.error = None;
        let entity = cx.weak_entity();
        let runner = gpui_tokio::Tokio::spawn(cx, async move {
            backend
                .management()
                .install_mcp_market_entry(MutationRequest::new(
                    vibex_core::McpMarketInstallRequest {
                        entry_id,
                        agent_ids,
                        env_values,
                        candidate,
                    },
                ))
                .await
                .map_err(crate::app::remote_error_into_vibex)
        });
        self.mutation_task = Some(cx.spawn(async move |_, cx| {
            let outcome = runner.await;
            let _ = entity.update(cx, |this, cx| {
                this.mutation = None;
                match outcome {
                    Ok(Ok(result)) => {
                        this.selected_mcp_id = Some(result.server.id.as_str().to_string());
                        this.mcp_market_install_target = None;
                        this.mcp_market_open = false;
                        let skipped = result.skipped_agent_ids.len();
                        this.notice = Some(match active_locale {
                            ResolvedLocale::En => format!(
                                "Installed {display_name} for {} Agent(s){}",
                                result.enabled_agent_ids.len(),
                                if skipped == 0 {
                                    String::new()
                                } else {
                                    format!(", skipped {skipped} that cannot receive MCP")
                                }
                            ),
                            ResolvedLocale::ZhCn => format!(
                                "已为 {} 个 Agent 安装 {display_name}{}",
                                result.enabled_agent_ids.len(),
                                if skipped == 0 {
                                    String::new()
                                } else {
                                    format!("，跳过 {skipped} 个无法接收 MCP 的 Agent")
                                }
                            ),
                            ResolvedLocale::ZhTw => format!(
                                "已為 {} 個 Agent 安裝 {display_name}{}",
                                result.enabled_agent_ids.len(),
                                if skipped == 0 {
                                    String::new()
                                } else {
                                    format!("，跳過 {skipped} 個無法接收 MCP 的 Agent")
                                }
                            ),
                        });
                        this.refresh(cx);
                    }
                    Ok(Err(error)) => {
                        this.error = Some(format!("{}: {}", error.code, error.message));
                    }
                    Err(error) => {
                        this.error = Some(format!(
                            "{}: {error}",
                            management_error_text(
                                "MCP market install failed",
                                "MCP 市场安装失败",
                                "MCP 市場安裝失敗",
                            )
                        ));
                    }
                }
                cx.notify();
            });
        }));
    }

