    fn render_providers(&mut self, window: &mut Window, cx: &mut Context<Self>) -> AnyElement {
        let copy = management_copy();
        if self.custom_agent_editor_open {
            return self.render_custom_agent_editor(cx);
        }
        if self.loading && !self.details_ready {
            // The pane is gated on the aggregated snapshot — the slowest stage
            // of the management refresh — so it would otherwise show the same
            // box it uses for "no Agent selected" for the whole wait. Keep the
            // card chrome, which is already known, and stand in for the rows.
            // `details_ready` stays true on every later refresh, so this is a
            // first load only.
            // The card is built inline rather than bound to a local: this stack
            // holds no Agent yet, so it is not the Agent detail stack the
            // ordering contract describes.
            return v_flex()
                .w_full()
                .min_w_0()
                .gap_4()
                .child(detail_empty_state(
                    management_loading_agents_title(),
                    management_loading_agents_description(),
                    cx,
                ))
                .child(management_card_with_icon(
                    copy.provider_configuration,
                    management_locale_text(
                        "Configure credentials and models for external model services",
                        "配置外部模型服务所需的凭证与模型",
                        "設定外部模型服務所需的憑證與模型",
                    ),
                    "icons/vibex/database.svg",
                    v_flex()
                        .w_full()
                        .min_w_0()
                        .gap(px(MANAGEMENT_PROVIDER_ROW_GAP))
                        .children(management_provider_placeholders(cx))
                        .into_any_element(),
                    cx,
                ))
                .into_any_element();
        }
        let selected_agent = self
            .snapshot
            .agents
            .iter()
            .find(|agent| self.selected_agent_id.as_deref() == Some(agent.id.as_str()));
        let Some(selected_agent) = selected_agent.cloned() else {
            return detail_empty_state(copy.no_agents, copy.no_agents_description, cx);
        };
        let agent_header = management_agent_detail_header(&selected_agent, cx);
        let selected_id = selected_agent.id.as_str().to_string();
        let installation_pending = management_agent_installation_pending(
            selected_agent.added,
            &selected_agent.managed_install,
        ) || matches!(
            self.agent_mutations.get(&selected_id),
            Some(ManagementMutation::AgentInstall(active_id))
                | Some(ManagementMutation::AgentRollback(active_id))
                if active_id == &selected_id
        );
        if installation_pending {
            return v_flex()
                .w_full()
                .gap_4()
                .child(agent_header)
                .child(self.render_agent_install_loading(
                    &selected_agent,
                    matches!(
                        selected_agent.managed_install.status,
                        vibex_core::AgentManagedInstallStatus::UpdateAvailable
                            | vibex_core::AgentManagedInstallStatus::Upgrading
                    ),
                    cx,
                ))
                .into_any_element();
        }
        if !selected_agent.added {
            if selected_agent.managed_install.managed {
                return v_flex()
                    .w_full()
                    .gap_4()
                    .child(agent_header)
                    .child(self.render_agent_installation_card(&selected_agent, window, cx))
                    .into_any_element();
            }
            return detail_empty_state(copy.no_agents, copy.no_agents_description, cx);
        }
        let selected_agent_id = selected_agent.id.as_str().to_string();
        let native_import_supported =
            vibex_core::supports_native_provider_import(&selected_agent.id);
        if !self.model_provider_agent_ids.contains(&selected_agent_id) {
            return v_flex()
                .w_full()
                .min_w_0()
                .gap_4()
                .child(agent_header)
                .child(self.render_agent_installation_card(&selected_agent, window, cx))
                .child(self.render_agent_authentication(window, cx))
                .into_any_element();
        }
        let mut profiles = self
            .snapshot
            .profiles
            .iter()
            .filter(|profile| profile.agent_id == selected_agent_id)
            .cloned()
            .collect::<Vec<_>>();
        profiles.sort_by_key(|profile| {
            (
                !self
                    .provider_display_order
                    .contains_key(profile.id.as_str()),
                self.provider_display_order
                    .get(profile.id.as_str())
                    .copied()
                    .unwrap_or(i64::MAX),
            )
        });
        let active_drag = self
            .provider_display_order_drag_state
            .clone()
            .filter(|state| cx.has_active_drag() && state.agent_id == selected_agent_id);
        if let Some(active_drag) = active_drag.as_ref() {
            profiles.sort_by_key(|profile| {
                active_drag
                    .preview_ids
                    .iter()
                    .position(|profile_id| profile_id == profile.id.as_str())
                    .unwrap_or(usize::MAX)
            });
        }
        let active_drop_target = self
            .provider_display_order_drop_target
            .clone()
            .filter(|_| cx.has_active_drag());
        let selected_profile_id = self
            .selected_management_provider_profile()
            .map(|profile| profile.id.as_str().to_string());
        let pending =
            self.mutation.is_some() || self.agent_mutations.contains_key(&selected_agent_id);
        let native_importing = matches!(
            &self.mutation,
            Some(ManagementMutation::ProviderPreview(action)) if action == "native-import"
        );
        let mut profile_rows = v_flex().id("provider-profile-rows").w_full().gap_2();
        for profile in profiles.clone() {
            let id = profile.id.clone();
            let hover_group: SharedString = format!("provider-row-hover-{id}").into();
            let select_id = id.clone();
            let agent_id = profile.agent_id.clone();
            let edit_profile = profile.clone();
            let test_id = id.clone();
            let test_agent = agent_id.clone();
            let duplicate_id = id.clone();
            let default_id = id.clone();
            let default_agent = agent_id.clone();
            let delete_id = id.clone();
            let delete_label = profile.display_name.clone();
            let profile_state = self
                .agent_profile_states
                .iter()
                .find(|state| state.agent_id == agent_id && state.profile_id == id);
            let is_default = profile_state.is_some_and(|state| state.is_default);
            let active = selected_profile_id.as_deref() == Some(id.as_str());
            let address = profile
                .base_url
                .as_deref()
                .map(str::trim)
                .filter(|value| !value.is_empty())
                .map(str::to_string)
                .unwrap_or_else(management_unconfigured_label);
            let model_count = management_model_count(profile.configured_model_count);
            let testing = matches!(
                &self.mutation,
                Some(ManagementMutation::ProviderProbe(active_id)) if active_id == &id
            );
            let deleting = matches!(
                &self.mutation,
                Some(ManagementMutation::ProfileDelete(active_id)) if active_id == &id
            );
            let selectable = h_flex()
                .id(SharedString::from(format!("provider-select-{id}")))
                .flex_1()
                .min_w_0()
                .min_h(px(72.0))
                .items_center()
                .gap_3()
                .cursor_pointer()
                .px_3()
                .py(px(12.0))
                .on_click(cx.listener(move |this, _, _, cx| {
                    this.select_provider_profile(select_id.clone(), cx);
                }))
                .child(management_profile_glyph(
                    profile.kind,
                    &profile.display_name,
                    is_default,
                    cx,
                ))
                .child(
                    v_flex()
                        .min_w_0()
                        .flex_1()
                        .gap_1()
                        .child(
                            h_flex()
                                .min_w_0()
                                .gap_2()
                                .child(
                                    div()
                                        .min_w_0()
                                        .truncate()
                                        .text_sm()
                                        .font_semibold()
                                        .child(profile.display_name.clone()),
                                )
                                .when(is_default, |header| {
                                    header.child(management_status_badge(
                                        management_locale_text("Default", "默认", "預設")
                                            .to_string(),
                                        cx,
                                    ))
                                }),
                        )
                        .child(
                            div()
                                .min_w_0()
                                .truncate()
                                .text_xs()
                                .text_color(cx.theme().muted_foreground)
                                .child(format!(
                                    "{} · {}",
                                    address,
                                    management_model_count(profile.configured_model_count)
                                )),
                        ),
                );
            let mut actions = h_flex()
                .flex_none()
                .items_center()
                .justify_end()
                .gap_1()
                .pr_3()
                .invisible()
                .group_hover(&hover_group, |style| style.visible());
            // Medium keeps icons at 16px; the explicit size keeps the button at 40px.
            if !is_default {
                actions = actions.child(button_with_aria_label(
                    Button::new(SharedString::from(format!("provider-default-{default_id}")))
                        .with_size(Size::Medium)
                        .secondary()
                        .compact()
                        .size(px(MANAGEMENT_PROVIDER_ROW_ACTION_SIZE))
                        .icon(IconName::Check)
                        .tooltip(management_set_default_label())
                        .disabled(pending)
                        .on_click(cx.listener(move |this, _, _, cx| {
                            this.set_default_provider_profile(
                                default_id.clone(),
                                default_agent.clone(),
                                cx,
                            )
                        })),
                    management_set_default_label(),
                ));
            }
            actions = actions
                .child(button_with_aria_label(
                    Button::new(SharedString::from(format!("provider-edit-{id}")))
                        .with_size(Size::Medium)
                        .secondary()
                        .compact()
                        .size(px(MANAGEMENT_PROVIDER_ROW_ACTION_SIZE))
                        .icon(Icon::default().path("icons/vibex/pencil.svg"))
                        .disabled(pending)
                        .tooltip(management_locale_text(
                            "Edit configuration",
                            "编辑配置",
                            "編輯配置",
                        ))
                        .on_click(cx.listener(move |this, _, window, cx| {
                            this.open_profile_editor(edit_profile.clone(), window, cx)
                        })),
                    management_locale_text("Edit configuration", "编辑配置", "編輯配置"),
                ))
                .child(button_with_aria_label(
                    Button::new(SharedString::from(format!(
                        "provider-duplicate-{duplicate_id}"
                    )))
                    .with_size(Size::Medium)
                    .secondary()
                    .compact()
                    .size(px(MANAGEMENT_PROVIDER_ROW_ACTION_SIZE))
                    .icon(IconName::Copy)
                    .disabled(pending)
                    .tooltip(management_locale_text(
                        "Duplicate configuration",
                        "复制配置",
                        "複製配置",
                    ))
                    .on_click(cx.listener(move |this, _, _, cx| {
                        this.duplicate_provider_profile(duplicate_id.clone(), cx)
                    })),
                    management_locale_text("Duplicate configuration", "复制配置", "複製配置"),
                ))
                .child(button_with_aria_label(
                    Button::new(SharedString::from(format!("provider-test-{test_id}")))
                        .with_size(Size::Medium)
                        .secondary()
                        .compact()
                        .size(px(MANAGEMENT_PROVIDER_ROW_ACTION_SIZE))
                        .icon(Icon::default().path("icons/vibex/activity.svg"))
                        .loading(testing)
                        .disabled(pending)
                        .tooltip(if testing {
                            management_locale_text("Testing...", "正在测试...", "正在測試...")
                        } else {
                            management_test_label()
                        })
                        .on_click(cx.listener(move |this, _, _, cx| {
                            this.test_provider_profile(test_id.clone(), test_agent.clone(), cx)
                        })),
                    management_test_label(),
                ))
                .child(button_with_aria_label(
                    Button::new(SharedString::from(format!("provider-delete-{delete_id}")))
                        .with_size(Size::Medium)
                        .danger()
                        .compact()
                        .size(px(MANAGEMENT_PROVIDER_ROW_ACTION_SIZE))
                        .icon(Icon::default().path("icons/vibex/trash-2.svg"))
                        .loading(deleting)
                        .disabled(pending)
                        .tooltip(management_delete_profile_label())
                        .on_click(cx.listener(move |this, _, window, cx| {
                            this.confirm_managed_delete(
                                ManagedDeleteTarget::Provider {
                                    id: delete_id.clone(),
                                    label: delete_label.clone(),
                                },
                                window,
                                cx,
                            )
                        })),
                    management_delete_profile_label(),
                ));
            let drag_payload = ProviderDisplayOrderDrag {
                agent_id: selected_agent_id.clone(),
                profile_id: id.clone(),
                kind: profile.kind,
                label: profile.display_name.clone(),
                is_default,
                address: address.clone(),
                model_count: model_count.clone(),
            };
            let drag_entity = cx.weak_entity();
            let drag_agent_id = selected_agent_id.clone();
            let drag_profile_id = id.clone();
            let release_agent_id = selected_agent_id.clone();
            let release_profile_id = id.clone();
            let release_out_agent_id = selected_agent_id.clone();
            let release_out_profile_id = id.clone();
            let drag_handle = div()
                .id(SharedString::from(format!("provider-drag-handle-{id}")))
                .flex_none()
                .w(px(36.0))
                .h(px(MANAGEMENT_PROVIDER_ROW_HEIGHT))
                .flex()
                .items_center()
                .justify_center()
                .cursor_grab()
                .tooltip(move |window, cx| {
                    Tooltip::new(management_locale_text(
                        "Drag to reorder providers",
                        "拖动调整供应商顺序",
                        "拖動調整供應商順序",
                    ))
                    .build(window, cx)
                })
                .child(
                    Icon::default()
                        .path("icons/vibex/grip-vertical.svg")
                        .size(px(18.0))
                        .text_color(cx.theme().muted_foreground.opacity(0.65)),
                )
                .on_mouse_up(
                    MouseButton::Left,
                    cx.listener(move |this, _, _, cx| {
                        this.finish_provider_profile_drag(
                            &release_agent_id,
                            &release_profile_id,
                            cx,
                        );
                    }),
                )
                .on_mouse_up_out(
                    MouseButton::Left,
                    cx.listener(move |this, _, _, cx| {
                        this.finish_provider_profile_drag(
                            &release_out_agent_id,
                            &release_out_profile_id,
                            cx,
                        );
                    }),
                )
                .on_drag(drag_payload, move |drag, cursor_offset, _, cx| {
                    cx.stop_propagation();
                    let _ = drag_entity.update(cx, |this, cx| {
                        this.start_provider_profile_drag(
                            &drag_agent_id,
                            &drag_profile_id,
                            f32::from(cursor_offset.y),
                            cx,
                        );
                    });
                    cx.new(|_| drag.clone())
                });
            let active_drop_after = active_drop_target
                .as_ref()
                .and_then(|target| (target.profile_id == id).then_some(target.after));
            let reorder_offset = active_drag
                .as_ref()
                .and_then(|drag| {
                    provider_reorder_row_offset(&drag.original_ids, &drag.preview_ids, id.as_str())
                })
                .map(|rows| {
                    px(
                        rows as f32
                            * (MANAGEMENT_PROVIDER_ROW_HEIGHT + MANAGEMENT_PROVIDER_ROW_GAP),
                    )
                });
            let reorder_animation_id =
                active_drag
                    .as_ref()
                    .zip(active_drop_target.as_ref())
                    .map(|(drag, target)| {
                        format!(
                            "provider-reorder-{}-{}-{}-{}",
                            drag.profile_id, target.profile_id, target.after, id
                        )
                    });
            let move_agent_id = selected_agent_id.clone();
            let move_profile_id = id.clone();
            let row = div()
                .id(SharedString::from(format!("provider-row-{id}")))
                .group(hover_group)
                .relative()
                .flex()
                .items_center()
                .w_full()
                .min_w_0()
                .min_h(px(MANAGEMENT_PROVIDER_ROW_HEIGHT))
                .overflow_hidden()
                .rounded(px(8.0))
                .border_1()
                .border_color(if active_drop_after.is_some() {
                    cx.theme().drag_border
                } else if active {
                    cx.theme().primary.opacity(0.0)
                } else {
                    cx.theme().border.opacity(0.65)
                })
                .bg(if active_drop_after.is_some() {
                    cx.theme().tokens.drop_target.into()
                } else if active {
                    cx.theme().primary.opacity(0.08)
                } else {
                    cx.theme().background.opacity(0.90)
                })
                .hover(|style| {
                    style.bg(if active_drop_after.is_some() {
                        cx.theme().tokens.drop_target.into()
                    } else if active {
                        cx.theme().primary.opacity(0.08)
                    } else {
                        cx.theme().accent
                    })
                })
                .when(
                    active_drag
                        .as_ref()
                        .is_some_and(|drag| drag.profile_id == id),
                    |this| this.opacity(0.45),
                )
                .when_some(active_drop_after, |this, after| {
                    this.child(
                        div()
                            .absolute()
                            .left_0()
                            .right_0()
                            .h(px(2.0))
                            .bg(cx.theme().drag_border)
                            .map(|line| if after { line.bottom_0() } else { line.top_0() }),
                    )
                })
                .on_drag_move(cx.listener(
                    move |this, event: &DragMoveEvent<ProviderDisplayOrderDrag>, _, cx| {
                        let drag = event.drag(cx).clone();
                        let position = event.event.position;
                        let inside_target = position.x >= event.bounds.left() - px(24.0)
                            && position.x <= event.bounds.right() + px(24.0)
                            && position.y
                                >= event.bounds.top() - px(MANAGEMENT_PROVIDER_ROW_GAP / 2.0)
                            && position.y
                                <= event.bounds.bottom() + px(MANAGEMENT_PROVIDER_ROW_GAP / 2.0);
                        let next = (inside_target
                            && drag.agent_id == move_agent_id
                            && drag.profile_id != move_profile_id)
                            .then_some(ProviderDisplayOrderDropTarget {
                                profile_id: move_profile_id.clone(),
                                after: position.y >= event.bounds.center().y,
                            });
                        if let Some(next) = next {
                            this.preview_provider_profile_reorder(
                                &drag,
                                &next.profile_id,
                                next.after,
                                cx,
                            );
                        }
                    },
                ))
                .child(drag_handle)
                .child(selectable)
                .child(actions);
            let row = if let (Some(offset), Some(animation_id)) =
                (reorder_offset, reorder_animation_id)
            {
                Transition::new(Duration::from_millis(
                    MANAGEMENT_PROVIDER_REORDER_ANIMATION_MS,
                ))
                .ease(ease_out_cubic)
                .slide_y(offset, px(0.0))
                .apply(row, animation_id)
                .into_any_element()
            } else {
                row.into_any_element()
            };
            profile_rows = profile_rows.child(row);
        }

        let installation = self.render_agent_installation_card(&selected_agent, window, cx);
        let provider_configuration = if profiles.is_empty() {
            EmptyState::new()
                .flex_none()
                .min_h(px(180.0))
                .gap_3()
                .py_4()
                .header(
                    EmptyHeader::new()
                        .max_w(px(420.0))
                        .title(EmptyTitle::new().child(copy.no_profiles))
                        .description(
                            EmptyDescription::new()
                                .text_xs()
                                .child(copy.no_profiles_description),
                        ),
                )
                .content(
                    EmptyContent::new().child(
                        h_flex()
                            .flex_wrap()
                            .items_center()
                            .justify_center()
                            .gap_2()
                            .child(
                                Button::new("provider-empty-add-configuration")
                                    .small()
                                    .primary()
                                    .icon(IconName::Plus)
                                    .label(copy.add_configuration)
                                    .disabled(pending)
                                    .on_click(cx.listener(|this, _, window, cx| {
                                        this.open_profile_creator(window, cx);
                                    })),
                            )
                            .children(native_import_supported.then(|| {
                                Button::new("provider-empty-import-existing")
                                    .small()
                                    .secondary()
                                    .icon(Icon::default().path("icons/vibex/import.svg"))
                                    .label(copy.import_configuration)
                                    .loading(native_importing)
                                    .disabled(pending)
                                    .on_click(cx.listener(|this, _, _, cx| {
                                        let agent_id = this.selected_agent_id.clone();
                                        this.preview_native_import(true, agent_id, cx)
                                    }))
                            })),
                    ),
                )
                .into_any_element()
        } else {
            v_flex()
                .w_full()
                .min_w_0()
                .gap_3()
                .child(
                    h_flex()
                        .w_full()
                        .min_w_0()
                        .flex_wrap()
                        .items_center()
                        .justify_between()
                        .gap_3()
                        .child(
                            div()
                                .text_xs()
                                .text_color(cx.theme().muted_foreground)
                                .child(management_profile_count(profiles.len())),
                        )
                        .child(
                            h_flex()
                                .flex_none()
                                .flex_wrap()
                                .justify_end()
                                .gap_2()
                                .children(native_import_supported.then(|| {
                                    management_detail_icon_action(
                                        Button::new("provider-import-existing")
                                            .small()
                                            .secondary()
                                            .icon(Icon::default().path("icons/vibex/import.svg"))
                                            .loading(native_importing)
                                            .disabled(pending)
                                            .on_click(cx.listener(|this, _, _, cx| {
                                                let agent_id = this.selected_agent_id.clone();
                                                this.preview_native_import(true, agent_id, cx)
                                            })),
                                        copy.import_configuration,
                                    )
                                }))
                                .child(management_detail_icon_action(
                                    Button::new("provider-add-configuration")
                                        .small()
                                        .primary()
                                        .icon(IconName::Plus)
                                        .disabled(pending)
                                        .on_click(cx.listener(|this, _, window, cx| {
                                            this.open_profile_creator(window, cx);
                                        })),
                                    copy.add_configuration,
                                )),
                        ),
                )
                .child(profile_rows)
                .into_any_element()
        };
        let provider_configuration = management_card_with_icon(
            copy.provider_configuration,
            management_locale_text(
                "Configure credentials and models for external model services",
                "配置外部模型服务所需的凭证与模型",
                "設定外部模型服務所需的憑證與模型",
            ),
            "icons/vibex/database.svg",
            provider_configuration,
            cx,
        );
        let authentication = self.render_agent_authentication(window, cx);

        v_flex()
            .w_full()
            .min_w_0()
            .gap_4()
            .child(agent_header)
            .child(installation)
            .child(authentication)
            .child(provider_configuration)
            .into_any_element()
    }

    fn render_mcp(&mut self, cx: &mut Context<Self>) -> AnyElement {
        if self.mcp_market_open {
            return self.render_mcp_market(cx);
        }
        if self.mcp_import_open {
            return self.render_import_view(true, cx);
        }
        if self.mcp_editor_open {
            let editor = self.render_mcp_editor(cx);
            return v_flex().w_full().gap_2().child(editor).into_any_element();
        }
        let pending = self.mutation.is_some();
        let servers = self
            .snapshot
            .mcp_servers
            .iter()
            .filter(|server| self.selected_mcp_id.as_deref() == Some(server.id.as_str()))
            .cloned()
            .collect::<Vec<_>>();
        let matrix_agents = self
            .snapshot
            .agents
            .iter()
            .filter(|agent| agent.added)
            .cloned()
            .collect::<Vec<_>>();
        let mut rows = v_flex().gap_2();
        for server in servers.clone() {
            let id = server.id.as_str().to_string();
            let validate_id = id.clone();
            let delete_id = id.clone();
            let delete_label = server.display_name.clone();
            let enabled = server.status == vibex_core::McpServerStatus::Enabled;
            let source = format!(
                "{} · {}",
                server.transport_kind,
                server
                    .command
                    .as_deref()
                    .or(server.url.as_deref())
                    .map(str::to_string)
                    .unwrap_or_else(management_unconfigured_label)
            );
            let description = server
                .description
                .as_deref()
                .map(str::trim)
                .filter(|description| !description.is_empty())
                .map(str::to_string)
                .unwrap_or_else(|| management_mcp_description().to_string());
            let validating = matches!(
                &self.mutation,
                Some(ManagementMutation::McpAction(action))
                    if action == &format!("validate:{id}")
            );
            let edit_id = id.clone();
            let deleting = matches!(
                &self.mutation,
                Some(ManagementMutation::McpAction(action))
                    if action == &format!("delete:{id}")
            );
            let validation = self
                .mcp_validation
                .as_ref()
                .filter(|(resource_id, _, _)| resource_id == &id)
                .map(|(_, message, failed)| (message.clone(), *failed));
            let mut agent_matrix_rows = v_flex().w_full().gap_1();
            for agent in matrix_agents.clone() {
                let agent_id = agent.id.clone();
                let server_id = id.clone();
                let matrix_entry = server
                    .agent_matrix
                    .iter()
                    .find(|entry| entry.agent_id == agent_id);
                let enabled_for_agent = matrix_entry.is_some_and(|entry| entry.enabled);
                let matrix_source = matrix_entry
                    .map(|entry| management_resource_matrix_source_label(entry.source_kind))
                    .unwrap_or("manual");
                agent_matrix_rows = agent_matrix_rows.child(
                    h_flex()
                        .w_full()
                        .items_center()
                        .gap_2()
                        .rounded(px(6.0))
                        .border_1()
                        .border_color(cx.theme().border.opacity(0.60))
                        .px_2()
                        .py_2()
                        .child(management_agent_glyph(
                            agent.id.as_str(),
                            &agent.label,
                            false,
                            cx,
                        ))
                        .child(
                            v_flex()
                                .min_w_0()
                                .flex_1()
                                .gap_1()
                                .child(div().truncate().text_sm().font_medium().child(agent.label))
                                .child(
                                    div()
                                        .truncate()
                                        .text_xs()
                                        .text_color(cx.theme().muted_foreground)
                                        .child(format!("{} · {matrix_source}", agent.id)),
                                ),
                        )
                        .child(
                            Switch::new(SharedString::from(format!(
                                "mcp-agent-matrix-{server_id}-{}",
                                agent_id.as_str()
                            )))
                            .small()
                            .checked(enabled_for_agent)
                            .disabled(pending)
                            .on_click(cx.listener(
                                move |this, checked, _, cx| {
                                    this.set_mcp_agent_matrix(
                                        server_id.clone(),
                                        agent_id.clone(),
                                        *checked,
                                        cx,
                                    )
                                },
                            )),
                        ),
                );
            }
            rows = rows.child(
                v_flex()
                    .w_full()
                    .gap_2()
                    .rounded(px(8.0))
                    .border_1()
                    .border_color(cx.theme().border.opacity(0.75))
                    .bg(cx.theme().background.opacity(0.75))
                    .p_3()
                    .child(
                        h_flex()
                            .w_full()
                            .min_w_0()
                            .items_center()
                            .justify_between()
                            .gap_2()
                            .child(
                                div()
                                    .min_w_0()
                                    .flex_1()
                                    .truncate()
                                    .text_sm()
                                    .font_semibold()
                                    .child(server.display_name.clone()),
                            )
                            .child(management_status_badge(
                                management_enabled_label(enabled).to_string(),
                                cx,
                            )),
                    )
                    .child(
                        div()
                            .w_full()
                            .text_xs()
                            .text_color(cx.theme().muted_foreground)
                            .child(description),
                    )
                    .child(key_value(
                        management_locale_text("Source", "来源", "來源"),
                        &source,
                        cx,
                    ))
                    .child(
                        h_flex()
                            .flex_wrap()
                            .gap_1()
                            .child(
                                Button::new(SharedString::from(format!("mcp-edit-{edit_id}")))
                                    .small()
                                    .outline()
                                    .label(management_edit_label())
                                    .disabled(pending)
                                    .on_click(cx.listener(move |this, _, window, cx| {
                                        this.open_mcp_editor(Some(edit_id.clone()), window, cx)
                                    })),
                            )
                            .child(
                                Button::new(SharedString::from(format!(
                                    "mcp-validate-{validate_id}"
                                )))
                                .small()
                                .outline()
                                .label(management_validate_label())
                                .loading(validating)
                                .disabled(pending)
                                .on_click(cx.listener(
                                    move |this, _, _, cx| {
                                        this.validate_mcp_server(validate_id.clone(), cx)
                                    },
                                )),
                            )
                            .child(
                                Button::new(SharedString::from(format!("mcp-delete-{delete_id}")))
                                    .small()
                                    .danger()
                                    .icon(Icon::default().path("icons/vibex/trash-2.svg"))
                                    .loading(deleting)
                                    .tooltip(management_delete_mcp_label())
                                    .disabled(pending)
                                    .on_click(cx.listener(move |this, _, window, cx| {
                                        this.confirm_managed_delete(
                                            ManagedDeleteTarget::Mcp {
                                                id: delete_id.clone(),
                                                label: delete_label.clone(),
                                            },
                                            window,
                                            cx,
                                        )
                                    })),
                            ),
                    )
                    .when_some(validation, |card, (message, failed)| {
                        card.child(status_line(
                            if failed {
                                locale::localize_error_message(&message)
                            } else {
                                locale::localize_ui_message(&message)
                            },
                            failed,
                            cx,
                        ))
                    })
                    .when(!matrix_agents.is_empty(), |card| {
                        card.child(
                            v_flex()
                                .w_full()
                                .gap_2()
                                .child(
                                    div()
                                        .text_xs()
                                        .font_semibold()
                                        .child(management_agent_enablement_label()),
                                )
                                .child(agent_matrix_rows),
                        )
                    }),
            );
        }
        v_flex()
            .w_full()
            .min_w_0()
            .gap_4()
            .child(if servers.is_empty() {
                compact_empty_state(
                    management_no_mcp_selection_title(),
                    management_no_mcp_selection_description(),
                    cx,
                )
            } else {
                rows.into_any_element()
            })
            .into_any_element()
    }

    fn render_skills(&mut self, cx: &mut Context<Self>) -> AnyElement {
        if self.skill_market_open {
            return self.render_skills_market(cx);
        }
        if self.skill_import_open {
            return self.render_import_view(false, cx);
        }
        if self.skill_editor_open {
            let editor = self.render_skill_editor(cx);
            return v_flex().w_full().gap_2().child(editor).into_any_element();
        }
        let pending = self.mutation.is_some();
        let skills = self
            .snapshot
            .skills
            .iter()
            .filter(|skill| self.selected_skill_id.as_deref() == Some(skill.id.as_str()))
            .cloned()
            .collect::<Vec<_>>();
        let matrix_agents = self
            .snapshot
            .agents
            .iter()
            .filter(|agent| agent.added)
            .cloned()
            .collect::<Vec<_>>();
        let mut rows = v_flex().gap_2();
        for skill in skills.clone() {
            let id = skill.id.as_str().to_string();
            let validate_id = id.clone();
            let delete_id = id.clone();
            let delete_label = skill.display_name.clone();
            let enabled = skill.status == vibex_core::SkillStatus::Enabled;
            let source = skill
                .source_uri
                .as_deref()
                .map(str::trim)
                .filter(|source| !source.is_empty())
                .map(str::to_string)
                .unwrap_or_else(|| management_skill_source_kind_label(skill.source_kind).into());
            let description = skill
                .description
                .as_deref()
                .map(str::trim)
                .filter(|description| !description.is_empty())
                .map(str::to_string)
                .unwrap_or_else(|| management_skills_description().to_string());
            let validating = matches!(
                &self.mutation,
                Some(ManagementMutation::SkillAction(action))
                    if action == &format!("validate:{id}")
            );
            let edit_id = id.clone();
            let deleting = matches!(
                &self.mutation,
                Some(ManagementMutation::SkillAction(action))
                    if action == &format!("delete:{id}")
            );
            let validation = self
                .skill_validation
                .as_ref()
                .filter(|(resource_id, _, _)| resource_id == &id)
                .map(|(_, message, failed)| (message.clone(), *failed));
            let mut agent_matrix_rows = v_flex().w_full().gap_1();
            for agent in matrix_agents.clone() {
                let agent_id = agent.id.clone();
                let skill_id = id.clone();
                let matrix_entry = skill
                    .agent_matrix
                    .iter()
                    .find(|entry| entry.agent_id == agent_id);
                let enabled_for_agent = matrix_entry.is_some_and(|entry| entry.enabled);
                let matrix_source = matrix_entry
                    .map(|entry| management_resource_matrix_source_label(entry.source_kind))
                    .unwrap_or("manual");
                agent_matrix_rows = agent_matrix_rows.child(
                    h_flex()
                        .w_full()
                        .items_center()
                        .gap_2()
                        .rounded(px(6.0))
                        .border_1()
                        .border_color(cx.theme().border.opacity(0.60))
                        .px_2()
                        .py_2()
                        .child(management_agent_glyph(
                            agent.id.as_str(),
                            &agent.label,
                            false,
                            cx,
                        ))
                        .child(
                            v_flex()
                                .min_w_0()
                                .flex_1()
                                .gap_1()
                                .child(div().truncate().text_sm().font_medium().child(agent.label))
                                .child(
                                    div()
                                        .truncate()
                                        .text_xs()
                                        .text_color(cx.theme().muted_foreground)
                                        .child(format!("{} · {matrix_source}", agent.id)),
                                ),
                        )
                        .child(
                            Switch::new(SharedString::from(format!(
                                "skill-agent-matrix-{skill_id}-{}",
                                agent_id.as_str()
                            )))
                            .small()
                            .checked(enabled_for_agent)
                            .disabled(pending)
                            .on_click(cx.listener(
                                move |this, checked, _, cx| {
                                    this.set_skill_agent_matrix(
                                        skill_id.clone(),
                                        agent_id.clone(),
                                        *checked,
                                        cx,
                                    )
                                },
                            )),
                        ),
                );
            }
            rows =
                rows.child(
                    v_flex()
                        .w_full()
                        .gap_2()
                        .rounded(px(8.0))
                        .border_1()
                        .border_color(cx.theme().border.opacity(0.75))
                        .bg(cx.theme().background.opacity(0.75))
                        .p_3()
                        .child(
                            h_flex()
                                .w_full()
                                .min_w_0()
                                .items_center()
                                .justify_between()
                                .gap_2()
                                .child(
                                    div()
                                        .min_w_0()
                                        .flex_1()
                                        .truncate()
                                        .text_sm()
                                        .font_semibold()
                                        .child(skill.display_name.clone()),
                                )
                                .child(management_status_badge(
                                    management_enabled_label(enabled).to_string(),
                                    cx,
                                )),
                        )
                        .child(
                            div()
                                .w_full()
                                .text_xs()
                                .text_color(cx.theme().muted_foreground)
                                .child(description),
                        )
                        .child(key_value(
                            management_locale_text("Source", "来源", "來源"),
                            &source,
                            cx,
                        ))
                        .child(
                            h_flex()
                                .flex_wrap()
                                .gap_1()
                                .child(
                                    Button::new(SharedString::from(format!(
                                        "skill-edit-{edit_id}"
                                    )))
                                    .small()
                                    .outline()
                                    .label(management_edit_label())
                                    .disabled(pending)
                                    .on_click(cx.listener(move |this, _, window, cx| {
                                        this.open_skill_editor(Some(edit_id.clone()), window, cx)
                                    })),
                                )
                                .child(
                                    Button::new(SharedString::from(format!(
                                        "skill-validate-{validate_id}"
                                    )))
                                    .small()
                                    .outline()
                                    .label(management_validate_label())
                                    .loading(validating)
                                    .disabled(pending)
                                    .on_click(cx.listener(move |this, _, _, cx| {
                                        this.validate_skill(validate_id.clone(), cx)
                                    })),
                                )
                                .child(
                                    Button::new(SharedString::from(format!(
                                        "skill-delete-{delete_id}"
                                    )))
                                    .small()
                                    .danger()
                                    .icon(Icon::default().path("icons/vibex/trash-2.svg"))
                                    .loading(deleting)
                                    .tooltip(management_delete_skill_label())
                                    .disabled(pending)
                                    .on_click(cx.listener(move |this, _, window, cx| {
                                        this.confirm_managed_delete(
                                            ManagedDeleteTarget::Skill {
                                                id: delete_id.clone(),
                                                label: delete_label.clone(),
                                            },
                                            window,
                                            cx,
                                        )
                                    })),
                                ),
                        )
                        .when_some(validation, |card, (message, failed)| {
                            card.child(status_line(
                                if failed {
                                    locale::localize_error_message(&message)
                                } else {
                                    locale::localize_ui_message(&message)
                                },
                                failed,
                                cx,
                            ))
                        })
                        .when(!matrix_agents.is_empty(), |card| {
                            card.child(
                                v_flex()
                                    .w_full()
                                    .gap_2()
                                    .child(
                                        div()
                                            .text_xs()
                                            .font_semibold()
                                            .child(management_agent_enablement_label()),
                                    )
                                    .child(agent_matrix_rows),
                            )
                        }),
                );
        }
        v_flex()
            .w_full()
            .min_w_0()
            .gap_4()
            .child(if skills.is_empty() {
                compact_empty_state(
                    management_no_skill_selection_title(),
                    management_no_skill_selection_description(),
                    cx,
                )
            } else {
                rows.into_any_element()
            })
            .into_any_element()
    }

