impl Render for ManagementProfileDialog {
    fn render(&mut self, window: &mut Window, cx: &mut Context<Self>) -> impl IntoElement {
        if !self.center.read(cx).profile_editor_open {
            cx.defer_in(window, |_, window, cx| {
                if window.has_active_dialog(cx) {
                    window.close_dialog(cx);
                }
            });
            return div().size_full().into_any_element();
        }
        self.center.update(cx, |center, cx| {
            center.render_profile_editor_dialog(window, cx)
        })
    }
}

impl Render for ManagementCenter {
    fn render(&mut self, window: &mut Window, cx: &mut Context<Self>) -> impl IntoElement {
        self.present_feedback(window, cx);
        let viewport = window.viewport_size();
        let viewport_width = f32::from(viewport.width);
        let viewport_height = f32::from(viewport.height);
        let wide = management_uses_wide_layout(viewport_width);
        let (compact_min_height, compact_max_height) =
            management_compact_sidebar_height_limits(viewport_height);
        let compact_sidebar_height = self
            .compact_sidebar_height
            .clamp(compact_min_height, compact_max_height);
        let nav = self.render_nav(cx);
        let context_sidebar = self.render_context_sidebar(window, cx);
        let content = self.render_content(window, cx);
        let sidebar = v_flex()
            .min_h_0()
            .flex_none()
            .overflow_hidden()
            .border_color(cx.theme().border)
            .bg(cx.theme().background)
            .when(wide, |sidebar| {
                sidebar
                    .w(px(MANAGEMENT_SIDEBAR_WIDTH))
                    .h_full()
                    .border_r_1()
            })
            .when(!wide, |sidebar| {
                sidebar.w_full().h(px(compact_sidebar_height))
            })
            .child(
                v_flex()
                    .min_h_0()
                    .flex_1()
                    .gap(px(10.0))
                    .p_3()
                    .child(nav)
                    .child(
                        div()
                            .min_h_0()
                            .flex_1()
                            .overflow_hidden()
                            .child(context_sidebar),
                    ),
            );
        let pane = div().flex_1().min_h_0().min_w_0().child(content);
        // A section body that scrolls its own list must not sit in a scroll
        // container as well: the container hands its child an auto height, so
        // the view grows past the window and takes its own footer — the market
        // pager, the import view's Detect command — off the bottom with it.
        // Left unscrolled, the pane's height is definite and the inner list is
        // the only thing that moves.
        //
        // The padding is spelled out in both branches rather than applied
        // before them: the pane's own inset is what keeps the overlay scrollbar
        // off its content, so it has to sit on the same builder chain as the
        // scroll wrapper — which is the chain a source check reads.
        let main = if self.section_body_owns_its_scroll() {
            pane.when(viewport_width < 640.0, |main| main.p_3())
                .when(viewport_width >= 640.0, |main| main.p_4())
                .into_any_element()
        } else {
            pane.when(viewport_width < 640.0, |main| main.p_3())
                .when(viewport_width >= 640.0, |main| main.p_4())
                .overflow_y_scrollbar()
                .into_any_element()
        };
        let layout = if wide {
            h_flex()
                .size_full()
                .min_w_0()
                .min_h_0()
                .child(sidebar)
                .child(main)
                .into_any_element()
        } else {
            v_flex()
                .size_full()
                .min_w_0()
                .min_h_0()
                .child(sidebar)
                .child(self.render_compact_sidebar_resize_handle(
                    compact_min_height,
                    compact_max_height,
                    compact_sidebar_height,
                    cx,
                ))
                .child(main)
                .into_any_element()
        };
        div()
            .id("management-center")
            .relative()
            .size_full()
            .min_w_0()
            .min_h_0()
            .bg(cx.theme().background)
            .text_color(cx.theme().foreground)
            .when(self.compact_sidebar_resize_drag.is_some(), |root| {
                root.cursor_ns_resize()
            })
            .child(layout)
    }
}

fn management_compact_sidebar_height_limits(viewport_height: f32) -> (f32, f32) {
    let available = viewport_height
        - TITLE_BAR_HEIGHT
        - MANAGEMENT_COMPACT_RESIZE_HANDLE_HEIGHT
        - MANAGEMENT_COMPACT_MAIN_MIN_HEIGHT;
    let max_height = available.clamp(
        MANAGEMENT_COMPACT_SIDEBAR_MIN_HEIGHT,
        MANAGEMENT_COMPACT_SIDEBAR_MAX_HEIGHT,
    );
    (MANAGEMENT_COMPACT_SIDEBAR_MIN_HEIGHT, max_height)
}

fn management_uses_wide_layout(viewport_width: f32) -> bool {
    viewport_width >= MANAGEMENT_WIDE_BREAKPOINT
}

impl ManagementCenter {
    /// Whether the section body scrolls a list of its own.
    fn section_body_owns_its_scroll(&self) -> bool {
        match management_primary_section(self.navigation.active) {
            ManagementSection::Mcp => management_section_body_scrolls_itself(
                self.mcp_market_open,
                self.mcp_market_install_target.is_some(),
                self.mcp_import_open,
            ),
            ManagementSection::Skills => management_section_body_scrolls_itself(
                self.skill_market_open,
                self.skill_market_install_target.is_some(),
                self.skill_import_open,
            ),
            _ => false,
        }
    }
}

/// Whether a resource section's body scrolls a list of its own.
///
/// The market grid keeps a pager under a list that scrolls, and the import
/// view keeps its Detect command under one; both are sized to the pane, so the
/// pane must not scroll them as well. The market's install form replaces the
/// grid and is a long form, so it goes back to the pane's own scrolling.
fn management_section_body_scrolls_itself(
    market_open: bool,
    install_form_open: bool,
    import_open: bool,
) -> bool {
    import_open || (market_open && !install_form_open)
}

fn management_primary_section(section: ManagementSection) -> ManagementSection {
    match section {
        ManagementSection::Agents | ManagementSection::ModelProviders => ManagementSection::Agents,
        ManagementSection::Mcp => ManagementSection::Mcp,
        ManagementSection::Skills => ManagementSection::Skills,
        ManagementSection::PromptsHooks
        | ManagementSection::Advanced
        | ManagementSection::Scheduled
        | ManagementSection::Automation
        | ManagementSection::Recovery => ManagementSection::Advanced,
    }
}

fn reordered_provider_profile_ids(
    profile_ids: &[String],
    moving_id: &str,
    target_id: &str,
    after: bool,
) -> Vec<String> {
    let mut ids = profile_ids.to_vec();
    if moving_id == target_id {
        return ids;
    }
    let Some(moving_index) = ids.iter().position(|id| id == moving_id) else {
        return ids;
    };
    let moving = ids.remove(moving_index);
    let Some(target_index) = ids.iter().position(|id| id == target_id) else {
        ids.insert(moving_index.min(ids.len()), moving);
        return ids;
    };
    ids.insert(target_index + usize::from(after), moving);
    ids
}

fn reorder_target_from_cursor_offset(
    ordered_ids: &[String],
    moving_id: &str,
    cursor_offset_y: f32,
    row_height: f32,
    row_gap: f32,
) -> Option<(String, bool)> {
    let moving_index = ordered_ids.iter().position(|id| id == moving_id)?;
    let stride = row_height + row_gap;
    if stride <= 0.0 {
        return None;
    }
    let row_delta = ((cursor_offset_y - row_height / 2.0) / stride).round() as isize;
    if row_delta == 0 {
        return None;
    }
    let target_index = moving_index
        .saturating_add_signed(row_delta)
        .min(ordered_ids.len().saturating_sub(1));
    (target_index != moving_index).then(|| {
        (
            ordered_ids[target_index].clone(),
            target_index > moving_index,
        )
    })
}

fn provider_reorder_row_offset(
    original_ids: &[String],
    preview_ids: &[String],
    profile_id: &str,
) -> Option<isize> {
    let original_index = original_ids.iter().position(|id| id == profile_id)?;
    let preview_index = preview_ids.iter().position(|id| id == profile_id)?;
    let offset = isize::try_from(original_index).ok()? - isize::try_from(preview_index).ok()?;
    (offset != 0).then_some(offset)
}

fn management_provider_default_scope(
    workspace_id: Option<vibex_core::WorkspaceId>,
) -> vibex_core::ProviderProfileDefaultScope {
    if let Some(workspace_id) = workspace_id {
        vibex_core::ProviderProfileDefaultScope {
            kind: vibex_core::ProviderDefaultScopeKind::Workspace,
            project_id: None,
            workspace_id: Some(workspace_id),
        }
    } else {
        vibex_core::ProviderProfileDefaultScope {
            kind: vibex_core::ProviderDefaultScopeKind::Global,
            project_id: None,
            workspace_id: None,
        }
    }
}

