fn management_agent_matches_search(agent: &AgentSnapshotEntry, query: &str) -> bool {
    query.is_empty()
        || format!(
            "{} {} {} {:?}",
            agent.label,
            agent.id.as_str(),
            agent.description.as_deref().unwrap_or_default(),
            agent.runtime_kind
        )
        .to_lowercase()
        .contains(query)
}

/// Sidebar grouping: enabled agents first, then added-but-disabled, then
/// not-added catalog agents. Within a group the shared Agent ordering applies.
fn management_agent_group(agent: &AgentSnapshotEntry) -> u8 {
    if !agent.added {
        2
    } else if agent.enabled {
        0
    } else {
        1
    }
}

fn agent_install_url(agent: &AgentSnapshotEntry) -> Option<&str> {
    if let Some(install_url) = agent
        .params
        .get("installUrl")
        .and_then(serde_json::Value::as_str)
        .filter(|install_url| !install_url.trim().is_empty())
    {
        return Some(install_url);
    }

    let identity = format!(
        "{} {} {} {}",
        agent.id,
        agent.label,
        agent
            .command
            .as_ref()
            .map(|command| command.command.as_str())
            .unwrap_or_default(),
        agent.description.as_deref().unwrap_or_default(),
    )
    .to_ascii_lowercase();
    let compact = identity
        .chars()
        .filter(char::is_ascii_alphanumeric)
        .collect::<String>();
    let tokens = identity
        .split(|character: char| !character.is_ascii_alphanumeric())
        .filter(|token| !token.is_empty())
        .collect::<Vec<_>>();
    let has_token = |candidates: &[&str]| {
        candidates
            .iter()
            .any(|candidate| tokens.contains(candidate))
    };

    if compact.contains("opencode") || compact.contains("openaiopencode") {
        Some("https://opencode.ai/docs/")
    } else if compact.contains("codebuddy") {
        Some("https://www.codebuddy.ai/cli")
    } else if compact.contains("githubcopilot") || has_token(&["copilot"]) {
        Some("https://github.com/features/copilot/cli")
    } else if has_token(&["qwen", "tongyi", "dashscope"]) || compact.contains("qwencode") {
        Some("https://qwen.ai/qwencode")
    } else if has_token(&["gemini"]) || compact.contains("geminicli") {
        Some("https://geminicli.com/")
    } else if has_token(&["goose"]) {
        Some("https://goose-docs.ai/docs/getting-started/installation")
    } else if has_token(&["qoder"]) {
        Some("https://qoder.com/zh/cli")
    } else if has_token(&["kiro"]) {
        Some("https://kiro.dev/cli/")
    } else if has_token(&["cline"]) {
        Some("https://cline.bot/cli")
    } else if has_token(&["auggie", "augment", "augmentcode"]) {
        Some("https://www.augmentcode.com/product/cli")
    } else if has_token(&["amp", "ampcode", "sourcegraph"]) {
        Some("https://ampcode.com/manual")
    } else if has_token(&["claude", "anthropic"]) || compact.contains("claudecode") {
        Some("https://code.claude.com/docs/quickstart")
    } else if has_token(&["codex", "openai", "chatgpt"]) {
        Some("https://developers.openai.com/codex/cli")
    } else {
        None
    }
}

fn mcp_import_selection_from_discovery(
    item: vibex_core::McpServerDiscovery,
) -> Option<vibex_core::McpServerImportSelection> {
    if item.status != vibex_core::ResourceDiscoveryStatus::Importable {
        return None;
    }
    let candidate = item.candidate?;
    let source_agent_id = item.source_agent_id;
    Some(vibex_core::McpServerImportSelection {
        discovery_id: item.discovery_id,
        enable_agent_ids: vec![source_agent_id.clone()],
        source_agent_id,
        candidate,
    })
}

fn skill_import_selection_from_discovery(
    item: vibex_core::SkillDiscovery,
) -> Option<vibex_core::SkillImportSelection> {
    if item.status != vibex_core::ResourceDiscoveryStatus::Importable {
        return None;
    }
    let source_agent_id = item.source_agent_id;
    Some(vibex_core::SkillImportSelection {
        discovery_id: item.discovery_id,
        enable_agent_ids: vec![source_agent_id.clone()],
        source_agent_id,
        source_path: item.source_path,
        display_name: item.display_name,
        command_name: item.command_name,
        description: item.description,
        content_preview: item.content_preview,
        body: item.body,
    })
}

fn acp_config_with_editor_fields(
    mut config: vibex_core::AcpProviderConfig,
    command: String,
    args: &str,
    cwd_template: &str,
) -> vibex_core::AcpProviderConfig {
    config.command = command;
    config.args = args.split_whitespace().map(str::to_string).collect();
    config.cwd_template =
        (!cwd_template.trim().is_empty()).then(|| cwd_template.trim().to_string());
    config
}

fn updated_mcp_agent_matrix(
    mut matrix: Vec<vibex_core::McpServerAgentMatrix>,
    agent_id: AgentId,
    enabled: bool,
) -> Vec<vibex_core::McpServerAgentMatrix> {
    let updated_at_ms = unix_timestamp_ms();
    if let Some(entry) = matrix.iter_mut().find(|entry| entry.agent_id == agent_id) {
        entry.enabled = enabled;
        entry.updated_at_ms = updated_at_ms;
    } else {
        matrix.push(vibex_core::McpServerAgentMatrix {
            agent_id,
            enabled,
            source_kind: vibex_core::ResourceAgentMatrixSourceKind::Manual,
            updated_at_ms,
        });
    }
    matrix
}

fn updated_skill_agent_matrix(
    mut matrix: Vec<vibex_core::SkillAgentMatrix>,
    agent_id: AgentId,
    enabled: bool,
) -> Vec<vibex_core::SkillAgentMatrix> {
    let updated_at_ms = unix_timestamp_ms();
    if let Some(entry) = matrix.iter_mut().find(|entry| entry.agent_id == agent_id) {
        entry.enabled = enabled;
        entry.updated_at_ms = updated_at_ms;
    } else {
        matrix.push(vibex_core::SkillAgentMatrix {
            agent_id,
            enabled,
            source_kind: vibex_core::ResourceAgentMatrixSourceKind::Manual,
            updated_at_ms,
        });
    }
    matrix
}

/// Parses one declared token limit from the Model editor.
///
/// An empty field is the "not declared" answer, never a zero: an undeclared
/// limit leaves the Agent's own default in place, while a zero window is not a
/// value any Agent could use. A rejected field is named by the caller, so the
/// error points at the input the user has to correct.
fn parse_declared_token_limit(value: &str) -> Result<Option<u32>, &'static str> {
    let value = value.trim();
    if value.is_empty() {
        return Ok(None);
    }
    match value.parse::<u32>() {
        Ok(tokens) if tokens > 0 => Ok(Some(tokens)),
        Ok(_) => Err("must be greater than zero"),
        Err(error) if matches!(error.kind(), IntErrorKind::PosOverflow) => {
            Err("is larger than a token limit can be")
        }
        Err(_) => Err("must be a whole number of tokens"),
    }
}

/// Parses the editor's two declared limits together.
///
/// Both fields are read before either is returned, so a rejected value leaves
/// the Model exactly as it was instead of half-applying an edit.
fn declared_token_limits(
    context_window: &str,
    max_output_tokens: &str,
) -> Result<(Option<u32>, Option<u32>), String> {
    let context = parse_declared_token_limit(context_window)
        .map_err(|reason| format!("agent_model_context_tokens_invalid: {reason}"))?;
    let output = parse_declared_token_limit(max_output_tokens)
        .map_err(|reason| format!("agent_model_output_tokens_invalid: {reason}"))?;
    Ok((context, output))
}

/// Names the field a rejected level list belongs to.
///
/// The parser explains the problem in the endpoint's own vocabulary, which is
/// the part a user can act on; the field name is what makes the message
/// attributable while the editor writes as the user types.
fn declared_reasoning_efforts_error(reason: &str) -> String {
    match locale::current_locale() {
        ResolvedLocale::En => format!("Thinking levels were not saved: {reason}"),
        ResolvedLocale::ZhCn => format!("思考档位没有写入：{reason}"),
        ResolvedLocale::ZhTw => format!("思考檔位沒有寫入：{reason}"),
    }
}

/// Turns the declared-limit parser's code and reason into one field message.
fn declared_token_limit_error(message: &str) -> String {
    let (field, reason) = if message.starts_with("agent_model_context_tokens_invalid") {
        (
            management_locale_text("Context window", "上下文窗口", "上下文視窗"),
            message.trim_start_matches("agent_model_context_tokens_invalid:"),
        )
    } else {
        (
            management_locale_text("Max output tokens", "最大输出 Token", "最大輸出 Token"),
            message.trim_start_matches("agent_model_output_tokens_invalid:"),
        )
    };
    let reason = match reason.trim() {
        "must be greater than zero" => {
            management_locale_text("must be greater than 0", "必须大于 0", "必須大於 0")
        }
        "is larger than a token limit can be" => management_locale_text(
            "is larger than a token limit can be",
            "超出了 Token 上限能表示的范围",
            "超出了 Token 上限能表示的範圍",
        ),
        _ => management_locale_text(
            "must be a whole number of tokens",
            "必须是整数",
            "必須是整數",
        ),
    };
    format!("{field}: {reason}")
}

/// How many per-protocol addresses the Provider already overrides.
fn protocol_override_count(count: usize) -> String {
    match locale::current_locale() {
        ResolvedLocale::En => format!("{count} set"),
        ResolvedLocale::ZhCn => format!("已设置 {count} 项"),
        ResolvedLocale::ZhTw => format!("已設定 {count} 項"),
    }
}

/// Whether a Model row survives the editor's search box.
///
/// Both the id and the display name are searched, because the list shows both
/// and a user may remember either one.
fn profile_candidate_matches(row: &ProfileCandidateRow, filter: &str) -> bool {
    profile_identity_matches(&row.id, row.display_name.as_deref(), filter)
}

/// The one search rule both Model panes use: a case-insensitive substring over
/// the id and the display name.
fn profile_identity_matches(id: &str, display_name: Option<&str>, filter: &str) -> bool {
    let filter = filter.trim().to_lowercase();
    filter.is_empty()
        || id.to_lowercase().contains(&filter)
        || display_name.is_some_and(|name| name.to_lowercase().contains(&filter))
}

/// A Model's declared token limits in the picker's own words.
///
/// Limits live per Model, so the row states the exact numbers the user
/// declared; a Model that declares none says nothing rather than "0".
fn profile_model_limits_label(
    capabilities: &vibex_core::ProviderModelCapabilities,
) -> Option<String> {
    match (capabilities.context_tokens, capabilities.output_tokens) {
        (None, None) => None,
        (context, output) => {
            let mut parts = Vec::new();
            if let Some(context) = context {
                parts.push(match locale::current_locale() {
                    ResolvedLocale::En => format!("{context} context"),
                    ResolvedLocale::ZhCn | ResolvedLocale::ZhTw => format!("上下文 {context}"),
                });
            }
            if let Some(output) = output {
                parts.push(match locale::current_locale() {
                    ResolvedLocale::En => format!("{output} output"),
                    ResolvedLocale::ZhCn => format!("输出 {output}"),
                    ResolvedLocale::ZhTw => format!("輸出 {output}"),
                });
            }
            Some(parts.join(" · "))
        }
    }
}

fn normalized_provider_models(
    models: &[vibex_core::ProviderConfiguredModel],
) -> Vec<vibex_core::ProviderConfiguredModel> {
    let mut normalized = Vec::new();
    for model in models {
        let id = model.id.trim();
        if id.is_empty()
            || normalized
                .iter()
                .any(|item: &vibex_core::ProviderConfiguredModel| item.id == id)
        {
            continue;
        }
        normalized.push(vibex_core::ProviderConfiguredModel {
            id: id.to_string(),
            display_name: model
                .display_name
                .as_deref()
                .map(str::trim)
                .filter(|value| !value.is_empty())
                .map(str::to_string),
            enabled: model.enabled,
            wire_api: model.wire_api,
            // Declared capabilities are user data: the editor is the only
            // place a thinking-depth table can come from, so saving must not
            // normalize it away.
            capabilities: model.capabilities.clone(),
        });
    }
    normalized
}

/// Replaces the draft catalogue while keeping the declared capabilities of
/// every Model that survives the refresh.
///
/// An Agent-owned catalogue answers which Models exist and which wire protocol
/// each speaks; it does not carry a thinking-depth table, so replacing the
/// draft wholesale would silently drop the user's declaration for a Model the
/// catalogue still advertises.
fn replace_provider_models_keeping_capabilities(
    current: &mut Vec<vibex_core::ProviderConfiguredModel>,
    incoming: Vec<vibex_core::ProviderConfiguredModel>,
) {
    let previous = std::mem::take(current);
    *current = incoming
        .into_iter()
        .map(|mut model| {
            if let Some(existing) = previous.iter().find(|existing| existing.id == model.id) {
                model.capabilities = existing.capabilities.clone();
            }
            model
        })
        .collect();
}

fn merge_provider_models(
    current: &mut Vec<vibex_core::ProviderConfiguredModel>,
    incoming: Vec<vibex_core::ProviderConfiguredModel>,
) {
    let mut merged = normalized_provider_models(current);
    for model in normalized_provider_models(&incoming) {
        if let Some(existing) = merged.iter_mut().find(|existing| existing.id == model.id) {
            if existing.display_name.is_none() {
                existing.display_name = model.display_name;
            }
            if existing.wire_api.is_none() {
                existing.wire_api = model.wire_api;
            }
        } else {
            merged.push(model);
        }
    }
    *current = merged;
}

fn with_provider_option(
    mut options: vibex_core::ProviderOptions,
    key: &str,
    value: Option<String>,
) -> vibex_core::ProviderOptions {
    options.entries.retain(|entry| entry.key != key);
    if let Some(value) = value
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty())
    {
        options.entries.push(vibex_core::ProviderBindingMetadata {
            key: key.to_string(),
            value,
        });
    }
    options
}

fn native_import_status_is_eligible(status: vibex_core::ProviderNativeImportItemStatus) -> bool {
    matches!(
        status,
        vibex_core::ProviderNativeImportItemStatus::Importable
            | vibex_core::ProviderNativeImportItemStatus::NeedsSecretSetup
            | vibex_core::ProviderNativeImportItemStatus::Partial
    )
}

fn provider_option_value<'a>(
    options: &'a vibex_core::ProviderOptions,
    key: &str,
) -> Option<&'a str> {
    options
        .entries
        .iter()
        .find(|entry| entry.key == key)
        .map(|entry| entry.value.trim())
        .filter(|value| !value.is_empty())
}

fn cc_switch_import_identity(options: &vibex_core::ProviderOptions) -> Option<String> {
    let db_path = provider_option_value(options, PROVIDER_OPTION_CC_SWITCH_DB_PATH)?;
    let provider_id = provider_option_value(options, PROVIDER_OPTION_CC_SWITCH_PROVIDER_ID)?;
    let app_type = provider_option_value(options, PROVIDER_OPTION_CC_SWITCH_APP_TYPE)?;
    Some(format!("{db_path}\0{provider_id}\0{app_type}"))
}

fn pending_cc_switch_import_item_ids(
    preview: &vibex_core::ProviderNativeImportPreview,
    existing_profiles: &[vibex_core::ProviderProfile],
    target_agent_id: &AgentId,
) -> Vec<vibex_core::RequestId> {
    let imported_identities = existing_profiles
        .iter()
        .filter(|profile| &profile.agent_id == target_agent_id)
        .filter_map(|profile| cc_switch_import_identity(&profile.provider_options))
        .collect::<HashSet<_>>();
    let mut seen_item_ids = HashSet::new();

    preview
        .items
        .iter()
        .filter(|item| item.agent_id.as_ref() == Some(target_agent_id))
        .filter(|item| {
            item.source == vibex_core::ProviderNativeImportSource::CcSwitch
                || provider_option_value(&item.provider_options, PROVIDER_OPTION_NATIVE_SOURCE)
                    == Some("cc-switch")
        })
        .filter(|item| native_import_status_is_eligible(item.status))
        .filter(|item| {
            cc_switch_import_identity(&item.provider_options)
                .is_none_or(|identity| !imported_identities.contains(&identity))
        })
        .filter(|item| seen_item_ids.insert(item.import_item_id.as_str().to_string()))
        .map(|item| item.import_item_id.clone())
        .collect()
}

/// Explains why a cc-switch import produced no work for `target_agent_id`.
///
/// A single `provider_native_import_no_candidate` covered four unrelated
/// situations, so the UI could only say "operation failed". Most of them are
/// ordinary states rather than failures — CC Switch is not installed, has no
/// record for this Agent, or has nothing left to import — and the user asked
/// for those to read as plain notices instead of error alerts. Only candidates
/// that exist but cannot be parsed are a real failure.
enum NativeImportEmptyReason {
    /// Nothing to import; reported as an informational notice.
    Notice { code: &'static str, message: String },
    /// Candidates exist, but none of them can be imported.
    Failure { code: &'static str, message: String },
}

impl NativeImportEmptyReason {
    /// The task outcome the UI should show for this reason.
    fn into_task_result(self) -> VibexResult<ManagementTaskSuccess> {
        match self {
            Self::Notice { code, message } => {
                tracing::debug!(
                    code,
                    "native provider import found nothing to import; reporting a notice"
                );
                Ok(ManagementTaskSuccess::from(message))
            }
            Self::Failure { code, message } => Err(VibexError::validation(code, message)),
        }
    }
}

fn native_import_empty_reason(
    preview: &vibex_core::ProviderNativeImportPreview,
    target_agent_id: &AgentId,
    locale: ResolvedLocale,
) -> NativeImportEmptyReason {
    let label = vibex_core::builtin_agent_definitions()
        .into_iter()
        .find(|definition| &definition.id == target_agent_id)
        .map(|definition| definition.label)
        .unwrap_or_else(|| target_agent_id.as_str().to_string());
    let cc_switch_items = preview
        .items
        .iter()
        .filter(|item| item.agent_id.as_ref() == Some(target_agent_id))
        .filter(|item| {
            item.source == vibex_core::ProviderNativeImportSource::CcSwitch
                || provider_option_value(&item.provider_options, PROVIDER_OPTION_NATIVE_SOURCE)
                    == Some("cc-switch")
        })
        .collect::<Vec<_>>();

    if cc_switch_items.is_empty() {
        if preview
            .diagnostics
            .iter()
            .any(|diagnostic| diagnostic.code == "provider_native_import_cc_switch_missing")
        {
            return NativeImportEmptyReason::Notice {
                code: "provider_native_import_cc_switch_missing",
                message: match locale {
                    ResolvedLocale::En => {
                        "The CC Switch provider database was not found".to_string()
                    }
                    ResolvedLocale::ZhCn => "未找到 CC Switch 数据库，无法导入配置".to_string(),
                    ResolvedLocale::ZhTw => "未找到 CC Switch 資料庫，無法匯入設定".to_string(),
                },
            };
        }
        return NativeImportEmptyReason::Notice {
            code: "provider_native_import_agent_not_in_cc_switch",
            message: match locale {
                ResolvedLocale::En => {
                    format!("CC Switch has no provider configuration for {label}")
                }
                ResolvedLocale::ZhCn => format!("CC Switch 中没有 {label} 的供应商配置"),
                ResolvedLocale::ZhTw => format!("CC Switch 中沒有 {label} 的供應商設定"),
            },
        };
    }

    if cc_switch_items
        .iter()
        .any(|item| native_import_status_is_eligible(item.status))
    {
        return NativeImportEmptyReason::Notice {
            code: "provider_native_import_already_imported",
            message: match locale {
                ResolvedLocale::En => {
                    format!("Every {label} provider in CC Switch is already imported")
                }
                ResolvedLocale::ZhCn => format!("{label} 的 CC Switch 供应商配置已全部导入"),
                ResolvedLocale::ZhTw => format!("{label} 的 CC Switch 供應商設定已全部匯入"),
            },
        };
    }

    NativeImportEmptyReason::Failure {
        code: "provider_native_import_blocked",
        message: match locale {
            ResolvedLocale::En => {
                format!("Every {label} provider in CC Switch is blocked by a parse error")
            }
            ResolvedLocale::ZhCn => {
                format!("{label} 在 CC Switch 中的供应商配置存在解析错误，无法导入")
            }
            ResolvedLocale::ZhTw => {
                format!("{label} 在 CC Switch 中的供應商設定存在解析錯誤，無法匯入")
            }
        },
    }
}

