/// A section heading inside the market's detail panel.
///
/// `actions` are shortcuts that answer the whole section at once — they sit on
/// the heading's trailing edge rather than under the list, because they act on
/// the section as a whole and the list is what deserves the vertical space.
fn management_market_section(
    title: &'static str,
    description: Option<&'static str>,
    actions: Option<AnyElement>,
    content: AnyElement,
    cx: &App,
) -> AnyElement {
    v_flex()
        .w_full()
        .min_w_0()
        .gap_2()
        .child(
            h_flex()
                .w_full()
                .min_w_0()
                .items_start()
                .gap_2()
                .child(
                    v_flex()
                        .min_w_0()
                        .flex_1()
                        .gap(px(2.0))
                        .child(div().text_sm().font_semibold().child(title))
                        .children(description.map(|description| {
                            div()
                                .text_xs()
                                .text_color(cx.theme().muted_foreground)
                                .child(description)
                        })),
                )
                .children(actions),
        )
        .child(content)
        .into_any_element()
}

/// The enable-for section both market install forms share.
///
/// The rows are the ones the resource's own detail panel draws — the Agent's
/// glyph, its label, its id, and a switch — so a scope chosen during install
/// reads exactly like the one edited afterwards. The two shortcuts on the
/// heading are the whole answer in one click, which is what most installs want.
fn management_market_enablement_section(
    id_prefix: &'static str,
    agents: Vec<AgentSnapshotEntry>,
    selected: &BTreeSet<String>,
    pending: bool,
    on_toggle: impl Fn(&mut ManagementCenter, &str, bool, &mut Window, &mut Context<ManagementCenter>)
    + Clone
    + 'static,
    on_set_all: impl Fn(&mut ManagementCenter, bool, &mut Window, &mut Context<ManagementCenter>)
    + Clone
    + 'static,
    cx: &mut Context<ManagementCenter>,
) -> AnyElement {
    let mut rows = v_flex().w_full().gap_1();
    let mut any_agent = false;
    for agent in agents.into_iter().filter(|agent| agent.added) {
        any_agent = true;
        let agent_id = agent.id.as_str().to_string();
        let checked = selected.contains(&agent_id);
        let toggle = on_toggle.clone();
        let toggle_id = agent_id.clone();
        rows = rows.child(
            h_flex()
                .w_full()
                .min_w_0()
                .items_center()
                .gap_2()
                .rounded(px(6.0))
                .border_1()
                .border_color(cx.theme().border.opacity(0.60))
                .px_2()
                .py_2()
                .child(management_agent_glyph(
                    agent.id.as_str(),
                    &agent.label,
                    false,
                    cx,
                ))
                .child(
                    v_flex()
                        .min_w_0()
                        .flex_1()
                        .gap_1()
                        .child(
                            div()
                                .truncate()
                                .text_sm()
                                .font_medium()
                                .child(agent.label.clone()),
                        )
                        .child(
                            div()
                                .truncate()
                                .text_xs()
                                .text_color(cx.theme().muted_foreground)
                                // A scope chosen here is the user's own answer,
                                // which is the same thing the detail panel calls
                                // `manual` once it is saved.
                                .child(format!("{} · manual", agent.id)),
                        ),
                )
                .child(
                    Switch::new(SharedString::from(format!("{id_prefix}-agent-{agent_id}")))
                        .small()
                        .checked(checked)
                        .disabled(pending)
                        .on_click(cx.listener(move |this, checked, window, cx| {
                            toggle(this, &toggle_id, *checked, window, cx);
                        })),
                ),
        );
    }

    let enable_all = on_set_all.clone();
    let disable_all = on_set_all;
    let actions = h_flex()
        .flex_none()
        .items_center()
        .gap_1()
        .child(
            Button::new(SharedString::from(format!("{id_prefix}-enable-all")))
                .xsmall()
                .ghost()
                .label(management_locale_text("Enable all", "全部启用", "全部啟用"))
                .disabled(pending)
                .on_click(
                    cx.listener(move |this, _, window, cx| enable_all(this, true, window, cx)),
                ),
        )
        .child(
            Button::new(SharedString::from(format!("{id_prefix}-disable-all")))
                .xsmall()
                .ghost()
                .label(management_locale_text(
                    "Disable all",
                    "全部取消",
                    "全部取消",
                ))
                .disabled(pending)
                .on_click(
                    cx.listener(move |this, _, window, cx| disable_all(this, false, window, cx)),
                ),
        );

    management_market_section(
        management_locale_text("Enable for", "启用范围", "啟用範圍"),
        Some(management_locale_text(
            "The Agents that may use this once it is saved.",
            "保存后可以使用该资源的 Agent。",
            "儲存後可以使用該資源的 Agent。",
        )),
        Some(actions.into_any_element()),
        if any_agent {
            rows.into_any_element()
        } else {
            div()
                .w_full()
                .text_sm()
                .text_color(cx.theme().muted_foreground)
                .child(management_locale_text(
                    "No Agent has been added yet, so this will be saved without one.",
                    "尚未添加任何 Agent，该资源将不带启用范围保存。",
                    "尚未新增任何 Agent，該資源將不帶啟用範圍儲存。",
                ))
                .into_any_element()
        },
        cx,
    )
}

/// The identity band at the top of a market detail panel.
///
/// The link to the entry's own page rides on the title row rather than under
/// the description: it belongs to the entry's identity, and putting it there
/// keeps the description free to be read on its own.
#[allow(clippy::too_many_arguments)]
fn management_market_detail_header(
    glyph: AnyElement,
    name: String,
    state: Option<MarketEntryState>,
    meta: Option<String>,
    description: Option<String>,
    link: Option<AnyElement>,
    cx: &App,
) -> AnyElement {
    let identity = div()
        .min_w_0()
        .flex_1()
        .truncate()
        .text_lg()
        .font_semibold()
        .child(name);
    v_flex()
        .w_full()
        .min_w_0()
        .gap_2()
        .child(
            h_flex()
                .w_full()
                .min_w_0()
                .items_start()
                .gap_3()
                .child(glyph)
                .child(
                    v_flex()
                        .min_w_0()
                        .flex_1()
                        .gap(px(2.0))
                        .child(
                            h_flex()
                                .w_full()
                                .min_w_0()
                                .gap_2()
                                .child(identity)
                                .children(
                                    state
                                        .as_ref()
                                        .map(|state| management_market_state_tag(state, cx)),
                                ),
                        )
                        .children(meta.map(|meta| {
                            div()
                                .w_full()
                                .min_w_0()
                                .truncate()
                                .text_xs()
                                .text_color(cx.theme().muted_foreground)
                                .child(meta)
                        })),
                )
                .children(link),
        )
        .children(description.map(|description| {
            div()
                .w_full()
                .text_sm()
                .text_color(cx.theme().muted_foreground)
                .child(description)
        }))
        .into_any_element()
}

/// The toolbar above a market grid: a query field, the one command that re-runs
/// the search, and the filters that narrow the result underneath.
///
/// The filters sit on their own line rather than beside the field: they narrow
/// the answer the query already produced, so they read as a second, quieter
/// decision under the search instead of competing with it for the same row.
fn management_market_toolbar(
    search_id: &'static str,
    query_input: &Entity<InputState>,
    loading: bool,
    disabled: bool,
    on_search: impl Fn(&ClickEvent, &mut Window, &mut App) + 'static,
    filters: Option<AnyElement>,
    cx: &App,
) -> AnyElement {
    v_flex()
        .w_full()
        .min_w_0()
        .flex_none()
        // The grid below reserves the overlay scrollbar's lane, so this row
        // reserves the same one: the search field and the cards share a right
        // edge instead of ending 12px apart.
        .pr(SCROLLBAR_GUTTER)
        .gap_2()
        .child(
            h_flex()
                .w_full()
                .min_w_0()
                .items_center()
                .gap_2()
                .child(div().min_w(px(220.0)).flex_1().child(
                    Input::new(query_input).w_full().cleanable(true).prefix(
                        Icon::new(IconName::Search).text_color(cx.theme().muted_foreground),
                    ),
                ))
                .child(
                    Button::new(search_id)
                        // The icon slot is what shows the button's progress: while
                        // the request is in flight the spinner takes the place of
                        // the glyph, so the search says it is working in the same
                        // place the user pressed.
                        .small()
                        .outline()
                        .h(MANAGEMENT_SIDEBAR_CONTROL_HEIGHT)
                        .px_4()
                        .icon(IconName::Search)
                        .label(management_locale_text("Search", "搜索", "搜尋"))
                        .loading(loading)
                        .disabled(disabled)
                        .on_click(on_search),
                ),
        )
        .children(filters)
        .into_any_element()
}

/// The transport filter as a row of mutually exclusive chips.
///
/// "All" is a chip of its own rather than an absence of selection, so the
/// current narrowing is always visible and always reversible from the same
/// place it was applied.
fn management_market_transport_filters(
    id_prefix: &'static str,
    selected: Option<MarketTransportFilter>,
    disabled: bool,
    on_select: impl Fn(&Option<MarketTransportFilter>, &mut Window, &mut App) + 'static,
    cx: &App,
) -> AnyElement {
    let on_select = std::rc::Rc::new(on_select);
    let mut row = h_flex()
        .min_w_0()
        .flex_none()
        .gap_1()
        .child(management_option_chip(
            SharedString::from(format!("{id_prefix}-all")),
            SharedString::from(management_locale_text("All", "全部", "全部")),
            selected.is_none(),
            disabled,
            None,
            {
                let on_select = on_select.clone();
                move |_, window, cx| on_select(&None, window, cx)
            },
            cx,
        ));
    for filter in MARKET_TRANSPORT_FILTERS {
        let checked = selected == Some(filter);
        row = row.child(management_option_chip(
            SharedString::from(format!("{id_prefix}-{filter:?}")),
            SharedString::from(filter.label()),
            checked,
            disabled,
            None,
            {
                let on_select = on_select.clone();
                move |_, window, cx| on_select(&Some(filter), window, cx)
            },
            cx,
        ));
    }
    row.into_any_element()
}

/// The way back out of a market view.
///
/// The market replaces the section body, so it owns the affordance that
/// returns to whatever the sidebar had selected rather than leaving the
/// sidebar buttons as the only exit.
fn management_market_back_button(
    id: &'static str,
    label: &'static str,
    on_click: impl Fn(&ClickEvent, &mut Window, &mut App) + 'static,
) -> AnyElement {
    Button::new(id)
        .small()
        .ghost()
        .icon(IconName::ArrowLeft)
        .label(label)
        .on_click(on_click)
        .into_any_element()
}
fn management_option_chip(
    id: SharedString,
    label: SharedString,
    checked: bool,
    disabled: bool,
    tooltip: Option<SharedString>,
    on_click: impl Fn(&bool, &mut Window, &mut App) + 'static,
    cx: &App,
) -> AnyElement {
    let foreground = if checked {
        cx.theme().foreground
    } else {
        cx.theme().muted_foreground
    };
    Toggle::new(id)
        .xsmall()
        .checked(checked)
        .disabled(disabled)
        .border_1()
        // An unavailable chip keeps saying which answer is current and only
        // steps back, so a disabled group is still readable as a group.
        .border_color(match (checked, disabled) {
            (true, _) => cx.theme().primary.opacity(0.55),
            (false, true) => cx.theme().border.opacity(0.55),
            (false, false) => cx.theme().border,
        })
        .bg(if checked {
            cx.theme().primary.opacity(0.14)
        } else {
            cx.theme().transparent
        })
        .text_color(if disabled {
            foreground.opacity(0.55)
        } else {
            foreground
        })
        .when(checked, |chip| chip.font_weight(FontWeight::MEDIUM))
        .when_some(tooltip, |chip, tooltip| chip.tooltip(tooltip))
        .label(label)
        .on_click(on_click)
        .into_any_element()
}

/// The caption over a row of choices inside the Model editor.
///
/// Smaller and quieter than a field label, because it names a group of controls
/// rather than one value, and the chips under it carry their own labels.
fn management_choice_group_label(label: &'static str, cx: &App) -> AnyElement {
    div()
        .w_full()
        .text_xs()
        .font_weight(FontWeight::MEDIUM)
        .text_color(cx.theme().muted_foreground)
        .child(label)
        .into_any_element()
}

/// The context-window sizes the Model editor offers as one click.
const MANAGEMENT_CONTEXT_TOKEN_PRESETS: [u64; 5] = [128_000, 200_000, 256_000, 512_000, 1_000_000];
/// The max-output sizes the Model editor offers as one click.
const MANAGEMENT_OUTPUT_TOKEN_PRESETS: [u64; 6] = [4_000, 8_000, 16_000, 32_000, 64_000, 128_000];

/// The count a quick-value chip is labelled with: `128k`, `1M`, or the number.
fn management_token_count_label(tokens: u64) -> String {
    if tokens >= 1_000_000 && tokens.is_multiple_of(1_000_000) {
        format!("{}M", tokens / 1_000_000)
    } else if tokens >= 1_000 && tokens.is_multiple_of(1_000) {
        format!("{}k", tokens / 1_000)
    } else {
        tokens.to_string()
    }
}

/// The count a token field currently holds, when it holds one.
fn current_token_field(state: &Entity<InputState>, cx: &App) -> Option<u64> {
    state.read(cx).value().trim().parse::<u64>().ok()
}

/// A token-count field with the quick values the user can click instead.
///
/// The chips sit between the label and the input because they are shortcuts to
/// the value the field holds rather than a second answer: the label names what is
/// being chosen, the chips are the common counts, and the field stays the place
/// any other count is typed.
fn management_token_field(
    label: impl Into<SharedString>,
    state: &Entity<InputState>,
    error: Option<&str>,
    presets: &'static [u64],
    id_prefix: String,
    pending: bool,
    cx: &mut Context<ManagementCenter>,
) -> AnyElement {
    let label: SharedString = label.into();
    let mut input = Input::new(state).small().w_full();
    if error.is_some() {
        input = input.border_color(cx.theme().danger);
    }
    let current = current_token_field(state, cx);
    v_flex()
        .w_full()
        .min_w_0()
        .gap_1()
        .child(
            Form::new().child(
                Field::new().label(label).child(
                    v_flex()
                        .w_full()
                        .gap_1p5()
                        .child(management_token_preset_row(
                            &id_prefix, presets, current, pending, state, cx,
                        ))
                        .child(input),
                ),
            ),
        )
        .children(error.map(|message| management_field_error(message.to_string(), cx)))
        .into_any_element()
}

/// A row of quick counts for a token field.
///
/// Clicking a chip writes its count into the field below, which stays the place
/// any other count is typed; clicking the chip that is already current clears
/// the field again, so "not declared" is reachable without the keyboard. The
/// field is the answer either way — the chip is a shortcut, not a second value.
fn management_token_preset_row(
    id_prefix: &str,
    presets: &[u64],
    current: Option<u64>,
    pending: bool,
    input: &Entity<InputState>,
    cx: &mut Context<ManagementCenter>,
) -> AnyElement {
    let mut row = h_flex().w_full().flex_wrap().gap_1p5();
    for preset in presets {
        let preset = *preset;
        let selected = current == Some(preset);
        let input = input.clone();
        row = row.child(management_option_chip(
            SharedString::from(format!("{id_prefix}-{preset}")),
            SharedString::from(management_token_count_label(preset)),
            selected,
            pending,
            // Only the current chip has something extra to say; the rest are
            // named by the counts they write.
            selected.then(|| {
                SharedString::from(management_locale_text(
                    "Click again to clear",
                    "再次点击清除",
                    "再次點擊清除",
                ))
            }),
            cx.listener(move |this, _, window, cx| {
                let value = if selected {
                    String::new()
                } else {
                    preset.to_string()
                };
                input.update(cx, |state, cx| state.set_value(value, window, cx));
                this.apply_profile_model_edit(cx);
            }),
            cx,
        ));
    }
    row.into_any_element()
}

/// One entry of the declared-levels field.
///
/// The chips read levels out of the field and write them back, so an entry the
/// vocabulary does not name is kept as the text the user wrote rather than being
/// dropped by the next click, and a level's wire spelling survives a toggle.
#[derive(Debug, Clone, PartialEq, Eq)]
enum ReasoningLevelEntry {
    Level {
        level: vibex_core::ProviderReasoningEffortLevel,
        wire: Option<String>,
    },
    Raw(String),
}

impl ReasoningLevelEntry {
    fn level(&self) -> Option<vibex_core::ProviderReasoningEffortLevel> {
        self.level_and_wire().map(|(level, _)| level)
    }

    fn level_and_wire(&self) -> Option<(vibex_core::ProviderReasoningEffortLevel, Option<String>)> {
        match self {
            Self::Level { level, wire } => Some((*level, wire.clone())),
            Self::Raw(_) => None,
        }
    }

    /// The entry as the field spells it: `level`, `level=wire`, or the raw text.
    fn declaration(&self) -> String {
        match self {
            Self::Level { level, wire } => match wire {
                Some(wire) if wire != level.as_str() => format!("{level}={wire}"),
                _ => level.as_str().to_string(),
            },
            Self::Raw(text) => text.clone(),
        }
    }
}

/// Splits the declared-levels field into the entries the chips read.
fn reasoning_level_entries(text: &str) -> Vec<ReasoningLevelEntry> {
    text.split(',')
        .map(str::trim)
        .filter(|entry| !entry.is_empty())
        .map(|entry| {
            let (name, wire) = match entry.split_once('=') {
                Some((name, wire)) => (name.trim(), Some(wire.trim().to_string())),
                None => (entry, None),
            };
            match vibex_core::ProviderReasoningEffortLevel::parse(name) {
                Some(level) => ReasoningLevelEntry::Level { level, wire },
                None => ReasoningLevelEntry::Raw(entry.to_string()),
            }
        })
        .collect()
}

/// Adds a level to the declaration, or takes it back out when it is there.
///
/// Levels keep escalation order, which is the order the declaration is stored
/// and shown in, and each keeps the wire spelling it was written with. An entry
/// the vocabulary does not name keeps its own text and its own place, and an
/// emptied declaration is the "follow the Agent default" answer.
fn toggled_reasoning_levels(text: &str, level: vibex_core::ProviderReasoningEffortLevel) -> String {
    let entries = reasoning_level_entries(text);
    let mut levels = entries
        .iter()
        .filter_map(ReasoningLevelEntry::level_and_wire)
        .collect::<Vec<_>>();
    match levels.iter().position(|(current, _)| *current == level) {
        Some(index) => {
            levels.remove(index);
        }
        None => levels.push((level, None)),
    }
    levels.sort_by_key(|(level, _)| *level);

    // The levels take the slots the declared ones held, so raw entries stay
    // where the user wrote them; a level that was just added has no slot and
    // lands after them.
    let mut remaining = levels.into_iter();
    let mut ordered = Vec::with_capacity(entries.len() + 1);
    for entry in entries {
        match entry {
            ReasoningLevelEntry::Level { .. } => {
                if let Some((level, wire)) = remaining.next() {
                    ordered.push(ReasoningLevelEntry::Level { level, wire });
                }
            }
            raw => ordered.push(raw),
        }
    }
    ordered.extend(remaining.map(|(level, wire)| ReasoningLevelEntry::Level { level, wire }));
    ordered
        .iter()
        .map(ReasoningLevelEntry::declaration)
        .collect::<Vec<_>>()
        .join(", ")
}

/// A disclosure header: a quiet caption row that opens the content below it.
///
/// Collapsed by default so a rarely used group does not push the frequent
/// fields off the dialog's first screen.
fn profile_editor_disclosure(
    id: &'static str,
    label: SharedString,
    open: bool,
    trailing: Option<AnyElement>,
    cx: &mut Context<ManagementCenter>,
) -> AnyElement {
    let icon = if open {
        IconName::ChevronDown
    } else {
        IconName::ChevronRight
    };
    h_flex()
        .id(id)
        .w_full()
        .min_w_0()
        .items_center()
        .gap_2()
        .child(
            Button::new(SharedString::from(format!("{id}-toggle")))
                .xsmall()
                .ghost()
                .compact()
                .icon(Icon::new(icon).size_3p5())
                .label(label)
                .on_click(
                    cx.listener(move |this, _, _, cx| {
                        this.toggle_profile_editor_disclosure(id, cx)
                    }),
                ),
        )
        .children(trailing)
        .into_any_element()
}

fn provider_wire_api_label(wire_api: vibex_core::ProviderModelWireApi) -> &'static str {
    match wire_api {
        vibex_core::ProviderModelWireApi::OpenaiResponses => "OpenAI Responses",
        vibex_core::ProviderModelWireApi::OpenaiChatCompletions => "Chat Completions",
        vibex_core::ProviderModelWireApi::AnthropicMessages => "Anthropic Messages",
        vibex_core::ProviderModelWireApi::GoogleGenerativeAi => "Google Generative AI",
        vibex_core::ProviderModelWireApi::GoogleVertex => "Google Vertex AI",
        vibex_core::ProviderModelWireApi::AwsBedrockConverse => "AWS Bedrock Converse",
    }
}

fn provider_interface_integration_label(
    kind: vibex_core::AgentModelInterfaceIntegrationKind,
) -> &'static str {
    match kind {
        vibex_core::AgentModelInterfaceIntegrationKind::Direct => {
            management_locale_text("Direct", "直接支持", "直接支援")
        }
        vibex_core::AgentModelInterfaceIntegrationKind::Bridged => {
            management_locale_text("Bridged", "协议桥接", "協定橋接")
        }
    }
}

fn provider_protocol_url_override_label(wire_api: vibex_core::ProviderModelWireApi) -> String {
    let protocol = provider_wire_api_label(wire_api);
    match locale::current_locale() {
        ResolvedLocale::En => format!("{protocol} URL override"),
        ResolvedLocale::ZhCn => format!("{protocol} URL 覆盖"),
        ResolvedLocale::ZhTw => format!("{protocol} URL 覆寫"),
    }
}

/// The three lines a management sidebar row can say about its resource.
struct ManagementResourceRowText {
    /// The resource's own name.
    title: String,
    /// Where it came from and how it connects.
    subtitle: String,
    /// How many Agents have it turned on.
    enabled_count: String,
}

/// One installed resource in a management sidebar.
///
/// It is the card the Agent sidebar draws — 8px radius, hairline border, a
/// leading glyph, a title line, and one muted line under it — so the three
/// sidebars read as one list instead of three separate designs. Selection is a
/// tinted surface rather than an outline box, which keeps the eye on one spine
/// down the rows.
fn management_resource_row(
    id: SharedString,
    glyph_path: &'static str,
    text: ManagementResourceRowText,
    enabled: bool,
    selected: bool,
    on_activate: impl Fn(&mut ManagementCenter, &mut Window, &mut Context<ManagementCenter>)
    + Clone
    + 'static,
    cx: &mut Context<ManagementCenter>,
) -> AnyElement {
    let ManagementResourceRowText {
        title,
        subtitle,
        enabled_count: enabled_count_label,
    } = text;
    // "Enabled" is the expected state, so it stays quiet; only a resource that
    // cannot be used says so. The label is localized: the row used to print the
    // projection's own `enabled`/`disabled` key.
    let status_tag = (!enabled).then(|| {
        Tag::warning()
            .xsmall()
            .child(management_locale_text("Disabled", "已停用", "已停用"))
    });
    let accessible_label = format!(
        "{title}, {}, {subtitle}, {enabled_count_label}",
        if enabled {
            management_locale_text("Enabled", "已启用", "已啟用")
        } else {
            management_locale_text("Disabled", "已停用", "已停用")
        }
    );

    let click = on_activate.clone();
    let keyboard = on_activate;
    v_flex()
        .id(id)
        .role(Role::Button)
        .aria_label(accessible_label)
        .focusable()
        .tab_index(0)
        .cursor_pointer()
        .relative()
        .w_full()
        .min_w_0()
        .gap_1()
        .overflow_hidden()
        .rounded(px(8.0))
        .border_1()
        // One selected treatment for the whole sidebar: the market entry button
        // and a chosen resource row both answer "which view is the body on", so
        // they take the same primary boundary and wash. The row used to drop its
        // border when chosen, which made the current row look less defined than
        // the ones around it.
        .border_color(if selected {
            cx.theme().primary.opacity(0.45)
        } else {
            cx.theme().border.opacity(0.65)
        })
        .bg(if selected {
            cx.theme().primary.opacity(0.12)
        } else {
            cx.theme().background.opacity(0.70)
        })
        .px_2()
        .py_2()
        .hover(|style| {
            style.bg(if selected {
                cx.theme().primary.opacity(0.12)
            } else {
                cx.theme().accent
            })
        })
        .on_click(cx.listener(move |this, _, window, cx| click(this, window, cx)))
        .on_key_down(cx.listener(move |this, event: &KeyDownEvent, window, cx| {
            if event.keystroke.key == "enter" || event.keystroke.key == "space" {
                keyboard(this, window, cx);
                cx.stop_propagation();
            }
        }))
        .child(
            h_flex()
                .w_full()
                .min_w_0()
                .items_center()
                .gap_1()
                .child(management_resource_sidebar_glyph(glyph_path, selected, cx))
                .child(
                    h_flex()
                        .flex_1()
                        .min_w_0()
                        .h(px(28.0))
                        .px_1()
                        .child(
                            div()
                                .min_w_0()
                                .truncate()
                                .text_sm()
                                .font_medium()
                                .child(title),
                        )
                        .children(status_tag)
                        .child(div().flex_1()),
                ),
        )
        .child(
            div()
                .pl(px(40.0))
                .truncate()
                .text_xs()
                .text_color(cx.theme().muted_foreground)
                .child(format!("{subtitle} · {enabled_count_label}")),
        )
        .into_any_element()
}

/// The header of a management sidebar: the resource name and the commands that
/// add one.
///
/// The commands are labelled buttons rather than icon-only controls: creating
/// and importing are the two ways a resource enters the list, and a glyph alone
/// does not say which is which. The count that used to sit beside the title is
/// gone — the list under it already answers how many there are.
fn management_resource_sidebar_actions(
    title: &'static str,
    actions: Vec<AnyElement>,
    cx: &App,
) -> AnyElement {
    h_flex()
        .w_full()
        .min_w_0()
        .items_center()
        .gap_2()
        .child(
            div()
                .min_w_0()
                .flex_1()
                .truncate()
                // The section name sits on the same 14px scale as the commands
                // beside it and the search field under it; at 12px it read as a
                // caption for the row rather than the name of the list.
                .text_sm()
                .font_semibold()
                .text_color(cx.theme().muted_foreground)
                .child(title),
        )
        .children(actions)
        .into_any_element()
}

/// A sidebar command: an icon and the verb it performs, sized to the control
/// band it sits in rather than to the toolbar scale.
///
/// The visible label is the short verb; the tooltip and the accessible name
/// carry the full object, because "New" in a sidebar says which sidebar and
/// "New MCP server" says what is about to be created.
fn management_sidebar_action(
    id: &'static str,
    icon: Icon,
    label: &'static str,
    accessible_label: &'static str,
    on_click: impl Fn(&ClickEvent, &mut Window, &mut App) + 'static,
) -> AnyElement {
    let accessible_label = SharedString::from(accessible_label);
    button_with_aria_label(
        Button::new(id)
            .small()
            .outline()
            .h(MANAGEMENT_SIDEBAR_CONTROL_HEIGHT)
            .px_3()
            // The glyph is drawn as content rather than through `icon()`: the
            // kit derives that slot from the button size, which would pin it to
            // the small 14px while the label already owns that scale.
            .child(
                h_flex()
                    .items_center()
                    .gap_1p5()
                    .child(icon.size(px(16.0)))
                    .child(div().text_sm().child(label)),
            )
            .tooltip(accessible_label.clone())
            .on_click(on_click),
        accessible_label,
    )
    .into_any_element()
}

/// The one button that opens a market from its sidebar.
///
/// It stays visibly engaged while the market is showing, so the sidebar always
/// answers which view the section body is on.
fn management_market_entry_button(
    id: &'static str,
    label: &'static str,
    open: bool,
    on_click: impl Fn(&ClickEvent, &mut Window, &mut App) + 'static,
    cx: &App,
) -> AnyElement {
    Button::new(id)
        // The same control band as the New and Import commands above it and the
        // search field below: one height, one type scale.
        .small()
        .w_full()
        .h(MANAGEMENT_SIDEBAR_CONTROL_HEIGHT)
        .px_3()
        .child(
            // The button's own content row centers what it is given, so the
            // left alignment has to be claimed by a full-width child rather
            // than by `justify_start` on the button itself.
            h_flex()
                .w_full()
                .items_center()
                .gap_1p5()
                .child(
                    Icon::default()
                        .path("icons/vibex/package.svg")
                        .size(px(16.0)),
                )
                .child(div().text_sm().child(label)),
        )
        .when(open, |button| {
            button
                .border_1()
                .border_color(cx.theme().primary.opacity(0.45))
                .bg(cx.theme().primary.opacity(0.12))
        })
        .on_click(on_click)
        .into_any_element()
}

fn management_resource_sidebar_glyph(path: &'static str, selected: bool, cx: &App) -> AnyElement {
    let (surface, foreground) = if selected {
        (
            cx.theme().primary.opacity(0.16),
            cx.theme().foreground.opacity(0.92),
        )
    } else {
        (cx.theme().muted.opacity(0.30), cx.theme().muted_foreground)
    };
    div()
        // The same 36px plate the Agent cards lead with, so the glyphs of all
        // three sidebars land on one vertical line.
        .size(px(36.0))
        .flex_none()
        .flex()
        .items_center()
        .justify_center()
        .rounded(cx.theme().radius)
        .bg(surface)
        .child(
            Icon::default()
                .path(path)
                .size(px(16.0))
                .text_color(foreground),
        )
        .into_any_element()
}

