fn management_search_input(
    state: &Entity<InputState>,
    cx: &mut Context<ManagementCenter>,
) -> AnyElement {
    // `Input` owns its border, background and focus ring; the search field only
    // adds the leading glyph and a clear affordance. It keeps the kit's medium
    // size rather than the compact one: a search field is the primary control in
    // these sidebars, and `Input::h` is a multi-line-only setter, so the size is
    // the only honest way to make it taller than a toolbar strip.
    Input::new(state)
        .w_full()
        .cleanable(true)
        .prefix(Icon::new(IconName::Search).text_color(cx.theme().muted_foreground))
        .into_any_element()
}

fn management_input_field(
    label: impl Into<SharedString>,
    state: &Entity<InputState>,
    masked: bool,
    cx: &mut Context<ManagementCenter>,
) -> AnyElement {
    management_input_field_with_error(label, state, masked, None, cx)
}

/// A labeled field that also reports its own problem.
///
/// The message sits directly under the control it belongs to, so a rejected
/// value is visible without scrolling back to a status line at the end of the
/// dialog.
fn management_input_field_with_error(
    label: impl Into<SharedString>,
    state: &Entity<InputState>,
    masked: bool,
    error: Option<&str>,
    cx: &mut Context<ManagementCenter>,
) -> AnyElement {
    let label: SharedString = label.into();
    let mut input = Input::new(state).small().w_full();
    if masked {
        input = input.mask_toggle();
    }
    if error.is_some() {
        input = input.border_color(cx.theme().danger);
    }
    v_flex()
        .w_full()
        .min_w_0()
        .gap_1()
        .child(Form::new().child(Field::new().label(label).child(input)))
        .children(error.map(|message| management_field_error(message.to_string(), cx)))
        .into_any_element()
}

/// A labeled read-only field for a value the Agent owns. It mirrors
/// `management_input_field`'s shape so the form keeps its rhythm, renders the
/// value in a muted box instead of an editable input, and carries a Help
/// affordance explaining why the value cannot be changed.
fn management_locked_field(
    label: impl Into<SharedString>,
    value: impl Into<SharedString>,
    help: impl Into<SharedString>,
    cx: &mut Context<ManagementCenter>,
) -> AnyElement {
    let label: SharedString = label.into();
    let value: SharedString = value.into();
    let help: SharedString = help.into();
    Form::new()
        .child(
            Field::new().label(label).child(
                h_flex()
                    .w_full()
                    .min_w_0()
                    .items_center()
                    .gap_1p5()
                    .child(
                        div()
                            .flex_1()
                            .min_w_0()
                            .h_6()
                            .px_2()
                            .flex()
                            .items_center()
                            .overflow_hidden()
                            .rounded(cx.theme().radius)
                            .border_1()
                            .border_color(cx.theme().border)
                            .bg(cx.theme().muted.opacity(0.3))
                            .text_sm()
                            .text_color(cx.theme().muted_foreground)
                            .child(value),
                    )
                    .child(
                        div()
                            .id("management-locked-field-help")
                            .flex_none()
                            .p_1()
                            .cursor_default()
                            .focusable()
                            .tab_stop(true)
                            .role(Role::Button)
                            .aria_label(help.clone())
                            .child(
                                Icon::new(IconName::Info)
                                    .size_3p5()
                                    .text_color(cx.theme().muted_foreground),
                            )
                            .tooltip(move |window, cx| {
                                Tooltip::new(help.clone()).build(window, cx)
                            }),
                    ),
            ),
        )
        .into_any_element()
}

/// A labeled editor section: a muted section caption over a hairline rule,
/// followed by the section content. Keeps long dialog forms scannable.
fn profile_editor_section(
    label: &'static str,
    trailing: Option<AnyElement>,
    content: AnyElement,
    cx: &App,
) -> AnyElement {
    v_flex()
        .w_full()
        .min_w_0()
        .gap_2p5()
        .child(
            h_flex()
                .w_full()
                .min_w_0()
                .items_center()
                .gap_2()
                .child(
                    div()
                        .flex_none()
                        .text_xs()
                        .font_weight(FontWeight::SEMIBOLD)
                        // Brighter than a hint but quieter than a field label:
                        // the caption names a region, it does not label a value.
                        .text_color(cx.theme().foreground.opacity(0.85))
                        .child(label),
                )
                .child(
                    div()
                        .flex_1()
                        .h(px(1.0))
                        .rounded_full()
                        .bg(cx.theme().border),
                )
                .children(trailing),
        )
        .child(content)
        .into_any_element()
}

/// Placeholder cards for the Agent list while the catalog is still loading.
///
/// Each one copies the real row's box model — the 8px radius, the hairline
/// border, `px_2`/`py_2`, the 28px title row, and `gap_1` — so the cards that
/// replace them land on the same pitch. The list is gated on
/// `loading && snapshot.agents.is_empty()`, so a refresh that already has rows
/// keeps them.
fn management_agent_card_placeholders(cx: &App) -> Vec<AnyElement> {
    (0..MANAGEMENT_AGENT_LOADING_CARDS)
        .map(|_| {
            v_flex()
                .w_full()
                .gap_1()
                .overflow_hidden()
                .rounded(px(8.0))
                .border_1()
                .border_color(cx.theme().border.opacity(0.65))
                .bg(cx.theme().background.opacity(0.70))
                .px_2()
                .py_2()
                .child(
                    h_flex()
                        .h(px(28.0))
                        .items_center()
                        .px_1()
                        .child(skeleton::skeleton_bar(12.0, 0.42, cx)),
                )
                .child(skeleton::skeleton_bar(14.0, 0.60, cx))
                .into_any_element()
        })
        .collect()
}

/// Placeholder rows for the MCP and Skill sidebars while the snapshot loads.
///
/// Both lists are cards at [`MANAGEMENT_PROVIDER_ROW_HEIGHT`] with an 8px
/// radius, a hairline border, and a 36px leading glyph beside a title and a
/// subtitle line — the same shape the Agent sidebar uses — so the rows that
/// replace these land on the same pitch.
fn management_resource_placeholders(cx: &App) -> Vec<AnyElement> {
    (0..MANAGEMENT_RESOURCE_LOADING_ROWS)
        .map(|_| {
            h_flex()
                .w_full()
                .min_w_0()
                .h(px(MANAGEMENT_PROVIDER_ROW_HEIGHT))
                .flex_none()
                .items_center()
                .gap_2()
                .rounded(px(8.0))
                .border_1()
                .border_color(cx.theme().border.opacity(0.70))
                .bg(cx.theme().background.opacity(0.70))
                .px(px(10.0))
                .py_2()
                .child(skeleton::skeleton_bar(36.0, 0.09, cx))
                .child(
                    v_flex()
                        .min_w_0()
                        .flex_1()
                        .gap(px(2.0))
                        .child(skeleton::skeleton_bar(12.0, 0.44, cx))
                        .child(skeleton::skeleton_bar(10.0, 0.30, cx)),
                )
                .into_any_element()
        })
        .collect()
}

/// Placeholder rows for the provider configuration list.
///
/// Rows use [`MANAGEMENT_PROVIDER_ROW_HEIGHT`] and
/// [`MANAGEMENT_PROVIDER_ROW_GAP`], the same pitch the real provider rows are
/// laid out on, so the list does not resize when the snapshot lands.
fn management_provider_placeholders(cx: &App) -> Vec<AnyElement> {
    (0..MANAGEMENT_PROVIDER_LOADING_ROWS)
        .map(|_| {
            h_flex()
                .w_full()
                .min_w_0()
                .h(px(MANAGEMENT_PROVIDER_ROW_HEIGHT))
                .flex_none()
                .items_center()
                .gap_3()
                .rounded(px(8.0))
                .border_1()
                .border_color(cx.theme().border.opacity(0.70))
                .bg(cx.theme().background.opacity(0.70))
                .px_3()
                .child(skeleton::skeleton_bar(18.0, 0.04, cx))
                .child(
                    v_flex()
                        .min_w_0()
                        .flex_1()
                        .gap_1()
                        .child(skeleton::skeleton_bar(12.0, 0.36, cx))
                        .child(skeleton::skeleton_bar(10.0, 0.52, cx)),
                )
                .child(skeleton::skeleton_bar(20.0, 0.08, cx))
                .into_any_element()
        })
        .collect()
}

/// Icon, title, and description of the compact management empty state.
fn compact_empty_state_header(
    title: &'static str,
    description: &'static str,
    cx: &App,
) -> EmptyHeader {
    EmptyHeader::new()
        .media(
            EmptyMedia::new()
                .with_variant(EmptyMediaVariant::Icon)
                .mb_0()
                .size(px(28.0))
                .rounded(px(7.0))
                .bg(cx.theme().muted.opacity(0.45))
                .child(
                    Icon::new(IconName::Inbox)
                        .size(px(15.0))
                        .text_color(cx.theme().muted_foreground),
                ),
        )
        .title(EmptyTitle::new().child(title))
        .description(
            EmptyDescription::new()
                .max_w(px(280.0))
                .text_xs()
                .child(description),
        )
}

/// Icon, title, and description of the full-detail management empty state.
fn detail_empty_state_header(
    title: &'static str,
    description: &'static str,
    cx: &App,
) -> EmptyHeader {
    EmptyHeader::new()
        .media(
            EmptyMedia::new()
                .with_variant(EmptyMediaVariant::Icon)
                .mb_0()
                .size(px(40.0))
                .rounded(px(10.0))
                .bg(cx.theme().muted.opacity(0.45))
                .child(
                    Icon::new(IconName::Inbox)
                        .size(px(20.0))
                        .text_color(cx.theme().muted_foreground),
                ),
        )
        .title(EmptyTitle::new().font_semibold().child(title))
        .description(
            EmptyDescription::new()
                .max_w(px(360.0))
                .text_xs()
                .child(description),
        )
}

fn compact_empty_state(
    title: &'static str,
    description: &'static str,
    cx: &mut Context<ManagementCenter>,
) -> AnyElement {
    solid_empty_border(
        EmptyState::new()
            .flex_none()
            .gap_1p5()
            .rounded(px(8.0))
            .border_1()
            .border_color(cx.theme().border.opacity(0.70))
            .bg(cx.theme().background.opacity(0.60))
            .p_3(),
    )
    .header(compact_empty_state_header(title, description, cx))
    .into_any_element()
}

/// The same empty state without its own box, for a region that already has a
/// boundary — a pane, an inspector, or another card.
///
/// It grows into whatever room the region has, so an empty pane reads as
/// deliberately empty rather than as content that failed to load.
fn bare_empty_state(
    title: &'static str,
    description: &'static str,
    cx: &mut Context<ManagementCenter>,
) -> AnyElement {
    EmptyState::new()
        .min_h_0()
        .gap_1p5()
        .p_3()
        .header(compact_empty_state_header(title, description, cx))
        .into_any_element()
}

fn detail_empty_state(
    title: &'static str,
    description: &'static str,
    cx: &mut Context<ManagementCenter>,
) -> AnyElement {
    solid_empty_border(
        EmptyState::new()
            .gap_2()
            .min_h(px(220.0))
            .rounded(px(8.0))
            .border_1()
            .border_color(cx.theme().border)
            .bg(theme::semantic_color("card", cx.theme().is_dark()).opacity(0.55)),
    )
    .header(detail_empty_state_header(title, description, cx))
    .into_any_element()
}

