    #[test]
    fn agent_mutations_are_keyed_by_their_target_agent() {
        for (mutation, expected) in [
            (ManagementMutation::AgentToggle("codex".into()), "codex"),
            (
                ManagementMutation::AgentToggle("add:claude".into()),
                "claude",
            ),
            (
                ManagementMutation::AgentToggle("probe:opencode".into()),
                "opencode",
            ),
            (
                ManagementMutation::AgentAuth {
                    agent_id: "auggie".into(),
                    action: "browser-login".into(),
                },
                "auggie",
            ),
            (ManagementMutation::AgentInstall("pi".into()), "pi"),
            (
                ManagementMutation::AgentUpdateCheck("gemini".into()),
                "gemini",
            ),
            (ManagementMutation::AgentUninstall("kiro".into()), "kiro"),
        ] {
            assert_eq!(mutation.concurrent_agent_id(), Some(expected));
        }
        assert_eq!(
            ManagementMutation::AgentDiscovery.concurrent_agent_id(),
            None
        );
        assert_eq!(
            ManagementMutation::ProfileCreate.concurrent_agent_id(),
            None
        );

        let mut pending = BTreeMap::new();
        pending.insert(
            "codex".to_string(),
            ManagementMutation::AgentInstall("codex".into()),
        );
        assert!(pending.contains_key("codex"));
        assert!(!pending.contains_key("claude"));
    }

    #[test]
    fn added_managed_agents_stay_on_the_download_surface_until_installation_finishes() {
        use vibex_core::{AgentManagedInstallState, AgentManagedInstallStatus};

        for status in [
            AgentManagedInstallStatus::NotInstalled,
            AgentManagedInstallStatus::Installing,
            AgentManagedInstallStatus::Upgrading,
        ] {
            let state = AgentManagedInstallState {
                status,
                ..AgentManagedInstallState::not_installed()
            };
            assert!(management_agent_installation_pending(true, &state));
        }
        for status in [
            AgentManagedInstallStatus::Installed,
            AgentManagedInstallStatus::UpdateAvailable,
            AgentManagedInstallStatus::Failed,
            AgentManagedInstallStatus::Uninstalling,
        ] {
            let state = AgentManagedInstallState {
                status,
                ..AgentManagedInstallState::not_installed()
            };
            assert!(!management_agent_installation_pending(true, &state));
        }

        assert!(!management_agent_installation_pending(
            false,
            &AgentManagedInstallState::not_installed()
        ));
        assert!(!management_agent_installation_pending(
            true,
            &AgentManagedInstallState::external()
        ));
    }

