    /// The registry publishes a full RFC3339 instant; a card only wants the day.
    #[test]
    fn market_timestamps_reduce_to_a_date() {
        assert_eq!(
            market_timestamp_date("2026-07-27T15:34:57.496953Z").as_deref(),
            Some("2026-07-27")
        );
        assert_eq!(
            market_timestamp_date("2026-07-27").as_deref(),
            Some("2026-07-27")
        );
        // Anything that is not plainly a date is dropped rather than shown raw.
        assert!(market_timestamp_date("").is_none());
        assert!(market_timestamp_date("not a date").is_none());
        assert!(market_timestamp_date("2026/07/27T00:00:00Z").is_none());
    }

    #[test]
    fn market_cards_say_who_published_an_entry_and_what_it_needs() {
        let mut entry = market_entry_for_display();
        let publisher = market_entry_publisher_line(&entry).expect("a publisher line");
        assert!(publisher.contains("io.example"));
        assert!(publisher.contains("2026-07-27"));

        // A variable the registry marked required is called out before the
        // install form is ever opened.
        entry.env = vec![
            vibex_core::MarketEnvRequirement {
                name: "API_KEY".to_string(),
                description: None,
                required: true,
                secret: true,
                default_value: None,
                placeholder: None,
            },
            vibex_core::MarketEnvRequirement {
                name: "REGION".to_string(),
                description: None,
                required: false,
                secret: false,
                default_value: None,
                placeholder: None,
            },
        ];
        let summary = market_entry_env_summary(&entry).expect("a variable summary");
        assert!(summary.contains('1') && summary.contains('2'), "{summary}");
        assert!(market_entry_env_summary(&market_entry_for_display()).is_none());
    }

    #[test]
    fn market_cards_call_out_at_most_one_state() {
        let entry = market_entry_for_display();
        // A healthy, uninstalled entry says nothing: `active` is the normal
        // state and is not worth a tag.
        assert_eq!(market_entry_state(&entry, false), None);
        assert_eq!(
            market_entry_state(&entry, true),
            Some(MarketEntryState::Installed)
        );

        // The publisher's lifecycle outranks the local install, because a
        // deprecated server is exactly where "you already have this" matters
        // less than "it is deprecated".
        let mut deprecated = market_entry_for_display();
        deprecated.status = Some("deprecated".to_string());
        assert_eq!(
            market_entry_state(&deprecated, true),
            Some(MarketEntryState::Deprecated)
        );
        // The lifecycle tags are the ones that shout; "installed" stays quiet.
        assert_ne!(
            MarketEntryState::Installed.label(),
            MarketEntryState::Deprecated.label()
        );

        let mut deleted = market_entry_for_display();
        deleted.status = Some("deleted".to_string());
        assert_eq!(
            market_entry_state(&deleted, false),
            Some(MarketEntryState::Removed)
        );

        // Classification and metadata are separate lanes: what published the
        // launcher and which version it pins never become tags.
        assert_eq!(
            market_entry_meta_line(&entry).as_deref(),
            Some("npm · 1.0.0")
        );
        let mut remote = market_entry_for_display();
        remote.package_kind = Some("remote".to_string());
        remote.version = None;
        assert_eq!(market_entry_meta_line(&remote), None);
    }

    /// The card's own contract, asserted against its source.
    ///
    /// Each of these is a defect the card shipped with, and each one is
    /// invisible in a diff but obvious on screen, so they are pinned here rather
    /// than left to a screenshot.
    #[test]
    fn market_card_stays_a_chooser_rather_than_a_container() {
        let source = include_str!("management.rs");
        let card = source
            .split_once("fn management_market_card(")
            .and_then(|(_, tail)| tail.split_once("\nfn management_market_error_text("))
            .map(|(body, _)| body)
            .expect("market card renderer should remain inspectable");

        // A clamped description without an ellipsis is cut at the wrap point, so
        // the last line ended mid-word with no mark that anything was missing.
        let clamp = card
            .find(".line_clamp(")
            .expect("the description is clamped to keep the grid even");
        assert!(
            card[clamp..].contains(".text_ellipsis()"),
            "a clamped description needs an ellipsis, or it reads as a broken string"
        );

        // The card is not a control, so it must not advertise one. It used to
        // blend its background under the pointer while offering no click.
        assert!(
            !card.contains("on_hover"),
            "the card has no click, so it must not carry a hover state"
        );

        // The footer is separated by spacing. A rule there repeated the card's
        // own boundary one line above itself.
        assert!(
            !card.contains("border_t_1"),
            "the card's footer must not draw a second rule inside the card"
        );

        // Identity owns the strongest type step on the card, because the grid is
        // a name picker.
        assert!(
            card.contains(".text_base()") && card.contains(".font_semibold()"),
            "the entry's name should outrank its body text"
        );
    }

    #[test]
    fn market_grids_page_the_whole_result_set() {
        let source = include_str!("management.rs");
        let renderer = |open: &str, close: &str| {
            source
                .split_once(open)
                .and_then(|(_, tail)| tail.split_once(close))
                .map(|(body, _)| body)
                .unwrap_or_else(|| panic!("{open} should remain inspectable"))
        };
        let mcp = renderer(
            "    fn render_mcp_market(",
            "\n    fn render_mcp_market_install_form(",
        );
        let skills = renderer(
            "    fn render_skills_market(",
            "\n    /// The native-import view",
        );

        // The MCP index holds the whole registry, so the view asks for one page
        // at a time and never cuts a page out of a window it fetched: the count
        // it pages through is the index's own match count.
        assert!(
            mcp.contains("self.mcp_market_total"),
            "the MCP pager should count what the index matched"
        );
        assert!(
            !mcp.contains("market_page_slice("),
            "the MCP market should not slice a fetched window: it pages the index"
        );
        let request = renderer(
            "    fn request_mcp_market(",
            "\n    /// Re-query once the index",
        );
        assert!(
            request.contains("offset: Some("),
            "the MCP request should address the page by offset"
        );
        assert!(
            request.contains("limit: Some(MARKET_PAGE_SIZE as u32)"),
            "the MCP request should ask for exactly one page"
        );
        assert!(
            request.contains("MarketTransportFilter::request_filter"),
            "the transport filter belongs to the index, or paging under it would leave holes"
        );

        // The Skill index ignores the offset outright, so that market fetches
        // one window and pages through it locally.
        assert!(
            skills.contains("market_page_slice("),
            "the Skill market should page the window it fetched"
        );
        assert!(
            skills.contains("market_page("),
            "the Skill market should clamp its page to the window in hand"
        );

        for (open, render) in [("MCP market", mcp), ("Skill market", skills)] {
            assert!(
                render.contains("management_market_pager("),
                "{open} should draw the pager under its grid"
            );
            assert!(
                render.contains(".track_scroll("),
                "{open} should return its grid to the top when the page changes"
            );
            // The pager is the only navigation a grid may offer; a "show more"
            // button would be a second, competing one.
            assert!(!render.contains("Show more"), "{open} still reveals more");
        }

        let pager = source
            .split_once("fn management_market_pager(")
            .and_then(|(_, tail)| tail.split_once("\n/// The exact launcher"))
            .map(|(body, _)| body)
            .expect("the market pager should remain inspectable");
        // The kit's own pager, spanning the strip rather than a lone button.
        assert!(pager.contains("Pagination::new(id)"));
        assert!(pager.contains(".current_page(page)"));
        assert!(pager.contains(".total_pages(market_page_count(total))"));
        assert!(pager.contains(".on_click(on_page)"));
        assert!(pager.contains(".w_full()"));
    }

