    #[test]
    fn agent_setup_and_managed_install_probe_options_but_ordinary_toggle_does_not() {
        let source = include_str!("management.rs");
        let toggle = source
            .split_once("    fn toggle_agent(")
            .and_then(|(_, tail)| tail.split_once("\n    fn set_agent_added("))
            .map(|(body, _)| body)
            .expect("Agent toggle handler should remain inspectable");
        let add = source
            .split_once("    fn set_agent_added(")
            .and_then(|(_, tail)| tail.split_once("\n    fn rollback_managed_agent("))
            .map(|(body, _)| body)
            .expect("Agent add handler should remain inspectable");
        let managed_rollback = source
            .split_once("    fn rollback_managed_agent(")
            .and_then(|(_, tail)| tail.split_once("\n    fn install_managed_agent("))
            .map(|(body, _)| body)
            .expect("managed Agent rollback handler should remain inspectable");
        let managed_install = source
            .split_once("    fn install_managed_agent(")
            .and_then(|(_, tail)| tail.split_once("\n    fn check_managed_agent_update("))
            .map(|(body, _)| body)
            .expect("managed Agent install handler should remain inspectable");
        let discover = source
            .split_once("    fn discover_local_agents(")
            .and_then(|(_, tail)| tail.split_once("\n    fn probe_agent("))
            .map(|(body, _)| body)
            .expect("Agent discovery handler should remain inspectable");
        let detect_after_install = source
            .split_once("    fn probe_agent(")
            .and_then(|(_, tail)| tail.split_once("\n    fn set_default_provider_profile("))
            .map(|(body, _)| body)
            .expect("Agent install detection handler should remain inspectable");

        // Setup paths probe through the backend facade, so ordinary toggles
        // must not reach for the runtime option probe at all.
        assert!(!toggle.contains(".probe_agent_runtime_options("));
        assert_eq!(add.matches(".probe_agent_runtime_options(").count(), 1);
        assert_eq!(
            managed_rollback
                .matches(".probe_agent_runtime_options(")
                .count(),
            1,
            "a rollback changes the Adapter version, so its model catalogue must be re-probed"
        );
        assert_eq!(
            managed_install
                .matches(".probe_agent_runtime_options(")
                .count(),
            1
        );
        assert!(managed_install.contains(".refresh_agent_auth_methods("));
        let selection = source
            .split_once("    fn reconcile_selected_agent(")
            .and_then(|(_, tail)| tail.split_once("\n    fn apply_snapshot("))
            .map(|(body, _)| body)
            .expect("selected Agent reconciliation should remain inspectable");
        assert!(selection.contains("agent.managed_install.managed"));
        assert_eq!(discover.matches(".probe_agent_runtime_options(").count(), 1);
        assert_eq!(
            detect_after_install
                .matches(".probe_agent_runtime_options(")
                .count(),
            1
        );
    }

